,p_lov_name=>'FLOW_SUBSCRIBE_FROM_APP_COMPUTATIONS'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select b.flow_id ||'' ''||f.name||'' - ''|| b.computation_item d,',
