prompt --application/shared_components/user_interface/lovs/p1926_parent_columns
begin
wwv_flow_imp_shared.create_list_of_values(
 p_id=>wwv_flow_imp.id(1825027843432939)
,p_lov_name=>'P1926_PARENT_COLUMNS'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with msgs as (',
'    select wwv_flow_lang_dev.builder_message( ''WWV_FLOW_DATA_PROFILE.ARRAY_COLUMNS'' ) as array_cols_msg,',
'           wwv_flow_lang_dev.builder_message( ''WWV_FLOW_DATA_PROFILE.TABLE_COLUMNS'' ) as table_cols_msg',
'      from sys.dual )',
'select msg.array_cols_msg as column_type,',
'       dpc.display_name,',
'       dpc.id',
'  from wwv_flow_src_arr_cols_dev dpc,',
'       msgs                      msg',
' where dpc.security_group_id = :FLOW_SECURITY_GROUP_ID',
'   and dpc.flow_id           = :FB_FLOW_ID',
'   and dpc.data_profile_id   = :P1926_DATA_PROFILE_ID  ',
'union all ',
'select msg.table_cols_msg as column_type,',
'       dpc.name,',
'       dpc.id',
'  from wwv_flow_data_profile_cols dpc,',
'       msgs                       msg',
' where dpc.security_group_id     = :FLOW_SECURITY_GROUP_ID',
'   and dpc.flow_id               = :FB_FLOW_ID',
'   and dpc.data_profile_id       = :P1926_DATA_PROFILE_ID  ',
'   and dpc.data_type            in ( ''DOCUMENT_FRAGMENT'',''ARRAY'')',
