,p_help_text=>'<p>A splitter dynamically divides the available space for two sub regions horizontally or vertically. The splitter region must have exactly two sub regions. Just about any region template can be used, as long as it has an id attribute, but some will '
||'look better than others. Avoid regions templates with margins or padding. If the region template has an element that wraps the sub regions then a CSS selector that selects the wrapping element must be entered in the Selector property.</p>'
,p_version_identifier=>'1.0'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(349220632388568598)
,p_plugin_id=>wwv_flow_imp.id(330671351658403453)
