,p_plug_source=>'You are on the <strong>Main</strong> version of this application. Please make changes in working copies to prevent conflicts.'
,p_plug_display_condition_type=>'EXPRESSION'
,p_plug_display_when_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'wwv_flow_working_copy_dev.is_main_app (',
'    p_application_id    => :FB_FLOW_ID,',
'    p_security_group_id => :WORKSPACE_ID )',
'and',
'wwv_flow_working_copy_dev.app_has_working_copy (',
