wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(231747163006396029)
,p_process_sequence=>30
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Compute Badge Counts'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select',
'    -- Application Items',
'    to_char(nullif( ',
'    (select count(*)',
'       from wwv_flow_items i',
'      where i.flow_id = :FB_FLOW_ID',
'        and i.security_group_id = :FLOW_SECURITY_GROUP_ID), 0), ''fm999G999G999G999'') as p9_app_items,',
'',
'    -- Application Processes',
'    to_char(nullif( ',
'    (select count(*)',
'       from wwv_flow_processing p',
'      where p.flow_id = :FB_FLOW_ID',
'        and p.security_group_id = :FLOW_SECURITY_GROUP_ID), 0), ''fm999G999G999G999'') as p9_app_processes,',
'',
'    -- Application Computations',
'    to_char(nullif( ',
'    (select count(*) ',
'       from wwv_flow_computations c',
'      where c.flow_id = :FB_FLOW_ID',
'        and c.security_group_id = :FLOW_SECURITY_GROUP_ID), 0), ''fm999G999G999G999'') as p9_app_computations,',
'',
'     -- Application Settings',
'     to_char(nullif( ',
'    (select count(*)',
'       from wwv_flow_app_settings s',
'      where flow_id = :FB_FLOW_ID',
'        and security_group_id = :FLOW_SECURITY_GROUP_ID), 0), ''fm999G999G999G999'') as p9_app_settings,',
'',
'     -- Automations',
'    to_char(nullif( ',
'    (select count(*) ',
'       from wwv_flow_automations a',
'      where a.flow_id = :FB_FLOW_ID ',
'        and a.security_group_id = :FLOW_SECURITY_GROUP_ID), 0), ''fm999G999G999G999'') as p9_automations,',
'',
'     -- Build Options',
'    to_char(nullif( ',
'    (select count(*) ',
'       from wwv_flow_patches b',
'      where b.flow_id = :FB_FLOW_ID ',
'        and b.security_group_id = :FLOW_SECURITY_GROUP_ID), 0), ''fm999G999G999G999'') as p9_build_options,',
'',
'     -- Authentication Schemes',
'    to_char(nullif( ',
'    (select count(*) ',
'       from wwv_flow_authentications a',
'      where a.flow_id = :FB_FLOW_ID',
'        and a.security_group_id = :FLOW_SECURITY_GROUP_ID), 0), ''fm999G999G999G999'') as p9_authn_schemes,',
'',
'     -- Authorization Schemes',
'    to_char(nullif( ',
'    (select count(*) ',
'       from wwv_flow_security_schemes a',
'      where a.flow_id = :FB_FLOW_ID',
'        and a.security_group_id = :FLOW_SECURITY_GROUP_ID), 0), ''fm999G999G999G999'') as p9_authz_schemes,',
'',
'     -- Appplication Access Control Roles',
'    to_char(nullif( ',
'    (select count(*) ',
'       from wwv_flow_fnd_user_groups r',
'      where r.flow_id = :FB_FLOW_ID',
'        and r.security_group_id = :FLOW_SECURITY_GROUP_ID), 0), ''fm999G999G999G999'') as p9_app_access_roles,',
'     ',
'     -- Lists of Values',
'    to_char(nullif( ',
'    (select count(*) ',
'       from wwv_flow_lists_of_values$ l',
'      where flow_id = :FB_FLOW_ID ',
'        and security_group_id = :FLOW_SECURITY_GROUP_ID), 0), ''fm999G999G999G999'') as p9_lovs,',
'',
'     -- Plug-ins',
'    to_char(nullif( ',
'    (select count(*)',
'       from wwv_flow_plugins p',
'      where p.flow_id = :FB_FLOW_ID',
'        and p.security_group_id = :FLOW_SECURITY_GROUP_ID',
'        and p.theme_id is null), 0), ''fm999G999G999G999'') as p9_plugins,',
'     ',
'     -- Shortcuts',
'    to_char(nullif( ',
'    (select count(*) ',
'       from wwv_flow_shortcuts s',
'      where flow_id = :FB_FLOW_ID',
'       and security_group_id = :FLOW_SECURITY_GROUP_ID), 0), ''fm999G999G999G999'') as p9_shortcuts,',
'',
'     -- Email Templates',
'    to_char(nullif( ',
'    (select count(*) ',
'       from wwv_flow_email_templates t',
'      where t.flow_id = :FB_FLOW_ID',
'        and t.security_group_id = :FLOW_SECURITY_GROUP_ID), 0), ''fm999G999G999G999'') as p9_email_templates,',
'     ',
'     -- Lists',
'     to_char(nullif( ',
'    (select count(*) ',
'       from wwv_flow_lists l',
'      where l.flow_id = :FB_FLOW_ID',
'        and l.security_group_id = :FLOW_SECURITY_GROUP_ID), 0), ''fm999G999G999G999'') as p9_lists,',
'     ',
'     -- Breadcrumbs',
'    to_char(nullif( ',
'    (select count(*)',
'       from wwv_flow_menus m',
'      where m.flow_id = :FB_FLOW_ID',
'        and m.security_group_id = :FLOW_SECURITY_GROUP_ID), 0), ''fm999G999G999G999'') as p9_breadcrumbs,',
'    ',
'    -- Search Configs',
'    to_char(nullif( ',
'    (select count(*)',
'       from wwv_flow_search_configs s',
'      where s.flow_id = :FB_FLOW_ID',
'        and s.security_group_id = :FLOW_SECURITY_GROUP_ID), 0), ''fm999G999G999G999'') as p9_search_configs,',
'     ',
'     -- Themes',
'    to_char(nullif( ',
'    (select count(*)',
'       from wwv_flow_themes t',
'      where t.flow_id = :FB_FLOW_ID',
'        and t.security_group_id = :FLOW_SECURITY_GROUP_ID), 0), ''fm999G999G999G999'') as p9_themes,',
'     ',
'     -- Templates',
'    to_char(nullif(',
'    (select sum(cnt)',
'       from ( select count(*) cnt',
'                from wwv_theme_popup_lov_templates t',
'           union all',
'              select count(*) cnt',
'                from wwv_theme_calendar_templates t',
'           union all',
'              select count(*) cnt',
'                from wwv_theme_breadcrumb_templates t',
'           union all',
'              select count(*) cnt',
'                from wwv_theme_button_templates t',
'           union all',
'              select count(*) cnt',
'                from wwv_theme_item_templates t',
'           union all',
'              select count(*) cnt',
'                from wwv_theme_list_templates t',
'           union all',
'              select count(*) cnt',
'                from wwv_theme_report_templates t',
'           union all',
'              select count(*) cnt',
'                from wwv_theme_page_templates t',
'           union all',
'              select count(*) cnt',
'                from wwv_theme_region_templates t',
'           union all',
'              select count(*) cnt',
'                from wwv_theme_template_components p',
'               where p.theme_id is not null',
'       ) ), 0), ''fm999G999G999G999'') as p9_templates,',
'     ',
'     -- Static Application Files',
'      to_char(nullif(',
'    (select count(*)',
'       from wwv_flow_static_files t',
'      where t.flow_id = :FB_FLOW_ID',
'        and t.security_group_id = :FLOW_SECURITY_GROUP_ID), 0), ''fm999G999G999G999'') as p9_app_files,',
'     ',
'     -- Static Workspace Files',
'    to_char(nullif(',
'    (select count(*)',
'       from wwv_flow_company_static_files t',
'      where t.security_group_id = :FLOW_SECURITY_GROUP_ID), 0), ''fm999G999G999G999'') as p9_workspace_files,',
'     ',
'     -- Data Load Definitions',
'    to_char(nullif( ',
'    (select count(*)',
'       from wwv_flow_load_tables l',
'      where l.flow_id = :FB_FLOW_ID',
'        and l.data_profile_id is not null',
'        and l.security_group_id = :FLOW_SECURITY_GROUP_ID), 0), ''fm999G999G999G999'') as p9_data_load_definitions,',
'     ',
'     -- REST Data Sources',
'    to_char(nullif( ',
'    (select count(*)',
'       from wwv_flow_web_src_modules m',
'      where m.flow_id = :FB_FLOW_ID',
'        and m.security_group_id = :FLOW_SECURITY_GROUP_ID), 0), ''fm999G999G999G999'') as p9_rest_data_sources,',
'',
'     -- Duality Views',
'    to_char(nullif( ',
'    (select count(*)',
'       from wwv_flow_duality_view_sources m',
'      where m.flow_id = :FB_FLOW_ID',
'        and m.security_group_id = :FLOW_SECURITY_GROUP_ID), 0), ''fm999G999G999G999'') as p9_duality_views,',
'',
'     -- JSON Sources',
'    to_char(nullif( ',
'    (select count(*)',
'       from wwv_flow_json_sources m',
'      where m.flow_id = :FB_FLOW_ID',
'        and m.security_group_id = :FLOW_SECURITY_GROUP_ID), 0), ''fm999G999G999G999'') as p9_json_sources,',
'     -- Report Queries',
'    to_char(nullif( ',
'    (select count(*)',
'       from wwv_flow_shared_queries q',
'      where q.flow_id           = :FB_FLOW_ID',
'        and q.security_group_id = :FLOW_SECURITY_GROUP_ID), 0), ''fm999G999G999G999'') as p9_report_queries,',
'     ',
'     -- Report Layouts',
'    to_char(nullif( ',
'    (select count(*)',
'       from wwv_flow_report_layouts r',
'      where r.flow_id           = :FB_FLOW_ID',
'        and r.security_group_id = :FLOW_SECURITY_GROUP_ID), 0), ''fm999G999G999G999'') as p9_report_layouts,',
'',
'     -- Text Messages',
'    to_char(nullif( ',
'    (select count(*)',
'       from wwv_flow_messages$ m',
'      where m.flow_id = :FB_FLOW_ID',
'        and m.security_group_id = :FLOW_SECURITY_GROUP_ID), 0), ''fm999G999G999G999'') as p9_text_messages,',
'',
'     -- Text Messages',
'    to_char(nullif( ',
