 p_id=>wwv_flow_imp.id(2017380840377444)
,p_name=>'Active Background Executions'
,p_parent_plug_id=>wwv_flow_imp.id(105124238853)
,p_template=>wwv_flow_imp.id(174794400314076650)
,p_display_sequence=>10
,p_region_template_options=>'#DEFAULT#:a-Region--noPadding:a-Region--simple'
,p_component_template_options=>'#DEFAULT#:a-Report--stretch'
,p_display_point=>'SUB_REGIONS'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select e.id,',
'       p.process_name,',
'       e.status,',
'       e.started_from_session_id,',
'       e.created_on',
'  from wwv_flow_process_bg_execs$ e,',
'       wwv_flow_step_processing   p',
' where p.security_group_id = e.security_group_id',
'   and p.flow_id           = e.flow_id',
'   and p.flow_step_id      = e.page_id',
'   and p.id                = e.process_id',
'    --',
'   and e.security_group_id = :FLOW_SECURITY_GROUP_ID',
'   and e.flow_id           = :FB_FLOW_ID',
'   and e.page_id           = :FB_FLOW_PAGE_ID',
'   and e.status in ( ''SCHEDUED'', ''ENQUEUED'', ''EXECUTING'' )   ',
'   '))
,p_display_when_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select 1',
