 p_id=>wwv_flow_imp.id(1493543391999991810)
,p_plug_name=>'Help'
,p_region_css_classes=>'a-Dialog-textContent'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(208928010704475743)
,p_plug_display_sequence=>10
,p_plug_source=>'<big>The Page Designer is a comprehensive integrated development environment (IDE) used to maintain and enhance pages within your &PRODUCT_NAME. applications.</big>'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(1104689117393514433)
,p_plug_name=>'Page Designer Toolbar'
,p_parent_plug_id=>wwv_flow_imp.id(1493543391999991810)
,p_region_css_classes=>'a-Region--textContent'
,p_region_template_options=>'#DEFAULT#:a-Region--noPadding:a-Region--noBorder'
,p_plug_template=>wwv_flow_imp.id(174794400314076650)
,p_plug_display_sequence=>20
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>The toolbar across the top of Page Designer has a number of capabilities:</p>',
'<ul>',
'  <li><strong>Page Selector</strong> - Displays the current page. You can enter a page number directly, or click on the popup list of values to select a page. </li>',
'  <li><strong>Messages</strong> - When you add a new component to a page, displays current errors and warnings. Clicking a message changes the focus within Property Editor to the corresponding attribute associated with the error or warning.</li>',
'  <li><strong>Page Lock</strong> - Indicates if the page is unlocked (clear), locked by you (red), or locked by another developer (red with person).<br/>',
'    By clicking on this icon you can lock or unlock the page, providing it is not locked by another developer.</li>',
'  <li><strong>Undo Changes</strong> - Click to undo the previous update you made within Page Designer.</li>',
'  <li><strong>Redo Changes</strong> - Click to reapply the last update that was undone using Undo Changes.</li>',
'  <li><strong>Create</strong> - Create new pages, copy pages, create regions, manage shared components, manage page groups, add developer comments, and create Team Development issues.</li>',
'  <li><strong>Utilities</strong> - Delete pages, run Advisor to perform a check, view Caching, view page history, view page checksum, export, enable or disable Tooltips and the Layout tab, or use Layout to toggle between Two Pane and Three Pane mode.'
||'<br/></li>',
'  <li><strong>Shared Components</strong> - Navigate to the Shared Components page.</li>',
'  <li><strong>Save</strong> - Save all changes you have made on the current page.</li>',
'  <li><strong>Save and Run Page</strong> - Save all changes and then run the current page.<br/>',
'    <em>Note: You cannot run modal and non-modal pages directly using Save and Run Page. Instead you need to navigate to a normal page and run the page from there and then navigate within the running application to the modal or non-modal page.</em></'
||'li>',
'</ul><br/>',
'<p><a target="_blank" href="&SYSTEM_HELP_URL.">Learn More ...</a></p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(1498784482317536966)
,p_plug_name=>'Main Panes'
,p_parent_plug_id=>wwv_flow_imp.id(1493543391999991810)
,p_region_css_classes=>'a-Region--textContent'
,p_region_template_options=>'#DEFAULT#:a-Region--noPadding:a-Region--noBorder'
,p_plug_template=>wwv_flow_imp.id(174794400314076650)
,p_plug_display_sequence=>10
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>There are three main panes within Page Designer:</p>',
'<ul>',
'  <li><strong>Left Pane</strong> - Includes tabs for Rendering, Dynamic Actions, Processing, and Shared Components. Each tab displays a list of the corresponding component types and components created on the current page.<br/>',
'    Right-click to access context sensitive menus. You can also drag components up and down within the tree to change the position or sequence of the selected component.</li>',
'  <li><strong>Central Pane</strong> - Includes tabs for Layout, Page Search, and Help.<br/>',
'   <em>Layout</em> shows a visual representation of the page. Add new page components by right-clicking to access a context sensitive menu, or dragging components from the Gallery tab at the bottom and dropping them in the Layout tab.<br/>',
'   <em>Page Search</em> enables you to search all page metadata including regions, items  buttons, dynamic actions, columns, and so on.<br/>',
'   <em>Help</em> displays attribute specific help. Click on the attribute name within Property Editor to view information and examples for that attribute.</li>',
'  <li><strong>Right Pane</strong> - Displays the Property Editor. Use the Property Editor to update attributes for the selected component(s).<br/>',
'    When you select multiple components the Property Editor only displays common attributes. Updating a common attribute will update that attribute for all of the selected components.</li>',
'</ul>',
'<p>&nbsp;</p>',
'<p>You can adjust the size of each pane by selecting and dragging the horizontal and vertical splitters. To expand or collapse each pane, click the small triangle labeled <strong>Collapse</strong> in the center of each splitter.</p>',
'<p><a target="_blank" href="&SYSTEM_HELP_URL.">Learn More ...</a></p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_button(
 p_id=>wwv_flow_imp.id(81564783738352513)
,p_button_sequence=>10
,p_button_plug_id=>wwv_flow_imp.id(153764270703903309)
,p_button_name=>'GET_STARTED'
,p_button_action=>'REDIRECT_URL'
,p_button_template_options=>'#DEFAULT#:a-Button--strongLabel'
,p_button_template_id=>wwv_flow_imp.id(183227826797404355)
,p_button_image_alt=>'Get Started'
,p_button_position=>'NEXT'
,p_button_redirect_url=>'javascript:apex.navigation.openInNewWindow(''https://apex.oracle.com/go/get_started_page_designer'');'
,p_button_css_classes=>'a-Button--dark'
);
end;
