wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(427665843253594857)
,p_name=>'Application Pages'
,p_template=>wwv_flow_imp.id(174794400314076650)
,p_display_sequence=>20
,p_region_template_options=>'#DEFAULT#:a-Region--noPadding:a-Region--accessibleHeader'
,p_component_template_options=>'#DEFAULT#:a-Report--inline:a-Report--staticRowColors:a-Report--stretch:a-Report--rowHighlight'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select p.id,',
'       p.flow_id the_flow,',
'       name page_name,',
'       last_updated_on updated,',
'       to_char(created_on,''YYYY.MM'') created_month,',
'       nvl(l.locked_by,sm.unlocked) locked,',
'       nvl(g.group_name,sm.t_unassigned) group_name,',
'       p.page_type,',
'       decode(p.page_mode,''NORMAL'',sm.apex_mode_normal,''MODAL'',sm.apex_mode_modal,''NON_MODAL'',sm.apex_mode_non_modal) page_mode,',
'       alias,',
'       decode(alias,null,sm.t_no,sm.t_yes) has_alias,',
'       nvl((select name from wwv_flow_templates t where p.STEP_TEMPLATE = t.id and t.security_group_id in ( :WORKSPACE_ID, 11, 12 ) ),sm.apex_default) page_template,',
'       --',
'       nvl(case',
'       when p.required_role = ''MUST_NOT_BE_PUBLIC_USER'' then t_must_not_be_public_user',
'       else (select case when p.required_role like ''!%'' then ''{'' end||',
'                    max(name) ||',
'                    case when p.required_role like ''!%'' then ''}'' end',
'               from wwv_flow_security_schemes s',
'              where s.flow_id = p.flow_id and to_char(s.id) = ltrim(p.required_role,''!''))',
'       end,sm.apex_no_authorization_scheme) authorization_scheme,',
'       --',
'       nvl((select replace(patch_name,'':'',''-'')',
'              from wwv_flow_patches bo',
'             where bo.id = p.required_patch),''No build option'') build_option,',
'       --',
'       decode(',
'           page_is_public_y_n,',
'           ''Y'', sm.t_yes,',
'           ''N'', sm.t_no,',
'           page_is_public_y_n) page_is_public,',
'       decode(',
'           protection_level,',
'           ''D'', sm.no_url_access,',
'           ''N'', sm.unrestricted,',
'           ''U'', sm.no_arguments_allowed,',
'           ''C'', sm.arguments_must_have_checksum,',
'           sm.unrestricted) protection_level,',
'       decode(',
'           cache_mode,',
'           ''NOCACHE'', sm.t_no,',
'           sm.t_yes) cache_page,',
'       nvl(lower(last_updated_by),sm.apex_unknown) last_updated_by,',
'       nvl(lower(created_by),sm.apex_unknown) created_by',
'  from wwv_flow_pages_dev p,',
'       wwv_flow_lock_page l,',
'       (select wwv_flow_lang.system_message(''UNLOCKED'') unlocked,',
'               wwv_flow_lang.system_message(''F4000.YES'') t_yes,',
'               wwv_flow_lang.system_message(''F4000.NO'') t_no,',
'               wwv_flow_lang.system_message(''NO_URL_ACCESS'') no_url_access,',
'               wwv_flow_lang.system_message(''UNRESTRICTED'') unrestricted,',
'               wwv_flow_lang.system_message(''NO_ARGUMENTS_ALLOWED'') no_arguments_allowed,',
'               wwv_flow_lang.system_message(''ARGUMENTS_MUST_HAVE_CHECKSUM'') arguments_must_have_checksum,',
'               wwv_flow_lang.system_message(''Unassigned'') t_unassigned,',
'               wwv_flow_lang.system_message(''MUST_NOT_BE_PUBLIC_USER'') t_must_not_be_public_user,',
'               wwv_flow_lang.system_message(''DEFAULT'') apex_default,',
'               wwv_flow_lang.system_message(''NO_AUTHORIZATION_SCHEME'') apex_no_authorization_scheme,',
'               wwv_flow_lang.system_message(''PE.PROPERTY.PAGE_MODE.LOV.MODAL.D'') apex_mode_modal,',
'               wwv_flow_lang.system_message(''PE.PROPERTY.PAGE_MODE.LOV.NON_MODAL.D'') apex_mode_non_modal,',
'               wwv_flow_lang.system_message(''PE.PROPERTY.PAGE_MODE.LOV.NORMAL.D'') apex_mode_normal,',
'               wwv_flow_lang.system_message(''UNKNOWN'') apex_unknown',
'          from sys.dual) sm,',
'       wwv_flow_page_groups g',
' where p.flow_id           = :FB_FLOW_ID',
'   and p.security_group_id = :FLOW_SECURITY_GROUP_ID',
'   and p.flow_id           = l.flow_id   (+)',
'   and p.id                = l.object_id (+)',
'   and p.group_id          = g.id        (+)'))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(123728124628276646)
,p_query_num_rows=>50
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_no_data_found=>'no data found'
,p_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_query_row_count_max=>100000
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_prn_format=>'PDF'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
