wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(2317966930424404)
,p_name=>'Background Processing'
,p_region_name=>'background_processing'
,p_template=>wwv_flow_imp.id(174794400314076650)
,p_display_sequence=>80
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody'
,p_component_template_options=>'#DEFAULT#:a-Report--stretch'
,p_region_attributes=>'style="width:100%; float:left;"'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select e.id,',
'       e.flow_id,',
'       e.page_id,',
'       p.process_name      bg_process_name,',
'       cp.process_name     child_process_name,',
'       e.status,',
'       e.sofar,',
'       e.totalwork,',
'       e.context_value,',
'       e.created_on,',
'       e.last_updated_on,',
'       case when e.status in ( ''SCHEDULED'', ''EXECUTING'', ''ENQUEUED'' ) then to_char( e.id ) else ''X'' end as terminate_button',
'  from wwv_flow_step_processing p,',
'       wwv_flow_step_processing cp,',
'       wwv_flow_process_bg_execs$ e',
' where p.security_group_id       = e.security_group_id',
'   and p.flow_id                 = e.flow_id',
'   and p.id                      = e.process_id',
'    --',
'   and cp.security_group_id (+)     = e.security_group_id',
'   and cp.flow_id           (+)     = e.flow_id',
'   and cp.id                (+)     = e.current_exec_process_id',
'    --      ',
'   and e.security_group_id       = :FLOW_SECURITY_GROUP_ID',
'   and e.flow_id                 = :FB_FLOW_ID',
'   and e.started_from_session_id = :F4000_FLOW_SESSION',
'    --',
'   and page_id                   = :F4000_P34_PAGE',
'   and status                   in (select /*+ cardinality( t 3 )*/ column_value ',
'                                     from table( wwv_flow_string.split( :P34_BACKGROUND_STATES, '':'') ) t )',
'   and (   :P34_FIND is null',
'       or instr(p.process_name,upper(:P34_FIND)) > 0',
'       or instr(cp.process_name,upper(:P34_FIND)) > 0',
'       or instr(upper(p.process_name),upper(:P34_FIND)) > 0    ',
'       or instr(upper(cp.process_name),upper(:P34_FIND)) > 0 )',
''))
,p_display_when_condition=>'P34_VIEW'
,p_display_when_cond2=>'BG:A'
,p_display_condition_type=>'VALUE_OF_ITEM_IN_CONDITION_IN_COLON_DELIMITED_LIST'
,p_ajax_enabled=>'Y'
