'        p_built_with_love     => false,',
'        p_learn_app_def       => false,',
'        p_learn_existing_apps => false,',
'        p_app_version         => ''Release 1.0''',
'    );',
'',
'    htmldb_util.clear_app_cache( p_app_id => :P56_APP_ID );',
'end;'))
