,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'The Page Designer provides several options for creating new page components.',
'To create regions, items, and buttons you can drag and drop components within the Layout tab in the central pane, or use the context menus within the Rendering tab in the left pane.',
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'TEXT',
  'show_line_breaks', 'N')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(1104687824864514420)
,p_plug_name=>'Creating Regions, Items, and Buttons Using Drag and Drop'
,p_parent_plug_id=>wwv_flow_imp.id(1477171307612322861)
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody:a-Region--simple'
,p_plug_template=>wwv_flow_imp.id(174794400314076650)
,p_plug_display_sequence=>20
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>To drag and drop new components:</p>',
'<ol>',
'  <li>Select the Layout tab in the central pane.</li>',
'  <li>Within the Gallery at the bottom of the pane, select the Region, Item, or Button.</li>',
'  <li>Click and hold the mouse on the component to be created, and drag it into the Layout tab.</li>',
'  <li>Move the component to the desired location within the page and release the mouse.</li>',
'  <li>Enter the appropriate details into the Property Editor.</li>',
'  <li>Click <strong>Save</strong> or <strong>Save and Run Page</strong>.</li>',
'</ol>      ',
'<p><em>Note: Components can only be dropped into appropriate drop zones, shown in yellow, as determined by the component type.',
'  After hovering over an existing drop zone the yellow changes to show a black box in the relevant drop zone.<br/>',
'  If you wish to place the new component next to an existing component then drag the new component to the right, and level, with the existing component, and wait a short period until a new drop zone displays.</em></p>',
'<p>The Layout tab also includes context menus. By selecting a component and right-clicking, you can delete, move, or copy the component to other regions, or new regions on the page.</p>',
'<p><a target="_blank" href="&SYSTEM_HELP_URL.">Learn More ...</a></p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(1104687995506514421)
,p_plug_name=>'Creating Pre-Rendering Branches, Computations and Processes'
,p_parent_plug_id=>wwv_flow_imp.id(1477171307612322861)
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody:a-Region--simple'
,p_plug_template=>wwv_flow_imp.id(174794400314076650)
,p_plug_display_sequence=>40
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>To create branches, computations, and processes that execute before rendering the page:</p>',
'<ol>',
'  <li>Select the Rendering tab in the left pane.</li>',
'  <li>Expand the <strong>Pre-Rendering</strong> node at the top of the Rendering tree.</li>',
'  <li>Right-click Before Header, After Header, Before Regions to display the context menu for that processing point.</li>',
'  <li>Select <strong>Create Branch</strong>, <strong>Create Computation</strong>, or <strong>Create Process</strong>.</li>',
'  <li>Enter the appropriate details into the Property Editor.</li>',
'  <li>Click <strong>Save</strong> or <strong>Save and Run Page</strong>.</li>',
'</ol>',
'<p><em>Note: If you have changed the default display to group components by component type, then must navigate to the Processing tab to maintain pre-rendering components.</em></p>',
'<p>You can also use the context menus to duplicate, delete, and copy a component to other pages.</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(1104688010835514422)
