,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>To create branches, validations, computations, and processes that execute when the page is submitted:</p>',
'<ol>',
'  <li>Select the Processing tab in the left pane.</li>',
'  <li>Navigate to After Submit, Validating, Processing, or After Processing as appropriate within the processing tree.</li>',
'  <li>Right-click the identifier or an existing component to dsipaly the context menu for that procecssing point.</li>',
'  <li>Select <strong>Create Branch</strong>, <strong>Create Validation</strong>, <strong>Create Computation</strong>, or <strong>Create Process</strong>.</li>',
'  <li>Enter the appropriate details into the Property Editor.</li>',
'  <li>Click <strong>Save</strong> or <strong>Save and Run Page</strong>.</li>',
'</ol>',
