,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(770240542605907344)
,p_plug_display_sequence=>100
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>The application could not be installed because it already exists in different workspace.  If you wish to install the application, please do the following:</p>',
'<ol>',
'<li>Remove the existing application from the workspace it currently exists in.</li>',
'</ol>',
'OR',
'<ol>',
'<li>Change the application ID in your export file.  An application ID that''s currently available you can use is &P154_FLOW_ID..</li>',
'<li>Upload the changed export file to the repository, and re-install your application.</li>',
'</ol>'))
,p_plug_display_condition_type=>'FUNCTION_BODY'
,p_plug_display_when_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  l_security_group_id number := null;',
'begin',
'  for c1 in (select security_group_id',
'             from wwv_flows',
'             where id = :P49_NEW_FLOW_ID)',
'  loop',
'    l_security_group_id := c1.security_group_id;',
'  end loop;',
'  if l_security_group_id is not null then',
'    if l_security_group_id != :P49_LOGGED_IN_COMPANY then',
'       return true;    ',
'    end if;',
'  end if;',
'  return false;',
'end;'))
,p_plug_display_when_cond2=>'PLSQL'
