,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'',
'    sys.htp.p( ''<ul class="a-PWIconPicker">'' );',
'    ',
'    for c1 in ( ',
'        select icon_name, ',
'               icon_filters,',
'               trim( regexp_replace(icon_name,''(^fa)|[\-]'','' '') ) as icon_description',
'          from wwv_flow_standard_icons',
'         where icon_library = ''FONTAPEX''',
'         order by icon_name )',
'    loop',
'',
'        sys.htp.p( ''<li class="a-PWIconPicker-item">''',
'            || ''<a href="javascript:void(0)" class="a-PWIconPicker-link" ''',
'            || ''id="'' || c1.icon_name || ''" ''',
'            || ''data-filters="'' || c1.icon_filters || ''" ''',
'            || ''aria-label="'' || wwv_flow_escape.html_attribute( c1.icon_description ) || ''" ''            ',
'            || ''>''',
'            || ''<span class="t-Icon fa '' || c1.icon_name || ''" aria-hidden="true"></span>''',
'            || ''</a></li>'' );',
'    end loop;',
'    ',
'    sys.htp.p( ''</ul>'' );',
'end;'))
,p_plug_source_type=>'NATIVE_PLSQL'
,p_plug_comment=>'TODO - Need to check how server caching can be utilized for this, may be based on theme refresh date?'
);
