wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(1416506952923466)
,p_validation_name=>'No duplicate subscription'
,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_exists     varchar2(255);',
'    l_found_name varchar2(32767);',
'begin',
'    for i in 1..wwv_flow.g_f03.count loop',
'        if wwv_flow.g_f02(i) in (''SUBSCRIBE'') then',
'            -- see if a subscription already exists for the authorization scheme',
'            begin',
'                select name',
'                  into l_exists',
'                  from wwv_flow_security_schemes',
'                 where security_group_id = :WORKSPACE_ID',
'                   and flow_id = :FB_FLOW_ID',
'                   and reference_id = wwv_flow.g_f03(i);',
'',
'                -- if we get here then a duplicate name exists',
'                if l_found_name is null then ',
'                  l_found_name := l_exists;',
'                else ',
'                  l_found_name := l_found_name||'', ''||l_exists;',
'                end if;',
'            exception',
'                when no_data_found then',
'                    -- do nothing if no duplicate exists.',
'                    null; ',
'            end;',
'        end if;',
'    end loop;',
'',
'    if l_found_name is not null then ',
'        return wwv_flow_lang.system_message(''F4000.SEC_SCHEME_SUBSCRIPTION_ALREADY_EXISTS'',',
'                                            l_found_name);',
'    else',
'        return null;',
'    end if;    ',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_when_button_pressed=>wwv_flow_imp.id(186783919387204968)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(4172009398198018)
,p_validation_name=>'No duplicate names'
,p_validation_sequence=>20
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_exists     varchar2(255);',
'    l_found_name varchar2(32767);',
'begin',
'    for i in 1..wwv_flow.g_f03.count loop',
'        if wwv_flow.g_f02(i) in (''Y'', ''SUBSCRIBE'') then',
'            -- see if a subscription already exists for the authorization scheme',
'            begin',
'                select name',
'                  into l_exists',
'                  from wwv_flow_security_schemes',
'                 where security_group_id = :WORKSPACE_ID',
'                   and flow_id = :FB_FLOW_ID',
'                   and name = nvl(wwv_flow.g_f01(i),''Copy of ''||i);',
'',
'                -- if we get here then a duplicate name exists',
'                if l_found_name is null then ',
'                  l_found_name := l_exists;',
'                else ',
'                  l_found_name := l_found_name||'', ''||l_exists;',
'                end if;',
'            exception',
'                when no_data_found then',
'                    -- do nothing if no duplicate exists.',
'                    null; ',
'            end;',
'        end if;',
'    end loop;',
'',
'    if l_found_name is not null then ',
'        return wwv_flow_lang.system_message(''F4000.SEC_SCHEME_NAME_ALREADY_EXISTS'',',
'                                            l_found_name);',
'    else',
'        return null;',
'    end if;    ',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_when_button_pressed=>wwv_flow_imp.id(186783919387204968)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
