wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(186970910581820894)
,p_name=>'F4000_P188_CACHING'
,p_item_sequence=>90
,p_item_plug_id=>wwv_flow_imp.id(186970606141820893)
,p_use_cache_before_default=>'NO'
,p_item_default=>'BY_USER_BY_SESSION'
,p_prompt=>'Validate authorization  scheme:'
,p_source=>'CACHING'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_RADIOGROUP'
,p_named_lov=>'AUTH_SCHEME_CACHING'
,p_lov=>'.'||wwv_flow_imp.id(84860700520374929)||'.'
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_escape_on_http_output=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'Authorization schemes are evaluated on first use in a session.',
'The <em>Validate authorization scheme</em> attribute controls if future uses cause re-evaluations and when a memorized result can be taken instead.',
'The list below describes the available options:',
'</p>',
'<ul>',
'<li><strong>Once per session:</strong> Evaluate only once and always use the memorized result afterwards.</li>',
'<li><strong>Once per page view:</strong> Evaluate once for each request that is processed. Use the memorized result if the authorization scheme is referenced in more than one component on the page.</li>',
'<li><strong>Once per component:</strong> Evaluate once for each component that references the authorization scheme, but save the result in the session. Further requests to render or process the scheme use the memorized result.</li>',
'<li><strong>Always (No Caching):</strong> The authorization scheme will always be evaluated.</li>',
'</ul>',
'<p>',
'The default value <em>Once per session</em> is the most efficient.',
'You should choose another value if the authorization check depends on changing session state or other factors that are not consistent over an entire session.',
'The options <em>Once per component</em> and <em>Always (No Caching)</em> provide additional information about the component that is secured by the authorization scheme.',
'In authorization plugins, you can use the <em>component.type</em>, <em>component.id</em> and <em>component.name</em> attributes of the <em>t_authorization</em> parameter.',
'For the built-in <em>Exists SQL Query</em> and <em>PL/SQL Function</em> scheme types, equivalent bind variables <em>:APP_COMPONENT_TYPE</em>, <em>:APP_COMPONENT_ID</em> and <em>:APP_COMPONENT_NAME</em> are available.',
'</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'number_of_columns', '1',
  'page_action_on_selection', 'NONE')).to_clob
);
