wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1407141969590715)
,p_name=>'P197_AUTO_DISMISS_SUCCESS_MSG'
,p_source_data_type=>'VARCHAR2'
,p_is_required=>true
,p_item_sequence=>40
,p_item_plug_id=>wwv_flow_imp.id(72766345492681456)
,p_item_source_plug_id=>wwv_flow_imp.id(28154408216362812)
,p_item_default=>'N'
,p_prompt=>'Auto Dismiss Success Messages'
,p_source=>'AUTO_DISMISS_SUCCESS_MSG'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_YES_NO'
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>When set to <strong>On</strong>, all success messages in this application will be dismissed automatically after 5 seconds. If a user interacts with a message before it is dismissed, the time will be reset and it will be another 5 seconds before th'
||'e message gets dismissed.</p>',
'<p>When set to <strong>Off</strong>, success messages will remain visible until the application user manually dismisses them.</p>',
'<p>Note that it is important to take into consideration the accessibility impact auto-dismiss could have on users. Some may not see or read a success message before it is dismissed, and could miss the information in the message. If turning auto-dismi'
||'ss on, consider providing users with settings that allow them to opt in or out of auto-dismiss, using the apex.message <code>setDismissPreferences</code> JavaScript API.</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'use_defaults', 'Y')).to_clob
);
