wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(266602103340641101)
,p_name=>'P204_HOT_TEMPLATE'
,p_item_sequence=>150
,p_item_plug_id=>wwv_flow_imp.id(77971829434098596)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Hot Template'
,p_source=>'HOT_TEMPLATE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'PLUGIN_COM.ORACLE.APEX.CODE_EDITOR'
,p_cSize=>100
,p_cMaxlength=>4000
,p_cHeight=>8
,p_tag_attributes=>'onchange="htmldb_item_change(this)"'
,p_field_template=>wwv_flow_imp.id(561549638722251517)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="htmldbInfoBodyP">Defines the button template that displays if the button type is ''Hot''. You have the option of including standard application substitutions. For example, &amp;ITEM_NAME. values can be substituted at rendering time.</div>',
'<div class="htmldbInfoBodyP">Button templates support the following substitution strings:',
'<ul class="noIndent">',
'<li><code>#LABEL#</code> is replaced with a button label.</li>',
'<li><code>#LINK#</code> is replaced with generated JavaScript code to control the button''s behavior. Depending on a button''s action, this code could be either a call to <code>apex.submit</code> to submit the page, a <code>redirect</code> to a page, a'
||' <code>redirect</code> to some other URL supplied, execution of some custom JavaScript or <code>void(0)</code> to do nothing (where the behavior may be defined separately with Dynamic Actions). Note : The <code>#LINK#</code> prefixes the generated Ja'
||'vaScript code with ''javascript:'', so should be used in an <code>href</code> attribute.</li>',
'<li><code>#JAVASCRIPT#</code> is replaced with generated JavaScript code to control the button''s behavior. Depending on a button''s Action, this code could be either a call to <code>apex.submit</code> to submit the page, a <code>redirect</code> to a p'
||'age, a <code>redirect</code> to some other URL supplied, execution of some custom JavaScript or <code>void(0)</code> to do nothing (where the behavior may be defined separately with Dynamic Actions). ',
'<p><strong>Note</strong>: The <code>#JAVASCRIPT#</code> does not prefix the generated JavaScript code with ''javascript:'', so should be used in an <code>onclick</code> attribute.</li>',
'<li><code>#ONCLICK#</code> indicates that the button has an onclick event with JavaScript code, which will be included in a script tag at the bottom of the page.</li>',
'<li><code>#BUTTON_ID#</code> is replaced with the ID for the button. This will be either the button''s Static ID if defined, or if not will be an internally generated ID in the format <pre>''B'' || [Internal Button ID]</pre></li>',
'<li><code>#BUTTON_CSS_CLASSES#</code> is replaced with the button CSS classes property from the button definition.</li>',
'<li><code>#BUTTON_ATTRIBUTES#</code> is replaced with the button attributes property from the button definition.</li>',
'<li><code>#ICON_CSS_CLASSES#</code> is replaced with the icon CSS classes property from the button definition.</li>',
'<li><code>#BUTTON_NAME#</code> is replaced with the name of the button from the button definition.</li>',
'</ul>',
'</div>',
'<div class="htmldbInfoBodyP">All substitution string must be in uppercase.</div>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'HTMLMIXED',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
);
