 p_id=>wwv_flow_imp.id(116570188447819658)
,p_validation_name=>'unique template name'
,p_validation_sequence=>50
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with central_theme as (',
'    select wwv_flow_theme_manager.get_central_application_id( :FB_FLOW_ID, :P204_THEME ) as application_id,',
'           wwv_flow_theme_manager.get_central_theme_id( :FB_FLOW_ID, :P204_THEME )       as theme_id,',
'           wwv_flow_theme_manager.get_central_workspace_id( :FB_FLOW_ID, :P204_THEME )   as workspace_id',
'      from sys.dual',
')',
'',
'select 1',
'  from wwv_flow_button_templates bt,',
'       central_theme ct',
' where ( bt.flow_id, bt.theme_id, bt.security_group_id ) in',
'       (',
'        ( :FB_FLOW_ID, :P204_THEME, :WORKSPACE_ID ),',
'        ( ct.application_id, ct.theme_id, ct.workspace_id )',
'       )',
'   and bt.template_name = :F4000_P204_TEMPLATE_NAME',
'   and bt.id           != :F4000_P204_ID'))
,p_validation_type=>'NOT_EXISTS'
,p_error_message=>'Template name must be unique'
,p_associated_item=>wwv_flow_imp.id(77942316895912737)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
