,p_template=>wwv_flow_imp.id(42025417508627628)
,p_display_sequence=>100
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#:a-Report--stretch'
,p_new_grid_row=>false
,p_display_column=>1
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with central_theme as (',
'    select wwv_flow_theme_manager.get_central_application_id( :F4000_P241_COPY_FROM_FLOW_ID, :P415_COPY_FROM_THEME ) as application_id,',
'           wwv_flow_theme_manager.get_central_theme_id( :F4000_P241_COPY_FROM_FLOW_ID, :P415_COPY_FROM_THEME )       as theme_id,',
'           wwv_flow_theme_manager.get_central_workspace_id( :F4000_P241_COPY_FROM_FLOW_ID, :P415_COPY_FROM_THEME )   as workspace_id',
'      from sys.dual',
')',
'',
'select mt.id,',
'       case',
'           when mt.security_group_id in ( 11, 12 ) then m.theme_repository',
'           else to_char( mt.flow_id )',
'       end flow_id,',
'       mt.name from_name,',
'       wwv_flow_lang.system_message(''F4000.P158.COPY_OF'',mt.name) to_name,',
'       ''N'' sub',
'  from wwv_flow_menu_templates mt,',
'       ( select wwv_flow_lang_dev.builder_message( ''SUBSCRIBED_FROM.THEME_REPOSITORY'' ) theme_repository',
'           from sys.dual ) m,',
'       central_theme ct',
' where ( mt.flow_id, mt.theme_id, mt.security_group_id ) in',
'       (',
'           ( :F4000_P241_COPY_FROM_FLOW_ID, :P415_COPY_FROM_THEME, :WORKSPACE_ID ),',
'           ( ct.application_id, ct.theme_id, ct.workspace_id )',
'       )'))
