wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(142984030433945447)
,p_name=>'P253_INSTALL_OPTION'
,p_item_sequence=>70
,p_item_plug_id=>wwv_flow_imp.id(47632929379498968)
,p_use_cache_before_default=>'NO'
,p_item_default=>'CREATE'
,p_display_as=>'NATIVE_HIDDEN'
,p_display_when=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select 1 ',
'  from wwv_flow_themes ',
' where flow_id = :P253_NEW_FLOW_ID ',
'   and security_group_id = :WORKSPACE_ID',
'   and theme_id = :P253_ORIGINAL_THEME_ID ',
'   and :p253_original_theme_id != ( select nvl(theme_id,-1) from wwv_flows where id = :P253_NEW_FLOW_ID )'))
,p_display_when_type=>'EXISTS'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Refreshing a theme updates the theme and template definition of the current theme with the definition of the imported theme. This requires that both themes are compatible and use matching theme and template identifiers.</p>',
'<p>Creating a new theme installs the imported theme alongside the current theme, allowing to switch from the old theme to the new theme and manually mapping templates.</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'value_protected', 'Y')).to_clob
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(143018502916051053)
,p_name=>'P253_ACTION'
,p_item_sequence=>80
,p_item_plug_id=>wwv_flow_imp.id(47632929379498968)
,p_use_cache_before_default=>'NO'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_original_theme_id number := wwv_flow_imp_parser.get_theme_id( :P253_FILE_ID );',
'begin',
'    if :P253_NEW_FLOW_ID is null and :P253_INSTALL_OPTION is null then',
'        for c1 in (',
'            select 1 from wwv_flow_themes ',
'             where flow_id           = :FB_FLOW_ID ',
'               and theme_id          = l_original_theme_id',
'               and security_group_id = :WORKSPACE_ID',
'               and not exists (',
'                    select 1 from wwv_flows ',
'                     where id                = :FB_FLOW_ID ',
'                       and security_group_id = :WORKSPACE_ID',
'                       and nvl(theme_id,-1)  = l_original_theme_id) ) ',
'        loop',
'            :P253_INSTALL_OPTION := ''REPLACE'';',
'            return wwv_flow_lang.system_message(''F4000.THEME_IMPORT_REPLACE'',:FB_FLOW_ID);',
'        end loop;',
'',
'        :P253_INSTALL_OPTION := ''CREATE'';',
'',
'        return wwv_flow_lang.system_message(''F4000.THEME_IMPORT_CREATE'',:FB_FLOW_ID);',
'    elsif :P253_NEW_FLOW_ID is not null and :P253_INSTALL_OPTION is null then',
'        for c1 in (',
'            select 1 from wwv_flow_themes ',
'             where flow_id           = :P253_NEW_FLOW_ID ',
'               and theme_id          = l_original_theme_id',
'               and security_group_id = :WORKSPACE_ID',
'               and not exists (',
'                   select 1 from wwv_flows ',
'                    where id                = :P253_NEW_FLOW_ID ',
'                      and security_group_id = :WORKSPACE_ID',
'                      and nvl(theme_id,-1)  = l_original_theme_id) ) ',
'        loop',
'            :P253_INSTALL_OPTION := ''REPLACE'';',
'            return wwv_flow_lang.system_message(''F4000.THEME_IMPORT_REPLACE'',:P253_NEW_FLOW_ID);',
'        end loop;',
'        ',
'        :P253_INSTALL_OPTION := ''CREATE'';',
'        ',
'        return wwv_flow_lang.system_message(''F4000.THEME_IMPORT_CREATE'',:P253_NEW_FLOW_ID);',
'    elsif :P253_NEW_FLOW_ID is not null and :P253_INSTALL_OPTION is not null then',
'        for c1 in (',
'            select 1 from wwv_flow_themes ',
'             where flow_id           = :P253_NEW_FLOW_ID ',
'               and theme_id          = l_original_theme_id',
'               and security_group_id = :WORKSPACE_ID',
'               and not exists (',
'                    select 1 from wwv_flows ',
'                    where id                = :P253_NEW_FLOW_ID ',
'                      and security_group_id = :WORKSPACE_ID',
'                      and nvl(theme_id,-1)  = l_original_theme_id)) ',
'        loop',
'            if :P253_INSTALL_OPTION = ''CREATE'' then',
'                return wwv_flow_lang.system_message(''F4000.THEME_IMPORT_CREATE'',:P253_NEW_FLOW_ID);',
'            else',
'                return wwv_flow_lang.system_message(''F4000.THEME_IMPORT_REPLACE'',:P253_NEW_FLOW_ID);',
'            end if;',
'        end loop;',
'          ',
'        :P253_INSTALL_OPTION := ''CREATE'';',
'        ',
'        return wwv_flow_lang.system_message(''F4000.THEME_IMPORT_CREATE'',:P253_NEW_FLOW_ID);  ',
'    elsif :P253_NEW_FLOW_ID is null and :P253_INSTALL_OPTION is not null  then',
'        :P253_INSTALL_OPTION := null;',
'        return null;',
'    end if;',
'',
'    return null;',
'end;'))
,p_source_type=>'FUNCTION_BODY'
,p_source_language=>'PLSQL'
,p_display_as=>'NATIVE_HIDDEN'
,p_help_text=>'Identifies file version.'
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'value_protected', 'Y')).to_clob
);
