wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(2346347639058255)
,p_name=>'F4000_P258_ROW_TEMPLATE1'
,p_item_sequence=>140
,p_item_plug_id=>wwv_flow_imp.id(2346347660092590)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Column Template 1'
,p_source=>'ROW_TEMPLATE1'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'PLUGIN_COM.ORACLE.APEX.CODE_EDITOR'
,p_cSize=>90
,p_cMaxlength=>32767
,p_cHeight=>4
,p_tag_attributes=>'onchange="htmldb_item_change(this)"'
,p_field_template=>wwv_flow_imp.id(561549638722251517)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="htmldbInfoBodyP">Defines the column template. You can use these substitution strings here:',
'<ul class="noIndent">',
'<li>#COLUMN_VALUE# - Will be replaced with the value of a column</li>',
'<li>#ALIGNMENT# - Specified by the user, determines the alignment of a column</li>',
'<li>#COLNUM# - Current Column Number</li>',
'<li>#COLUMN_HEADER# - Column Header</li>',
'<li>#COLCOUNT# - Number of Columns</li>',
'<li>#ROWNUM# - Current Row Number</li>',
'<li>#ACCESSIBLE_HEADERS# - Adds the row and column headers for the cell</li>',
'</ul>',
'</div>',
'<div class="htmldbInfoBodyP">A typical example would be:</div>',
'<pre>&lt;td #ALIGNMENT#&gt;#COLUMN_VALUE#&lt;/td&gt;</pre>',
'',
'<div class="instructiontext">You can define up to four column templates, each of which can be conditional.  For example, you can have different background colors for even and odd rows, or highlight rows which meet a PL/SQL defined condition.</div>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'HTMLMIXED',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
);
