,p_field_template=>wwv_flow_imp.id(561549638722251517)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="htmldbInfoBodyP">Used only when the column condition is set to Use Based on PL/SQL Expression. Enables you to format columns based on the data in that row.</div>',
'<div class="htmldbInfoBodyP">For example, if you wanted to display a value in bold if the salary was greater than 2000, you could use the following row template condition:</div>',
'<pre>',
':SAL &gt; 2000',
'</pre>',
'<div class="htmldbInfoBodyP">Note that column names should be referenced using bind variable syntax, that is, use :SAL rather than #SAL#. You can also use the substitution string #ROWNUM# here.</div>'))
