,p_item_plug_id=>wwv_flow_imp.id(28562360017818729)
,p_use_cache_before_default=>'NO'
,p_item_default=>'<table>'
,p_prompt=>'Before Rows'
,p_source=>'ROW_TEMPLATE_BEFORE_ROWS'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'PLUGIN_COM.ORACLE.APEX.CODE_EDITOR'
,p_cSize=>90
,p_cMaxlength=>32767
,p_cHeight=>3
,p_tag_attributes=>'onchange="htmldb_item_change(this)"'
,p_field_template=>wwv_flow_imp.id(561549638722251517)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Enter HTML which will be displayed one time at the beginning of a report template.</p>',
'<p>The most common use of this attribute is to open an HTML table:</p>',
'<pre>&lt;table&gt;</pre>',
'<p>If you want to display pagination above the reports, your template needs to specify the following substitution string:</p>',
'<pre>#TOP_PAGINATION#</pre>',
'<p>The #TOP_PAGINATION# substitution string will generate HTML which starts with an opening &lt;tr&gt; tag and ends with a closing &lt;/tr&gt; tag.  Ideally, you would include an open table tag and #TOP_PAGINATION# substitution string like so:</p>',
'<pre>&lt;table&gt;#TOP_PAGINATION#</pre>',
'<p>You can use the substitution string #CSV_LINK# if you wish to support exporting your report to CSV format for use in spreadsheets.</p>',
'<p>You can also use the substitution string #REPORT_ATTRIBUTES#.  This substitution string is set per report region on the report attributes page.</p>',
'<p>You can also use the substitution string #COMPONENT_CSS_CLASSES#.  This substitution string is set on the region edit page</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'HTMLMIXED',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
);
