wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1094586706434933036)
,p_name=>'P258_JAVASCRIPT_FILE_URLS'
,p_item_sequence=>20
,p_item_plug_id=>wwv_flow_imp.id(1094586653151933035)
,p_use_cache_before_default=>'NO'
,p_prompt=>'FILE URLs'
,p_source=>'JAVASCRIPT_FILE_URLS'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXTAREA'
,p_cSize=>96
,p_cMaxlength=>4000
,p_cHeight=>3
,p_field_template=>wwv_flow_imp.id(561549638722251517)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Enter JavaScript file URLs for code to be loaded on this page. Each URL has to be written into a new line. If you provide a minified version of your file you can use the substitution string <code>#MIN#</code> to include <code>.min</code> or <code>'
||'#MIN_DIRECTORY#</code> to include <code>minified/</code> in your file URL for a regular page view and an empty string if the page is viewed in debug mode. You also have access to the substitution string <code>#APP_VERSION#</code> if you want to inclu'
||'de the application''s version in the file URL.</p>',
'',
'<p>Note: You do not need to include opening or closing <code>script</code> tags. Just write the URL.',
'',
'<p>',
'Examples:',
'<ul>',
'  <li>Standard file reference',
'      <pre>/myjs/main.js</pre>',
'  </li>',
'  <li>Standard file reference which loads the minified file main.min.js from /myjs/minified/ for regular page views and main.js from /myjs/ in debug mode.',
'      <pre>/myjs/#MIN_DIRECTORY#main#MIN#.js</pre>',
'  </li>',
'  <li>Use this syntax if the library is also used from a RequireJS require call. The define name must match what is used in the requirejs.config paths and the value must be the global symbol exposed by the library. Only applies when using RequireJS. '
||'This avoids RequireJS  loading that library a second time.',
'      <pre>[define hammerjs=Hammer]/myjs/hammer.js</pre>',
'  </li>',
'  <li>Use this syntax if the file has a dependency on RequireJS. This will automatically load RequireJS before this file.',
'      <pre>[require requirejs]/myjs/main.js</pre>',
'  </li>',
'  <li>Use this syntax if the file has a dependency on Oracle JET. This will automatically load RequireJS and the Oracle JET RequireJS configuration before this file.',
'      <pre>[require jet]/myjs/main.js</pre>',
'  </li>',
'  <li>File reference using a query string in the URL referencing the application version, such that when the application is upgraded (and the version is incremented), the browser will be instructed to always load the new file and ignore any previousl'
||'y cached files.',
'      <pre>/myjs/main.js?version=#APP_VERSION#</pre>',
'  </li>',
'</ul>',
'</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'auto_height', 'Y',
  'character_counter', 'N',
  'resizable', 'Y',
  'trim_spaces', 'BOTH')).to_clob
);
