'       (',
'        ( :FB_FLOW_ID, :P267_THEME_ID, :WORKSPACE_ID ),',
'        ( ( select wwv_flow_theme_manager.get_central_application_id( :FB_FLOW_ID, :P267_THEME_ID ) from sys.dual ) ,',
'          ( select wwv_flow_theme_manager.get_central_theme_id( :FB_FLOW_ID, :P267_THEME_ID ) from sys.dual ) ,',
