wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1284198878924776853)
,p_name=>'P267_CUSTOM_LIBRARY_FILE_URLS'
,p_item_sequence=>380
,p_item_plug_id=>wwv_flow_imp.id(1253547956481954904)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Custom Library File URLs'
,p_source=>'CUSTOM_LIBRARY_FILE_URLS'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXTAREA'
,p_cSize=>80
,p_cMaxlength=>4000
,p_cHeight=>3
,p_tag_css_classes=>'a-Form-textarea--code'
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_css_classes=>'a-Form-fieldContainer--fieldsetBlock'
,p_item_template_options=>'#DEFAULT#:a-Form-fieldContainer--stretch'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Enter Cascading Style Sheet file URLs for custom icons to be loaded on every page. Each URL has to be written into a new line. If you provide a minified version of your file you can use the substitution string <code>#MIN#</code> to include <code>.'
||'min</code> or <code>#MIN_DIRECTORY#</code> to include <code>minified/</code> in your file URL for a regular page view and an empty string if the page is viewed in debug mode. You also have access to the substitution string <code>#APP_VERSION#</code> '
||'if you want to include the application''s version in the file URL.</p>',
'',
'<p>File URLs you enter here will replace the <code>#THEME_CSS#</code> substitution string in the page template.</p>',
'',
'<p>Note: You do not need to include opening or closing <code>link</code> tags. Just include the file URL.</p>',
'',
'<p>',
'Examples:',
'<ul>',
'  <li>Standard file reference which loads the file from the theme directory:',
'      <pre>#THEME_IMAGES#icons.css</pre>',
'  </li>',
'  <li>Standard file reference which loads the minified file icons.min.css from /mycss/minified/ for regular page views and icons.css from /mycss/ in debug mode.',
'      <pre>/mycss/#MIN_DIRECTORY#icons#MIN#.css</pre>',
'  </li>',
'  <li>Conditional media query:',
'      <pre>[media="only screen and (max-device-width: 480px)"]/mycss/smartphone_icons.css</pre>',
'  </li>',
'  <li>File reference using a query string in the URL referencing the application version, such that when the application is upgraded (and the version is incremented), the browser loads the new file and ignore any previously cached files:',
'      <pre>/mycss/icons.css?version=#APP_VERSION#</pre>',
'  </li>',
'</ul>',
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'auto_height', 'N',
  'character_counter', 'N',
  'resizable', 'Y',
  'trim_spaces', 'BOTH')).to_clob
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1284811815656337680)
,p_name=>'P267_JAVASCRIPT_FILE_URLS'
,p_item_sequence=>420
,p_item_plug_id=>wwv_flow_imp.id(1253548287352954907)
,p_use_cache_before_default=>'NO'
,p_prompt=>'JavaScript File URLs'
,p_source=>'JAVASCRIPT_FILE_URLS'
,p_source_type=>'DB_COLUMN'
