wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(116566530918758697)
,p_validation_name=>'unique template name'
,p_validation_sequence=>40
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with central_theme as (',
'    select wwv_flow_theme_manager.get_central_application_id( :FB_FLOW_ID, :P289_THEME ) as application_id,',
'           wwv_flow_theme_manager.get_central_theme_id( :FB_FLOW_ID, :P289_THEME )       as theme_id,',
'           wwv_flow_theme_manager.get_central_workspace_id( :FB_FLOW_ID, :P289_THEME )   as workspace_id',
'      from sys.dual',
')',
'',
'select 1',
'  from wwv_flow_menu_templates mt,',
'       central_theme ct',
' where ( mt.flow_id, mt.theme_id, mt.security_group_id ) in',
'       (',
'        ( :FB_FLOW_ID, :P289_THEME, :WORKSPACE_ID ),',
'        ( ct.application_id, ct.theme_id, ct.workspace_id )',
'       )',
'   and mt.name = :F4000_P289_NAME',
'   and mt.id  != :F4000_P289_ID'))
,p_validation_type=>'NOT_EXISTS'
,p_error_message=>'Template name must be unique'
,p_associated_item=>wwv_flow_imp.id(9803615747050612)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
