,p_validation_name=>'dont allow locking already locked pages'
,p_validation_sequence=>30
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_pages_to_lock  wwv_flow_t_varchar2;',
'    l_count          number;',
'begin',
'    wwv_flow_string.push( l_pages_to_lock, wwv_flow.g_f01 );',
'',
'    select count( * )',
'      into l_count',
'      from wwv_flow_lock_page',
'     where flow_id      = :FB_FLOW_ID',
'       and locked_by   is not null ',
'       and object_id   in ( select /*+ cardinality( t 20 ) */ column_value ',
'                              from table( l_pages_to_lock ) t )',
'       and rownum       = 1;',
'',
'    return l_count = 0;',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>'You may not lock pages that have already been locked.'
