wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(543179732397973700)
,p_name=>'Seed Translatable Text'
,p_template=>wwv_flow_imp.id(208928010704475743)
,p_display_sequence=>20
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#:a-Report--stretch'
,p_source_type=>'NATIVE_TABFORM'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select m.id,',
'       m.primary_language_flow_id,',
'       m.translation_flow_id,',
'       m.translation_flow_language_code,',
'       tt.translatable_strings,',
'       tt.distinct_string_estimate,',
'       coalesce(',
'           ( select case when sign( app_diff.difference ) = -1',
'                        then ''Y''',
'                        else ''N''',
'                    end',
'               from (',
'                   select f2.created_on - f1.last_updated_on difference,',
'                          f2.id translated_app_id',
'                     from wwv_flows f1, wwv_flows f2',
'                    where f1.security_group_id = f2.security_group_id',
'                      and f1.id = m.primary_language_flow_id',
'                      and f2.id = m.translation_flow_id',
'                      and f1.id = :FB_FLOW_ID',
'                      and f1.security_group_id = :flow_security_group_id ) app_diff',
'              where app_diff.translated_app_id = m.translation_flow_id ),',
'            ''Y'') requires_synchronization,',
'       (select created_on',
'          from wwv_flows f',
'         where f.id = m.translation_flow_id',
'           and security_group_id = :flow_security_group_id ) translation_created',
'from wwv_flow_language_map m,',
'     (select count(*) translatable_strings,',
'             count(distinct sys.dbms_lob.substr(t.translate_from_text,1000,1)) distinct_string_estimate,',
'             t.translated_flow_id',
'        from wwv_flow_translatable_text$ t',
'       where t.security_group_id = :flow_security_group_id',
'         and t.flow_id = :fb_flow_id',
'       group by t.translated_flow_id) tt',
'where m.primary_language_flow_id = :fb_flow_id',
'  and m.security_group_id = :flow_security_group_id',
'  and tt.translated_flow_id (+)= m.translation_flow_id'))
,p_fixed_header=>'NONE'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(123728124628276646)
,p_query_num_rows=>100
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_break_cols=>'0'
