,p_group_id=>wwv_flow_imp.id(213210808239773454)
,p_step_template=>wwv_flow_imp.id(386677207130845076)
,p_page_template_options=>'#DEFAULT#'
,p_nav_list_template_options=>'#DEFAULT#'
,p_help_text=>'nav_list.htm'
,p_page_component_map=>'18'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3852226590687921)
,p_plug_name=>'Lists'
,p_region_template_options=>'#DEFAULT#:a-IRR-region--noOuterBorders:a-IRR-region--responsiveIconView'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(646287526247383209)
,p_plug_display_sequence=>30
,p_plug_new_grid_row=>false
,p_plug_new_grid_column=>false
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with messages as (',
'    select ( select wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_UP_TO_DATE'') from sys.dual ) up_to_date,',
'           ( select wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_NEEDS_REFRESH'') from sys.dual ) needs_refresh,',
'           ( select wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_UNKNOWN'') from sys.dual ) unknown_status,',
'           ( select wwv_flow_lang_dev.builder_message(''SUBSCRIBED_FROM.NONEXISTING_MASTER'') from sys.dual ) no_master,',
'           ( select wwv_flow_lang_dev.builder_message(''F4000.DYNAMIC'') from sys.dual ) "DYNAMIC",',
'           ( select wwv_flow_lang_dev.builder_message(''F4000.STATIC'') from sys.dual ) "STATIC"         ',
'      from sys.dual )',
'select l.id,',
'       l.name name,',
'       ( select count(*)',
'           from wwv_flow_list_items i',
'          where i.list_id           = l.id ',
'            and i.flow_id           = l.flow_id',
'            and i.security_group_id = l.security_group_id) entries,',
'       ( select count(*)',
'           from wwv_flow_page_plugs p',
'          where p.list_id           = l.id',
'            and p.flow_id           = l.flow_id',
'            and p.security_group_id = l.security_group_id ) +',
'       ( select count(*)',
'           from wwv_flow_steps s',
'          where s.navigation_list_id = l.id',
'            and s.flow_id            = l.flow_id',
'            and s.security_group_id  = l.security_group_id ) +',
'       ( select count(*)',
'           from wwv_flows f',
'          where l.id                 in (f.navigation_list_id, f.nav_bar_list_id)',
'            and f.id                 = l.flow_id',
'            and f.security_group_id  = l.security_group_id ) +',
'        ( select count(*)',
'            from wwv_flow_list_items sl',
'           where sl.sub_list_id       = l.id',
'             and sl.flow_id           = l.flow_id',
'             and sl.security_group_id = l.security_group_id) as ref,',
'       --',
'       coalesce(l.last_updated_on,l.created_on) list_last_updated,',
'       --',
'       decode(substr(l.list_query,1,1),null,messages."STATIC",decode(substr(upper(l.list_query),1,6),''STATIC'',',
'          messages."STATIC",messages."DYNAMIC")) list_type,',
'       --',
'       ( select patch_name',
'           from wwv_flow_patches p',
'          where security_group_id = :FLOW_SECURITY_GROUP_ID',
'            and flow_id           = :FB_FLOW_ID',
'            and p.id              = l.required_patch ) build_option,',
'       --',
'       l.list_comment,',
'       l.flow_id appliation_id,',
'       ''icon-sc-list'' icon_class,',
'       replace(replace(l.name,''_'','' ''),''.'','' '') icon_title,',
'       --',
'       wwv_flow_page_api.get_url(',
'            p_page               => ''4050'',',
'            p_clear_cache        => ''4050'',',
'            p_items              => ''F4000_P4050_LIST_ID'',',
'            p_values             => l.id ) as edit_link,',
'       --',
'       ( select decode(count(nav_bar_list_id),0,''N'',''Y'')',
'           from wwv_flows',
'          where id                = :FB_FLOW_ID',
'            and security_group_id = :FLOW_SECURITY_GROUP_ID',
'            and nav_bar_list_id   = l.id ) navbar,',
'       --',
'       ( select decode(count(nav_bar_list_id),0,0,1)',
'           from wwv_flows',
'          where id                = :FB_FLOW_ID',
'            and security_group_id = :FLOW_SECURITY_GROUP_ID',
'            and nav_bar_list_id   = l.id ) is_navbar,',
'       --',
'       case',
'         when exists ( select 1 ',
'                         from wwv_flows',
'                        where id                 = :FB_FLOW_ID',
'                          and security_group_id  = :FLOW_SECURITY_GROUP_ID',
'                          and navigation_list_id = l.id ) then ''Y''',
'         when exists ( select 1',
'                         from wwv_flow_steps',
'                        where flow_id            = :FB_FLOW_ID',
'                          and security_group_id  = :FLOW_SECURITY_GROUP_ID',
'                          and navigation_list_id = l.id ) then ''Y''',
'         else ''N''',
'       end global_nav,',
'       --',
'       case',
'         when exists ( select 1',
'                         from wwv_flows',
'                        where id                 = :FB_FLOW_ID',
'                          and security_group_id  = :FLOW_SECURITY_GROUP_ID',
'                          and navigation_list_id = l.id ) then 1',
'         when exists ( select 1',
'                         from wwv_flow_steps',
'                        where flow_id            = :FB_FLOW_ID',
'                          and security_group_id  = :FLOW_SECURITY_GROUP_ID',
'                          and navigation_list_id = l.id ) then 1',
'         else 0',
'       end is_navmenu,',
'       --',
'       case when l.reference_id is not null then',
'           coalesce ( to_char( master.flow_id ),',
'                       messages.no_master )',
'       end as subscribed_from,',
'       ( select case when count(*) > 0 then count(*) end',
'           from wwv_flow_lists sub',
'          where sub.reference_id      = l.id',
'            and sub.security_group_id = :WORKSPACE_ID ) as subscribers,',
'       case when l.reference_id is not null then',
'           case',
'               when master.version_scn = l.version_scn then',
'                   messages.up_to_date',
'               when master.version_scn != l.version_scn then',
'                   messages.needs_refresh',
'               else',
'                   messages.unknown_status',
'           end',
'       end subscription_status,',
'       --  ',
'       null action     ',
'  from wwv_flow_lists l,',
'       wwv_flow_lists master,',
'       messages',
' where l.flow_id                = :FB_FLOW_ID',
'   and l.security_group_id      = :WORKSPACE_ID',
'   and l.reference_id           = master.id (+)',
'   and l.security_group_id      = master.security_group_id (+)'))
,p_plug_source_type=>'NATIVE_IR'
,p_plug_query_show_nulls_as=>' - '
,p_pagination_display_position=>'BOTTOM_RIGHT'
);
