  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(185271801825507433)
,p_plug_name=>'List Utilization Page References'
,p_region_template_options=>'#DEFAULT#:a-IRR-region--noOuterBorders'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(646287526247383209)
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'BELOW'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select l.name      as list_name,',
'       p.page_id,',
'       (',
'           select name',
'             from wwv_flow_steps',
'            where flow_id = :fb_flow_id',
'              and id      = p.page_id',
'       )           as page_name,',
'       p.plug_name as region_name,',
'       l.id        as list_id,',
'       null        as referenced_by,',
'       null        as referenced_by_item_id,',
'       null        as referenced_by_list_id',
'  from wwv_flow_page_plugs p,',
'       wwv_flow_lists l',
' where l.flow_id = :fb_flow_id',
'   and p.flow_id = :fb_flow_id',
'   and p.list_id = l.id',
'union all',
'select l.name as list_name,',
'       p.id   as page_id,',
'       p.name as page_name,',
'       null   as region_name,',
'       l.id   as list_id,',
'       null   as referenced_by,',
'       null   as referenced_by_item_id,',
'       null   as referenced_by_list_id',
'  from wwv_flow_steps p,',
'       wwv_flow_lists l',
' where l.flow_id            = :fb_flow_id',
'   and p.flow_id            = :fb_flow_id',
'   and p.navigation_list_id = l.id',
'union all',
'select l.name as list_name,',
'       null   as page_id,',
'       null   as page_name,',
'       null   as region_name,',
'       l.id   as list_id,',
'       null   as referenced_by,',
'       null   as referenced_by_item_id,',
'       null   as referenced_by_list_id',
'  from wwv_flows f,',
'       wwv_flow_lists l',
' where l.flow_id = :fb_flow_id',
'   and f.id      = :fb_flow_id',
'   and l.id in (f.navigation_list_id, f.nav_bar_list_id)',
'union all',
'select l.name                                 as list_name,',
'       null                                   as page_id,',
'       null                                   as page_name,',
'       null                                   as region_name,',
'       l.id                                   as list_id,',
'       r.name || '' \ '' || i.list_item_link_text as referenced_by,',
'       i.id                                   as referenced_by_item_id,',
'       r.id                                   as referenced_by_list_id',
'  from wwv_flow_lists l,',
'       wwv_flow_list_items i,',
'       wwv_flow_lists r',
' where l.flow_id     = :fb_flow_id',
'   and i.flow_id     = :fb_flow_id',
'   and i.sub_list_id = l.id',
'   and r.id          = i.list_id'))
,p_plug_source_type=>'NATIVE_IR'
,p_plug_query_show_nulls_as=>' - '
,p_pagination_display_position=>'BOTTOM_RIGHT'
);
