,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'ON'
,p_group_id=>wwv_flow_imp.id(24897722063538624)
,p_step_template=>wwv_flow_imp.id(386677207130845076)
,p_page_template_options=>'#DEFAULT#'
,p_nav_list_template_options=>'#DEFAULT#'
,p_help_text=>'deployment.htm'
,p_page_component_map=>'18'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(12979519988497157)
,p_plug_name=>'Installation Scripts'
,p_region_template_options=>'#DEFAULT#:a-IRR-region--noOuterBorders'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(646287526247383209)
,p_plug_display_sequence=>60
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with upd as',
'( select id',
'    from wwv_flow_install_scripts a',
'   where a.security_group_id = :flow_security_group_id',
'     and a.flow_id           = :fb_flow_id',
'     and exists ( select 1',
'                    from sys.dba_objects b,',
'                         wwv_flow_install_objects c',
'                   where b.object_type   = c.object_type',
'                     and b.owner         = replace(c.object_owner,''#''||''OWNER''||''#'',wwv_flow_wizard_api.get_flow_owner)',
'                     and b.object_name   = c.object_name',
'                     and b.last_ddl_time > nvl(a.last_updated_on, a.created_on)',
'                     and a.id = c.script_id )',
'   union',
'  select distinct script_id id',
'    from wwv_flow_install_objects a',
'   where a.security_group_id = :flow_security_group_id',
'     and a.flow_id           = :fb_flow_id',
'     and not exists ( select 1',
'                        from sys.dba_objects',
'                       where owner       = replace(a.object_owner,''#''||''OWNER''||''#'',wwv_flow_wizard_api.get_flow_owner)',
'                         and object_type = a.object_type',
'                         and object_name = a.object_name ) ),',
'ob as',
'( select distinct script_id id',
'    from wwv_flow_install_objects a',
'   where a.security_group_id = :flow_security_group_id',
'     and a.flow_id           = :fb_flow_id )',
'select s.id,',
'       case when (l.locked_by is null) or (l.locked_by is not null and l.locked_by = :app_user) then',
'           ''<a href="''',
'           ||wwv_flow_page_api.get_url (',
'                 p_page        => 865,',
'                 p_clear_cache => ''865,INSTALL_SCRIPT'',',
'                 p_items       => ''P865_SCRIPT_ID,P865_MODE,F4000_LAST_VIEW'',',
'                 p_values      => s.id||'',EDIT,473'' )',
'           ||''">''',
'           ||''<img src="#IMAGE_PREFIX#menu/pencil2_16x16.gif" alt="''||sm.edit||''"></a>''',
'       end edit_link,',
'       s.name,',
'       s.sequence,',
'       lower(nvl(s.last_updated_by,s.created_by)) updated_by,',
'       nvl(s.last_updated_on,s.created_on) last_updated_on,',
'       sys.dbms_lob.substr(s.script,200,1)||(case when sys.dbms_lob.getlength(s.script) > 200 then ''...'' end) script,',
'       decode (ob.id, null, sm.manual, sm.database_object) source,',
'       decode (upd.id, null, null, sm.need_refresh) status,',
'       decode (ob.id, null, null, wwv_flow_item.checkbox(1,ob.id,''title="''||wwv_flow_lang.system_message(''SELECT_ROW_C'', wwv_flow_escape.html(s.name))||''"'')) refresh,',
'       case when l.locked_by is null then',
'           wwv_flow_lang.system_message(''SCRIPT_NAME_UNLOCKED'', wwv_flow_escape.html(s.name))',
'       else',
'           wwv_flow_lang.system_message(''SCRIPT_NAME_LOCKED'', wwv_flow_escape.html(s.name))',
'       end locked,',
'       case when l.locked_by is null then',
'           ''icon-unlock''',
'       else',
'           ''icon-lock''',
'       end lock_icon,',
'       l.id lock_id',
'  from "#OWNER#"."WWV_FLOW_INSTALL_SCRIPTS" s,',
'       upd,',
'       ob,',
'       wwv_flow_lock_script l,',
'       (select wwv_flow_lang.system_message(''MANUAL'') manual,',
'       	       wwv_flow_lang.system_message(''F4000_P473_DATABASE_OBJECT'') database_object,',
'       	       wwv_flow_lang.system_message(''P473_NEEDS_REFRESH'') need_refresh,',
'       	       wwv_flow_lang.system_message(''EDIT'') edit',
'          from sys.dual) sm',
' where s.flow_id                    = :FB_FLOW_ID',
'   and s.security_group_id          = :FLOW_SECURITY_GROUP_ID',
'   and s.id                         = ob.id(+)',
'   and s.id                         = upd.id(+)',
'   and s.id                         = l.script_id(+)',
'   and nvl(s.script_type,''INSTALL'') = ''INSTALL'''))
,p_plug_source_type=>'NATIVE_IR'
,p_plug_query_show_nulls_as=>' - '
,p_pagination_display_position=>'BOTTOM_RIGHT'
);
