,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Specifies how &PRODUCT_NAME. derives the translated application language.  The application primary language can be static, derived from the Web browser language, or determined from a user preference or item. Available options include:',
'<ul>',
'<li><strong>No NLS (Application not translated)</strong> - Select this option if the application will not be translated.</li>',
'<li><strong>Application Primary Language</strong> - Determines the translated application language based on the Application Primary Language attribute.</li>',
'<li><strong>Browser (use browser language preference)</strong> - Determines the translated application language based on the user''s Web browser language.</li>',
'<li><strong>Application Preference (use FSP_LANGUAGE_PREFERENCE)</strong> - Determines the translated application language based on a value defined using the <code>APEX_UTIL.SET_PREFERENCE</code> API.  This option can be used to maintain a user''s lan'
||'guage preference across multiple logins.</li>',
'<li><strong>Item Preference (use item containing preference)</strong> - Determines the translated application language based on an application-level item called <code>FSP_LANGUAGE_PREFERENCE</code>. Using this option requires &PRODUCT_NAME. to determ'
||'ine the appropriate language preference every time the user logs in. </li>',
'<li><strong>Session</strong> - Determines the translated application language from the session setting.  The &PRODUCT_NAME. session language can be set via either the <code>APEX_UTIL.SET_SESSION_LANG</code> procedure or via the <code>P_LANG</code> pa'
||'rameter of the <code>F</code> procedure in the URL.</li>',
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
