,p_item_default=>'black-translucent'
,p_prompt=>'iOS Status Bar Style'
,p_source=>'PWA_APPLE_STATUS_BAR_STYLE'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'PWA_APPLE_STATUS_BAR_STYLE'
,p_lov=>'.'||wwv_flow_imp.id(3776418597747042)||'.'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>The iOS Status Bar Style attribute is rendered as a meta tag on the page to control the appearance of the status bar in a web application when it is added to the home screen on an iOS device.</p>',
'<ul>',
'    <li><strong>Default</strong>: This is the default value and it displays the status bar in the usual way.</li>',
'    <li><strong>Black</strong>: This value makes the status bar black.</li>',
'    <li><strong>Translucent</strong>: This value makes the status bar translucent, allowing the content to be displayed behind it.</li>',
'</ul>',
'<p>Note: Only iOS devices use this attribute. Oracle APEX is only relaying this information to the device which handles',
'the Progressive Web App appropriately.</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(3606435840641505)
,p_name=>'P507_SW_MODE'
,p_item_sequence=>20
,p_item_plug_id=>wwv_flow_imp.id(23102851875504524)
,p_prompt=>'Service Worker'
,p_display_as=>'NATIVE_RADIOGROUP'
,p_lov=>'STATIC2:Default;DEFAULT,Configure Hooks;DECLARATIVE,File URL;URL'
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_css_classes=>'apex-button-group'
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Service workers are JavaScript files that can execute code even when the app is not in use.</p>',
'<p>It can listen to events like fetching resources or handling notifications.</p>',
'<p>Pick a service worker strategy that best fits your application''s needs.</p>',
'<ul>',
'    <li><span>Default: The &PRODUCT_NAME. engine will generate a service worker with the following strategy:</span>',
'        <ul>',
'            <li>Install and activate the service worker</li>',
'            <li>Serve resources from cache if cache exists</li>',
'            <li>Otherwise serve from network, then put resource in cache</li>',
'            <li>Serve an offline page if network fails</li>',
'        </ul>',
'    </li>',
'    <li>Configure Hooks: Fill in the placeholders in the service worker code to add your own. Hooks locations are provided by &PRODUCT_NAME.</li>',
'    <li>File URL: Provide a URL reference to a file that contains the service worker hooks interface. This is useful for sharing service worker hooks across multiple applications. If using the file reference, make sure to follow the interface archite'
||'cture appropriately or else the service worker will fail at runtime.</li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'number_of_columns', '3',
  'page_action_on_selection', 'NONE')).to_clob
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(3606573660641506)
,p_name=>'P507_SW_FILE_REFERENCE'
,p_item_sequence=>40
,p_item_plug_id=>wwv_flow_imp.id(23102851875504524)
,p_prompt=>'File Reference URL'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>50
,p_cMaxlength=>255
,p_field_template=>wwv_flow_imp.id(452656722938220607)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Provide a URL reference to a file that contains the service worker hooks interface. This is useful for sharing service worker hooks across multiple applications. If using the file reference, make sure to follow the interface architecture appropria'
||'tely or else the service worker will fail at runtime. Here is the interface structure:</p>',
'<pre><code class="language-javascript">',
'const swHooks = {',
'  FUNCTION_VARIABLE_DECLARATION: ({ apex })                         => { console.log(1, { apex }); },',
'  EVENT_INSTALL:                 ({ apex, event })                  => { console.log(2, { apex, event }); },',
'  EVENT_INSTALL_BEFORE:          ({ apex, event })                  => { console.log(3, { apex, event }); },',
'  EVENT_INSTALL_AFTER:           ({ apex, event })                  => { console.log(4, { apex, event }); },',
'  EVENT_ACTIVATE:                ({ apex, event })                  => { console.log(5, { apex, event }); },',
'  EVENT_ACTIVATE_BEFORE:         ({ apex, event })                  => { console.log(6, { apex, event }); },',
'  EVENT_ACTIVATE_AFTER:          ({ apex, event })                  => { console.log(7, { apex, event }); },',
'  EVENT_FETCH:                   ({ apex, event })                  => { console.log(8, { apex, event }); },',
'  EVENT_FETCH_BEFORE:            ({ apex, event })                  => { console.log(9, { apex, event }); },',
'  EVENT_FETCH_CACHE_DEFINITION:  ({ apex, event, cacheName })       => { console.log(10, { apex, event, cacheName }); },',
'  EVENT_FETCH_CACHE_RESPONSE:    ({ apex, event, cache, response }) => { console.log(11, { apex, event, cache, response }); },',
'  EVENT_FETCH_NETWORK_RESP_SUC:  ({ apex, event, response })        => { console.log(12, { apex, event, response }); },',
'  EVENT_FETCH_NETWORK_RESP_ERR:  ({ apex, event, error })           => { console.log(13, { apex, event, error }); },',
'  EVENT_FETCH_OFFLINE_PAGE:      ({ apex, event, offlinePage })     => { console.log(14, { apex, event, offlinePage }); },',
'  EVENT_FETCH_NETWORK_FALLBACK:  ({ apex, event })                  => { console.log(15, { apex, event }); },',
'  EVENT_SYNC:                    ({ apex, event })                  => { console.log(16, { apex, event }); },',
'  EVENT_PUSH:                    ({ apex, event })                  => { console.log(17, { apex, event }); },',
'  EVENT_NOTIFICATIONCLICK:       ({ apex, event })                  => { console.log(18, { apex, event }); },',
'  EVENT_NOTIFICATIONCLOSE:       ({ apex, event })                  => { console.log(19, { apex, event }); },',
'  EVENT_CANMAKEPAYMENT:          ({ apex, event })                  => { console.log(20, { apex, event }); },',
'  EVENT_PAYMENTREQUEST:          ({ apex, event })                  => { console.log(21, { apex, event }); },',
'};',
'</code></pre>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'TEXT',
  'trim_spaces', 'BOTH')).to_clob
);
