' where p.flow_id             = :FB_FLOW_ID',
'   and p.security_group_id   = :WORKSPACE_ID',
'   and pa.security_group_id  = p.security_group_id',
'   and pa.flow_id            = p.flow_id',
'   and pa.id                 = p.required_patch',
'   and pa.feature_identifier = ''APPLICATION_PUSH_NOTIFICATIONS'''))
);
