,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Cleanup files'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_file_id number;',
'begin',
'    for i in ( select id ',
'                 into l_file_id',
'                 from wwv_flow_static_files sf',
'                where sf.security_group_id = :workspace_id ',
'                  and sf.flow_id           = :fb_flow_id',
'                  and sf.file_name         like ''pwa/shortcut-icon%''',
'                  and not exists ( select 1',
'                                     from wwv_flow_pwa_shortcuts ps',
'                                    where ps.security_group_id = sf.security_group_id ',
'                                      and ps.flow_id           = sf.flow_id',
'                                      and ps.icon_url          = sf.file_name ) )',
'    loop',
'        wwv_flow_file_editor_dev.delete_file (',
'           p_id     => i.id,',
'           p_scope  => ''APP'',',
'           p_app_id => :fb_flow_id );',
'    end loop;',
'exception when others then ',
'    null; -- if anything happens don''t delete the file, that is fine',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(5403080113685429)
,p_internal_uid=>11364429369866146
);
