,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'save_shortcut'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_extension varchar2(50);',
'begin',
'    if wwv_flow.g_x02 like ''%jpeg'' or wwv_flow.g_x02 like ''%jpg'' then',
'        l_extension := ''jpg'';',
'    else ',
'        l_extension := ''png'';',
'    end if;',
'',
'    wwv_flow_imp_shared.create_app_static_file(',
'        p_flow_id      => :fb_flow_id,',
'        p_file_name    => ''pwa/shortcut-icon-''||wwv_flow.g_x01||''.''||l_extension,',
'        p_mime_type    => nvl(wwv_flow.g_x02, ''image/png''),',
'        p_file_charset => ''utf-8'',',
'        p_file_content => wwv_flow_webservices_api.clobbase642blob( p_clob => wwv_flow.g_clob_01 ) );',
' ',
'    wwv_flow_json.open_object;',
'    wwv_flow_json.write( p_name => ''success'', p_value => true );',
'    wwv_flow_json.close_object;',
'exception',
'    when others then',
'        wwv_flow_json.open_object;',
'        wwv_flow_json.write( p_name => ''success'', p_value => false );',
'        wwv_flow_json.write( p_name => ''message'', p_value => sqlerrm );',
'        wwv_flow_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>11361121769866113
);
