wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1875072844167005)
,p_name=>'P509_AUTH_CONFIG_PROCEDURE'
,p_item_sequence=>110
,p_item_plug_id=>wwv_flow_imp.id(107178726415706930)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Configuration Procedure'
,p_source=>'AUTH_CONFIG_PROCEDURE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>32
,p_cMaxlength=>255
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Enter the name of a procedure which configures authentication at runtime.',
'The code below is for an application that implements multi-tenancy and supports',
'different variations of <em>Social Sign-In</em> for the tenants.',
'It uses the domain name in the URL to fetch configuration data (URLs are e.g. ',
'https://cust-01.example.com, https://cust-02.example.com, ...):',
'</p><pre><code>',
'procedure my_auth_config (',
'    p_conf in out nocopy apex_authentication.t_configuration )',
'is',
'    l_host varchar2(32767) := sys.owa_util.get_cgi_env(''HTTP_HOST'');',
'begin',
'    for i in ( select discovery_url,',
'                      auth_scheme_name,',
'                      credential,',
'                      tenant_id',
'                 from customer_tenants',
'                where hostname = l_host )',
'    loop',
'        p_conf.authentication_name := i.auth_scheme_name;',
'        p_conf.substitutions := apex_t_varchar2 (',
'                                    ''DISCOVERY_URL''       , i.discovery_url,',
'                                    ''CREDENTIAL_STATIC_ID'', i.credential );',
'        p_conf.tenant_id := i.tenant_id;',
'    end loop;',
'end my_auth_config;',
'</code></pre><p>',
'The procedure can change 3 attributes of the in/out parameter <code>p_conf</code>,',
'all of them are optional:',
'<ul>',
'    <li><code>authentication_name</code>:',
'    Assign the name of an authentication scheme in your application,',
'    which will be used instead of the default scheme.',
'    Note that <em>Switch In Session</em> must be enabled for that scheme.',
'    </li><li><code>substitutions</code>:',
'    Assign name/value pairs using <code>apex_t_varchar2</code>.',
'    &PRODUCT_NAME. substitutes each <code>#NAME#</code> in the authentication scheme ',
'    attributes with the associated value.',
'    The built-in <em>Social Sign-In</em> scheme uses <code>CREDENTIAL_STATIC_ID</code>',
'    to use the corresponding credential store instead of the one that was configured ',
'    in the scheme.',
'    </li><li><code>tenant_id</code>:',
'    Set this tenant id in the session (see <code>apex_session.set_tenant_id</code>).',
'    </li>',
'</ul>',
'</p><p>',
'In applications with an authentication configuration procedure,',
'the authentication scheme can not be changed via the URL (e.g. <code>f?p=100:1:1234:APEX_AUTHENTICATION=myauth</code>).',
'</p><p>',
'The authentication configuration procedure runs at least once per session, on the first request.    ',
'However, &PRODUCT_NAME. may need to also call it on other occasions.',
'In such cases, it must set the same values on each call.',
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'TEXT',
  'trim_spaces', 'BOTH')).to_clob
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(2404415432409943)
,p_name=>'P509_SESSION_STATE_COMMITS'
,p_is_required=>true
,p_item_sequence=>40
,p_item_plug_id=>wwv_flow_imp.id(6354406057147715)
,p_use_cache_before_default=>'NO'
,p_item_default=>'END_OF_REQUEST'
,p_prompt=>'Session State Commits'
,p_source=>'SESSION_STATE_COMMITS'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'SESSION_STATE_COMMITS'
,p_lov=>'.'||wwv_flow_imp.id(2404156723407174)||'.'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'&PRODUCT_NAME. maintains session state[<a rel="noopener noreferrer" href="#fn1">1</a>] both in PL/SQL global variables for quick access and in database tables.',
'Use this attribute to configure when session state gets written and committed to the database:',
'<ul><li><strong>Immediate</strong>: When state changes during request processing, for example because a PL/SQL process modified a bind variable,',
'immediately write these changes and commit. Note that this commits the main transaction,',
'which may contain changes to your application tables.',
'</li><li><strong>End Of Request</strong>: &PRODUCT_NAME. maintains a list of session state changes that occur during request processing',
'and applies them at the end of the request.',
'Use this value for better transaction control and Application Continuity in case of unplanned outages.',
'</li></ul>',
'<br/>',
'<div id="fn1">[1] In this context, session state includes item values and attributes of the session itself (for example the idle timeout).',
'While collections are also part of session state, they are not affected by the <em>Session State Commits</em> attribute.',
'</div>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
