wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(16978325970274016)
,p_name=>'P509_AUTHORIZE_PUBLIC_PAGES_YN'
,p_is_required=>true
,p_item_sequence=>280
,p_item_plug_id=>wwv_flow_imp.id(107179907066706934)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Run on Public Pages'
,p_source=>'AUTHORIZE_PUBLIC_PAGES_YN'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_YES_NO'
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'Controls whether the application-level authorization scheme is checked on public pages (that is, pages that do not require authorization). Options include:',
'</p>',
'<ul>',
'<li><strong>On</strong> - If you select <strong>On</strong> and the page is public, the application authorization is checked.</li>',
'<li><strong>Off</strong> - If you select <strong>Off</strong> and the page is public, the application authorization is ignored.</li>',
'</ul>',
'<p>',
'Note: This attribute is ignored if you select <strong>Must Not Be Public User</strong> as Authorization Scheme.',
'</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'use_defaults', 'Y')).to_clob
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(34364122664343194)
,p_name=>'P509_DEEP_LINKING'
,p_is_required=>true
,p_item_sequence=>30
,p_item_plug_id=>wwv_flow_imp.id(6354406057147715)
,p_use_cache_before_default=>'NO'
,p_item_default=>'Y'
,p_prompt=>'Deep Linking'
,p_source=>'DEEP_LINKING'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'DEEP_LINKING'
,p_lov=>'.'||wwv_flow_imp.id(34319101845334424)||'.'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'YES'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>This attribute enables or prevents deep linking to an application. Deep linking refers to the ability to link to an &PRODUCT_NAME. page out of context (for example, from a hyperlink in an email or workflow notification). Options include:</p>',
'<ul>',
'<li><strong>Enabled</strong> - If the URL references a specific page in an application, after authentication, &PRODUCT_NAME. automatically displays that specific page.</li>',
'<li><strong>Disabled</strong> - If the URL does not contain a valid session ID, &PRODUCT_NAME. redirects to the application''s home page.</li>',
'</ul><p/>',
'<p>For example, browsers often save the URLs of opened tabs and try to restore the sessions after a restart, causing a deep link. This behavior may be undesirable (for example if a URL points to a page in the middle of a multi-step wizard). By select'
||'ing <strong>Disabled</strong>, &PRODUCT_NAME. starts a new session and redirects to the application''s home page.</p>',
'<p>You can override this application setting at page level.</p>',
'<p>To simplify development, deep linking is always enabled if the user is also logged in to the development environment.</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(94182360081544823)
,p_name=>'P509_SESSION_TIMEOUT_WARN_SEC'
,p_item_sequence=>110
,p_item_plug_id=>wwv_flow_imp.id(6354406057147715)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Session Timeout Warning in Seconds'
,p_source=>'SESSION_TIMEOUT_WARNING_SEC'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_named_lov=>'SECONDS_SMALL'
,p_lov=>'.'||wwv_flow_imp.id(433752258048536863)||'.'
,p_cSize=>30
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>The session timeout warning time defines (in seconds) how long before a session times out (either maximum session length, or maximum session idle time), to warn the user. For the maximum session idle time warning, the user will have the opportunit'
||'y to extend the session. For maximum session length warning, the user will be prompted to save any work, to avoid loss of data when the session maximum time is reached.</p>',
'<ul>',
'    <li>Enter a positive integer to control the session timeout warning time for sessions used by this application.</li>',
'    <li>Enter 0 to switch off session timeout warnings for sessions used by this application.</li>',
