wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(107203001185706981)
,p_name=>'P509_PAGE_PROTECTION_ENABLED'
,p_item_sequence=>200
,p_item_plug_id=>wwv_flow_imp.id(107273213161009008)
,p_use_cache_before_default=>'NO'
,p_item_default=>'N'
,p_prompt=>'Session State Protection'
,p_source=>'PAGE_PROTECTION_ENABLED_Y_N'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'ENABLED_DISABLED_RETURNS_Y_OR_N'
,p_lov=>'.'||wwv_flow_imp.id(91439803955181562)||'.'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_escape_on_http_input=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="htmldbInfoBodyP">When you select <strong>Enabled</strong>, this feature uses the Page Access Protection page attribute and the Session State Protection item attributes in conjunction with checksums positioned in f?p= URLs. Enabling this f'
||'eature prevents URL tampering and unauthorized access to and alteration of session state.</div>',
'',
'<div class="htmldbInfoBodyP">When you select <strong>Disabled</strong>, the &PRODUCT_NAME. engine does not consider Page Access Protection page attributes or Session State Protection item attributes during the execution of your application and does n'
||'ot include checksums in the f?p= section of the URLs.</div>',
'',
'<div class="htmldbInfoBodyP">If this attribute is set to <strong>Enabled</strong>, changing it to <strong>Disabled</strong> disableS Session State Protection, but leaves the setting of all Page Access Protection page attributes and all Session State '
||'Protection item attributes intact.</div>',
'',
'<div class="htmldbInfoBodyP">If the attribute is set to <strong>Disabled</strong>, changing it to <strong>Enabled</strong> enables Session State Protection and leaves all Page Access Protection page attributes and all Session State Protection item at'
||'tributes intact, to be observed during the execution of your application.</div>',
'',
'<div class="htmldbInfoBodyP">An exception to the general rule about item Session State Protection attributes having effect only when Session State Protection is <strong>Enabled</strong>, is if an item''s attribute is set to <strong>Protected</strong>,'
||' that status is always in effect. Protected items cannot be set from the URL, regardless of whether or not Session State Protection is Enabled or Disabled.</div>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
