,p_item_template_options=>'#DEFAULT#'
,p_escape_on_http_input=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="htmldbInfoBodyP"><strong>Allows URLS Created After</strong> lists the date and time after which bookmarked links are useable to access pages in this application if the bookmarked link contains a checksum and Session State Protection is en'
||'abled for the application.',
'<p>',
'Bookmarks created before this date and time are not usable to access this application if the bookmarked link contains a checksum and Session State Protection is enabled for the application.',
'<p>',
'Bookmarks that do not contain checksums or bookmarks that contain checksums that are unnecessary are not affected by this attribute. Their usability is determined using other criteria.',
'<p>',
'A hidden application attribute (a checksum salt) is used during the computation and later verification of checksums included in <code>f?p=</code> URLs generated during page rendering. Checksums are included when Session State Protection is enabled fo'
||'r the application. You can reset this checksum salt attribute at any time by clicking the <strong>Expire Bookmarks</strong> button. Clicking this button causes any bookmarked URLs that contain previously generated checksums to fail when they are subs'
||'equently used to access the application.</div>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'based_on', 'VALUE',
  'format', 'PLAIN',
  'send_on_page_submit', 'N',
  'show_line_breaks', 'N')).to_clob
);
