wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(384789975408553245)
,p_name=>'P509_REJOIN_EXISTING_SESSIONS'
,p_is_required=>true
,p_item_sequence=>20
,p_item_plug_id=>wwv_flow_imp.id(6354406057147715)
,p_use_cache_before_default=>'NO'
,p_item_default=>'N'
,p_prompt=>'Rejoin Sessions'
,p_source=>'REJOIN_EXISTING_SESSIONS'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'REJOIN_EXISTING_SESSIONS'
,p_lov=>'.'||wwv_flow_imp.id(492680965578161495)||'.'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'Use this attribute to control if &PRODUCT_NAME. should support application URLs that do not contain session IDs.',
'When rejoin sessions is enabled, &PRODUCT_NAME. attempts to use the session cookie to join an existing session,',
'when a URL does not contain a session ID.',
'</p>',
'<p>',
'A more restrictive instance level setting overrides this page level value.',
'</p>',
'<p>',
'    <strong>Note:</strong>',
'Enabling rejoin sessions exposes your application to possible security breaches, as it can enable attackers to take over existing end user sessions. To learn more, see the Rejoin Sessions sections in "Managing Application Security" in the App Builder'
||' User''s Guide.',
'</p>',
'',
'<p>',
'Available options include:    ',
'</p>',
'<ul>',
'    <li><strong>Application Default</strong> - ',
'    The application-level setting applies.',
'    </li>',
'    <li><strong>Disabled</strong> - ',
'    If the URL does not contain a session ID, &PRODUCT_NAME. creates a new session.',
'    </li>',
'    <li><strong>Enabled for Public Sessions</strong> - ',
'    If the URL goes to a public page and does not contain a session ID,',
'    &PRODUCT_NAME. attempts to utilize the existing session cookie established for that application.',
'    For applications with both public and authenticated pages, a session ID is defined after the end user authenticates.',
'    &PRODUCT_NAME. only joins using the cookie when the session is not yet authenticated.',
'    </li>',
'    <li><strong>Enabled for All Sessions</strong> - ',
'    If the URL does not contain a session ID, &PRODUCT_NAME. attempts to utilize the existing session cookie established for that application,',
'    providing the following conditions are met:',
'    <ul>',
'        <li>',
'        Session State Protection is enabled for the application and the URL includes a valid checksum.',
'        For public bookmarks,',
'        the most restrictive item level protection must be either <em>Unrestricted</em> or <em>Checksum Required - Application Level</em>.',
'        </li>',
'        <li>',
'        OR, the URL does not contain payload (a request parameter, clear cache or data value pairs).',
'        </li>',
'    </ul>',
'    This setting also requires that Embed In Frames is set to Allow from same origin or to Deny for the application.',
'    </li>',
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
