 p_id=>wwv_flow_imp.id(875823623343323717)
,p_name=>'P509_BROWSER_CACHE'
,p_is_required=>true
,p_item_sequence=>240
,p_item_plug_id=>wwv_flow_imp.id(875541626713267923)
,p_use_cache_before_default=>'NO'
,p_item_default=>'N'
,p_prompt=>'Cache'
,p_source=>'BROWSER_CACHE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'BROWSER_CACHE'
,p_lov=>'.'||wwv_flow_imp.id(875788205897309215)||'.'
,p_cHeight=>1
,p_display_when=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select 1',
'  from wwv_flows',
' where id                  = :FB_FLOW_ID',
'   and compatibility_mode <> ''4.0''',
'   and security_group_id   = :flow_security_group_id'))
,p_display_when_type=>'EXISTS'
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'YES'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Use Cache to enable or disable browser caching of application page contents. If enabled, the browser saves the contents of pages for this application in its cache, both in memory and on disk. Typically when caching is enabled and the browser Back '
||'button is clicked, the page is loaded from the cache instead of from the server. If disabled, the browser is instructed not to save application page contents and to request the latest page content from the server whenever the URL changes. ',
'</p>',
'<p>To avoid the possibility of saving sensitive data, Oracle recommends that this attribute be disabled. Otherwise, it is possible to go back in the browser history after a logout and see cached content from a previous session. Disabling the browser '
||'cache also prevents issues with pages that use partial page refreshes, such as is the case with interactive reports.</p>',
'<p>If this attribute is set to <strong>Disabled</strong>, &PRODUCT_NAME. sends the HTTP header <em>Cache-Control: no-store</em>, which instructs the browser not to cache the page contents on disk or in memory.',
'</p>',
'<p>Note: This feature requires modern browsers that support the HTTP header response variable "Cache-Control".</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(885511105529258340)
,p_name=>'P509_VPD_TEARDOWN_CODE'
,p_item_sequence=>40
,p_item_plug_id=>wwv_flow_imp.id(107179319972706932)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Cleanup PL/SQL Code'
,p_source=>'VPD_TEARDOWN_CODE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'PLUGIN_COM.ORACLE.APEX.CODE_EDITOR'
,p_cSize=>96
,p_cMaxlength=>4000
,p_cHeight=>6
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_template_options=>'#DEFAULT#'
,p_escape_on_http_input=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Use this attribute to enter a PL/SQL block that runs at the end of page processing.',
'It can be used to free or clean up resources that were used, like VPD contexts or database links.',
'</p>',
'<p>Example 1:',
'<pre>',
'dbms_session.clear_context(''CTX_USER_QRY'');',
'</pre>',
'This call resets the application context named CTX_USER_QRY before the database session is given back to the session pool,',
'to ensure that no information will be leaked when it gets reused later on.',
'</p>',
'<p>Example 2:',
'<pre>',
'dbms_session.close_database_link(''SALES'');',
'</pre>',
'This call closes the database link SALES, which might have been opened in the "Initialization PL/SQL Code" or implicitly, just by querying data via the link.',
'Again, this frees resources and prevents resource leakage when the database session will be reused.',
'</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'PLSQL',
  'attribute_02', 'VARCHAR2',
  'attribute_03', 'Y',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1098121125859208369)
,p_name=>'P260_BROWSER_FRAME'
,p_is_required=>true
,p_item_sequence=>260
,p_item_plug_id=>wwv_flow_imp.id(875541626713267923)
,p_use_cache_before_default=>'NO'
,p_item_default=>'D'
,p_prompt=>'Embed in Frames'
,p_source=>'BROWSER_FRAME'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'BROWSER_FRAME'
,p_lov=>'.'||wwv_flow_imp.id(1098055005642193053)||'.'
,p_cHeight=>1
,p_display_when=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select 1',
'  from wwv_flows',
' where id                  = :FB_FLOW_ID',
'   and compatibility_mode <> ''4.0''',
'   and security_group_id   = :flow_security_group_id'))
,p_display_when_type=>'EXISTS'
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'YES'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'Use this attribute to control if the browser is allowed to display your application''s pages within a frame:',
'<ul>',
'<li><strong>Deny</strong>: The page cannot be displayed in a frame, regardless of the site attempting to do so.</li>',
'<li><strong>Allow from same origin</strong>: The page can only be displayed in a frame on the same origin as the page itself.</li>',
'<li><strong>Allow</strong>: The page can be displayed in any frame.</li>',
'</ul>',
'</p>',
'<p>',
'Displaying pages within frames can be misused with "clickjacking" attacks.',
'In a clickjacking attack the attacker uses multiple layers to trick a user into clicking a button or link on another page when they were intending to click on the top level page.',
'Thus, the attacker is hijacking clicks (or keystrokes) meant for their page and routing them to another page.',
'</p>',
'<p>',
'Dialog pages are often displayed within an iframe,',
'which would normally not work with the attribute value "Deny".',
'A dialog page template''s attribute <em>Allow Embed In Frame</em> defines whether "Allow from same origin" should be used instead of "Deny",',
'for pages that use such a template.',
'To protect against clickjacking,',
'&PRODUCT_NAME. uses a page-specific checksum in dialog page URLs.',
'</p>',
'<p>',
'Note: This feature requires modern browsers that support the HTTP header response variable "X-Frame-Options".',
'</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
