,p_plug_display_sequence=>130
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select id as "PAGE",',
'	   name as "Name",',
'	   decode(',
'           nvl(PROTECTION_LEVEL,''N''),',
'           ''N'', m.n,',
'           ''C'', m.c,',
'           ''U'', m.u,',
'           ''D'', m.d,',
'           protection_level) as "Protection",',
'       (select count(*)',
'          from wwv_flow_step_items',
'         where flow_step_id      = p.id',
'           and flow_id           = :FB_FLOW_ID',
'           and security_group_id = :FLOW_SECURITY_GROUP_ID) page_items,',
'       id,',
'       p.page_type,',
'       nvl(last_updated_on,created_on) updated,',
'       nvl(last_updated_by,created_by) updated_by,',
'       decode(',
'           nvl(p.page_is_public_y_n,''N''),',
'           ''Y'', t_yes,',
'           ''N'', t_no) page_is_public_y_n,',
'       decode(nvl(p.allow_duplicate_submissions,''Y''),',
'          ''Y'', t_yes,',
'          ''N'', t_no) allow_duplicate_submissions',
'  from wwv_flow_pages_dev p,',
'       (select wwv_flow_lang.system_message(''UNRESTRICTED'') n,',
'               wwv_flow_lang.system_message(''ARGUMENTS_MUST_HAVE_CHECKSUM'') c,',
'               wwv_flow_lang.system_message(''NO_ARGUMENTS_ALLOWED'') u,',
