wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(107454504672085768)
,p_name=>'P515_PROTECTION_LEVEL'
,p_item_sequence=>70
,p_item_plug_id=>wwv_flow_imp.id(107452431597085754)
,p_use_cache_before_default=>'NO'
,p_item_default=>'N'
,p_prompt=>'Page Access Protection'
,p_source=>'PROTECTION_LEVEL'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'PAGE PROTECTION LEVEL'
,p_lov=>'.'||wwv_flow_imp.id(17255429593772638)||'.'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_escape_on_http_input=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Select a Page Access Protection Level:',
'<ul>',
'<li><strong>Unrestricted</strong> - The page may be requested using an URL with or without session state arguments (Request, Clear Cache, Name/Values).</li>',
'<li><strong>Arguments Must Have Checksum</strong> - If Request, Clear Cache, or Name/Value arguments appear in the URL, a checksum must also be provided. The checksum type must be compatible with the most stringent Session State Protection attribute '
||'of all the items passed as arguments.</li>',
'<li><strong>No Arguments Allowed</strong> - A URL may be used to request the page but no Request, Clear Cache, or Name/Value arguments are allowed.</li>',
'<li><strong>No URL Access</strong> - The page may not be accessed using a URL, however the page may be the target of a Branch to Page branch type, which does not do a URL redirect.</li> ',
'</ul>    '))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
