,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_escape_on_http_input=>'N'
,p_escape_on_http_output=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Enabling Session State Protection is a two step process:',
'<ol>',
'<li>Enable the feature</li>',
'<li>Configure page and item security attributes</li>',
'</ol>',
'For Select Action, select one of the following and click <strong>Next</strong>:',
'<ul>',
'<li><strong>Disable</strong> - Disables Session State Protection. Note that disabling Session State Protection will not affect previously configured page and item security attributes.',
'<li><strong>Enable</strong> -  Enables Session State Protection. When enabled, Session State Protection, uses the <i>Page Access Protection</i> page attributes and the Session State Protection item attributes in conjunction with checksums positioned '
||'in "f?p=" URLs to prevent URL tampering and unauthorized access to and alteration of session state. ',
'<li><strong>Configure</strong> - Configure page and item security attributes and apply them to all pages and items within the application.',
'<p><strong>Note:</strong> You can also adjust page and item security attributes manually. Select <strong>Enable</strong>, return to the Session State Protection page, and click the appropriate icon.</li>',
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'number_of_columns', '1',
  'page_action_on_selection', 'NONE')).to_clob
);
