wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(3405738497955649)
,p_name=>'Template Component References'
,p_template=>wwv_flow_imp.id(174794400314076650)
,p_display_sequence=>110
,p_region_template_options=>'#DEFAULT#:a-Region--noTopBorder:a-Region--noPadding:a-Region--noBorder:a-Region--accessibleHeader'
,p_component_template_options=>'#DEFAULT#:a-Report--stretch'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select p.builder_name                                         as template_name,',
'       p.id                                                   as template_id,',
'       pg.name                                                as page_name,',
'       r.plug_name                                            as region,',
'       r.page_id                                              as page,',
'       wwv_flow_lang.system_message(''F4000.REGION'')         as object_type,',
'       to_char(null)                                          as object_name',
'  from wwv_theme_template_components    p,',
'       wwv_flow_page_plugs           r,',
'       wwv_flow_steps                pg',
' where p.theme_id           is not null',
'   and r.flow_id            = p.flow_id',
'   and r.security_group_id  = p.security_group_id',
'   and r.plug_source_type   = p.used_name',
'   and pg.flow_id           = r.flow_id',
'   and pg.id                = r.page_id',
'   and pg.security_group_id = r.security_group_id',
'   and (    :P707_FIND                                  is null ',
'         or instr(upper(r.plug_name),upper(:P707_FIND)) > 0',
'         or instr(r.page_id,:P707_FIND)                 > 0 )',
'union all',
'select p.builder_name                                         as template_name,',
'       p.id                                                   as template_id,',
'       pg.name                                                as page_name,',
'       r.plug_name                                            as region,',
'       c.page_id                                              as page,',
'       wwv_flow_lang.system_message(''F4000.REPORT_COLUMN'')    as object_type,',
'       c.db_column_name                                       as object_name',
'  from wwv_theme_template_components  p,',
'       wwv_flow_worksheet_columns    c,',
'       wwv_flow_worksheets           w,',
'       wwv_flow_page_plugs           r,',
'       wwv_flow_steps                pg',
' where p.theme_id           is not null',
'   and c.flow_id            = p.flow_id',
'   and c.security_group_id  = p.security_group_id',
'   and c.display_text_as    = p.used_name',
'   and w.id                 = c.worksheet_id',
'   and w.flow_id            = p.flow_id',
'   and w.security_group_id  = p.security_group_id',
'   and r.id                 = w.region_id',
'   and r.flow_id            = p.flow_id',
'   and r.security_group_id  = p.security_group_id',
'   and pg.flow_id           = r.flow_id',
'   and pg.id                = r.page_id',
'   and pg.security_group_id = r.security_group_id',
'   and (    :P707_FIND                                  is null ',
'         or instr(upper(r.plug_name),upper(:P707_FIND)) > 0',
'         or instr(r.page_id,:P707_FIND)                 > 0 )'))
,p_display_when_condition=>'P707_TEMPLATE_TYPE'
,p_display_when_cond2=>'TEMPLATE_COMPONENT'
,p_display_condition_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(123728124628276646)
