,p_validation_name=>'MustHaveSomethingToCopy'
,p_validation_sequence=>20
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'begin',
'for i in 1..wwv_flow.g_f03.count loop',
'  if wwv_flow.g_f02(i) in (''Y'',''SUBSCRIBE'')',
'     then return null;',
'  end if;',
'end loop;',
'return wwv_flow_lang.system_message(''F4000.P818.VALIDATION'');',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_error_message=>'Must have something to copy.'
,p_when_button_pressed=>wwv_flow_imp.id(1270617619132554)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(8281153296864401)
,p_validation_name=>'No Duplicate Subscriptions'
,p_validation_sequence=>30
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'for i in 1..wwv_flow.g_f03.count loop',
'    if wwv_flow.g_f02(i) = ''SUBSCRIBE'' then',
'        for j in (',
'            select m.name',
'              from wwv_flow_authentications s,',
'                   wwv_flow_authentications m',
'             where s.flow_id           = :FB_FLOW_ID',
'               and s.security_group_id = :WORKSPACE_ID',
'               and s.reference_id      = wwv_flow.g_f03(i)',
'               and s.reference_id      = m.id',
'               and m.security_group_id = :WORKSPACE_ID )',
'        loop',
'            return wwv_flow_lang.system_message( ',
'                       p_name => ''F4000.P818.VALIDATION.NO_DUPLICATE_SUBSCRIPTION'',',
'                       p0     => j.name );',
'        end loop;               ',
'    end if;',
'end loop;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_when_button_pressed=>wwv_flow_imp.id(1270617619132554)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(8281285366864402)
,p_validation_name=>'No Duplicate Names'
,p_validation_sequence=>40
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare ',
'    l_name wwv_flow_authentications.name%type;',
'begin    ',
'    for i in 1..wwv_flow.g_f03.count loop',
'        if wwv_flow.g_f02(i) = ''SUBSCRIBE'' then',
'            select name ',
'              into l_name',
'              from wwv_flow_authentications',
'             where id                = wwv_flow.g_f03(i)',
'               and security_group_id = :WORKSPACE_ID;',
'        elsif wwv_flow.g_f02(i) = ''Y'' then ',
'            l_name := wwv_flow.g_f01(i);',
'        end if;',
'',
'        for j in (',
'            select name',
'              from wwv_flow_authentications s',
'             where s.flow_id           = :FB_FLOW_ID',
'               and s.security_group_id = :WORKSPACE_ID',
'               and s.name              = l_name )',
'        loop',
'            return wwv_flow_lang.system_message( ',
