,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(253961620789367687)
,p_plug_name=>'Select Page'
,p_region_template_options=>'#DEFAULT#:a-IRR-region--noOuterBorders:a-IRR-region--responsiveIconView'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(646287526247383209)
,p_plug_display_sequence=>10
,p_plug_display_column=>1
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select id,',
'       the_flow,',
'       name,',
'       updated,',
'       last_updated_by,',
'       created_on,',
'       nvl(group_name,sm.t_unassigned) group_name,',
'       page_type,',
'       alias,',
'       page_title,',
'       nbr_items,',
'       nbr_report_cols',
'  from (select p.id,',
'               p.flow_id the_flow,',
'               name,',
'               last_updated_on updated,',
'               lower(last_updated_by) last_updated_by,',
'               created_on,',
'               g.group_name,',
'               page_component_map,',
'               alias,',
'               step_title page_title,',
'               p.page_type,',
'               (select count(*)',
'                  from wwv_flow_step_items i,',
'                       wwv_flow_page_plugs r',
'                 where nvl(i.display_when_type,''disp'') != ''NEVER''',
'                   and i.display_as not in (''NATIVE_HIDDEN'',''NATIVE_STOP_AND_START_HTML_TABLE'')',
'                   and i.security_group_id  = :FLOW_SECURITY_GROUP_ID',
'                   and i.flow_id            = p.flow_id',
'                   and i.flow_step_id       = p.id',
'                   and i.item_plug_id       = r.id',
'                   and nvl(r.plug_display_condition_type,''disp'') != ''NEVER''',
'                   and r.security_group_id  = :FLOW_SECURITY_GROUP_ID',
'                   and r.flow_id            = p.flow_id',
'                   and r.page_id            = p.id) nbr_items,',
'               (select count(*)',
'                  from wwv_flow_region_report_column rc,',
'                       wwv_flow_page_plugs r',
'                 where rc.hidden_column = ''N''',
'                   and nvl(rc.display_when_cond_type,''disp'') != ''NEVER''',
'                   and rc.security_group_id = :FLOW_SECURITY_GROUP_ID',
'                   and rc.flow_id           = p.flow_id',
'                   and rc.region_id         = r.id',
'                   and nvl(r.plug_display_condition_type,''disp'') != ''NEVER''',
'                   and r.security_group_id  = :FLOW_SECURITY_GROUP_ID',
'                   and r.flow_id            = p.flow_id',
'                   and r.page_id            = p.id',
'                   and substr(rc.column_alias,1,6) != ''CHECK$''',
'                   and substr(rc.column_alias,1,5) != ''LINK$''',
'                   and substr(rc.column_alias,1,8) != ''DERIVED$'') +',
'               (select count(*)',
'                  from wwv_flow_worksheet_columns wc,',
'                       wwv_flow_worksheets w,',
'                       wwv_flow_page_plugs r',
'                 where nvl(wc.display_text_as,''disp'') != ''HIDDEN''',
'                   and wc.security_group_id = :FLOW_SECURITY_GROUP_ID',
'                   and wc.flow_id           = p.flow_id',
'                   and wc.worksheet_id      = w.id',
'                   and w.security_group_id  = :FLOW_SECURITY_GROUP_ID',
'                   and w.flow_id            = p.flow_id',
'                   and w.page_id            = p.id',
'                   and w.region_id          = r.id',
'                   and nvl(r.plug_display_condition_type,''disp'') != ''NEVER''',
'                   and r.security_group_id  = :FLOW_SECURITY_GROUP_ID',
'                   and r.flow_id            = p.flow_id',
'                   and r.page_id            = p.id) nbr_report_cols',
'          from wwv_flow_pages_dev p,',
'               wwv_flow_page_groups g',
'         where p.flow_id           = :FB_FLOW_ID',
'           and p.security_group_id = :FLOW_SECURITY_GROUP_ID',
'           and p.group_id          = g.id (+)),',
'       (select wwv_flow_lang.system_message(''Unassigned'') t_unassigned',
'          from dual) sm'))
,p_plug_source_type=>'NATIVE_IR'
,p_plug_query_show_nulls_as=>' - '
,p_pagination_display_position=>'BOTTOM_RIGHT'
);
