wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(73941629713235925)
,p_validation_name=>'P902_THEME unique'
,p_validation_sequence=>30
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with central_theme as (',
'    select wwv_flow_theme_manager.get_central_application_id( :FB_FLOW_ID, :P902_THEME ) as application_id,',
'           wwv_flow_theme_manager.get_central_theme_id( :FB_FLOW_ID, :P902_THEME )       as theme_id,',
'           wwv_flow_theme_manager.get_central_workspace_id( :FB_FLOW_ID, :P902_THEME )   as workspace_id',
'      from sys.dual',
')',
'',
'select 1',
'  from wwv_flow_page_plug_templates ppt,',
'       central_theme ct',
' where ( ppt.flow_id, ppt.theme_id, ppt.security_group_id ) in',
'       (',
'        ( :FB_FLOW_ID, :P902_THEME, :WORKSPACE_ID ),',
'        ( ct.application_id, ct.theme_id, ct.workspace_id )',
'       )',
'   and ppt.page_plug_template_name = :P902_NAME'))
,p_validation_type=>'NOT_EXISTS'
,p_error_message=>'#LABEL# must be unique.'
,p_when_button_pressed=>wwv_flow_imp.id(106647404038700884)
,p_associated_item=>wwv_flow_imp.id(98321416048032372)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
