,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>The Report Columns listed were matched to existing columns in the Attribute Dictionary.  Select those you wish to update and indicate which attributes you wish to include in the update.</p>',
'',
'<p>Note: Help Text is only available within Interactive Reports. If you are updating Columns in a Standard Report, Help Text is not shown.  For Standard Reports, if your column headings are based upon PL/SQL, they will not be overwritten, anything ot'
||'her than PL/SQL will be changed to Custom in order for the new column headings to be displayed.</p>'))
,p_plug_query_headings_type=>'QUERY_COLUMNS'
,p_plug_query_num_rows=>15
,p_plug_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_plug_query_show_nulls_as=>' - '
,p_pagination_display_position=>'BOTTOM_RIGHT'
