wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(73941399520235922)
,p_validation_name=>'P924_NAME unique'
,p_validation_sequence=>20
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with central_theme as (',
'    select wwv_flow_theme_manager.get_central_application_id( :FB_FLOW_ID, :P924_THEME ) as application_id,',
'           wwv_flow_theme_manager.get_central_theme_id( :FB_FLOW_ID, :P924_THEME )       as theme_id,',
'           wwv_flow_theme_manager.get_central_workspace_id( :FB_FLOW_ID, :P924_THEME )   as workspace_id',
'      from sys.dual',
')',
'',
'select 1',
'  from wwv_flow_templates t,',
'       central_theme ct',
' where ( t.flow_id, t.theme_id, t.security_group_id ) in',
'       (',
'        ( :FB_FLOW_ID, :P924_THEME, :WORKSPACE_ID ),',
'        ( ct.application_id, ct.theme_id, ct.workspace_id )',
'       )',
'   and t.name = :P924_NAME'))
,p_validation_type=>'NOT_EXISTS'
,p_error_message=>'#LABEL# must be unique.'
,p_when_button_pressed=>wwv_flow_imp.id(122619509673470584)
