wwv_flow_imp_page.create_page(
 p_id=>971
,p_name=>'Manage Application Backups'
,p_alias=>'MANAGE-APPLICATION-BACKUPS'
,p_step_title=>'Manage Backups'
,p_autocomplete_on_off=>'OFF'
,p_group_id=>wwv_flow_imp.id(5507013954294272)
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'// Replace $<token>$ substitutions in URLs.',
'// Note how generic this code is. The only thing specific to the example is',
'// the name of the menu (ir_context_menu) and the button class (ir-actions-btn).',
'// It could easily be turned into a function and moved to a JavaScript file to',
'// be used from any number of reports.',
'const RE_DATA_SUBST = /(?:%24|\$)(\w+)(?:%24|\$)/g;',
'',
'let menu$ = $( "#mb_context_menu" ),',
'    items = menu$.menu( "option" ).items;',
'',
'function substitute( urlTemplate, context$ ) {',
'    if ( !urlTemplate ) {',
'        return;',
'    }',
'    return urlTemplate.replace( RE_DATA_SUBST, function( m, token ) {',
'        return context$.attr( "data-" + token );',
'    } );',
'}',
'',
'items = items.map( ( item ) => {',
'    if ( item.action === "a-dialog-open" ) {',
'        item.urlTemplate = item.args.url;',
'        item.prepareUrl = function( context$ ) {',
'            this.args.url = substitute( this.urlTemplate, context$ );',
'        }',
'    } else {',
'        // regular URL',
'        item.urlTemplate = item.href;',
'        item.prepareUrl = function( context$ ) {',
'            this.href = substitute( this.urlTemplate, context$ );',
'        }',
'    }',
'    return item;',
'} );',
'',
'',
'// When the menu opens',
'menu$.on( "menubeforeopen", function( event, data ) {',
'    // This is how to get the context. Would be nice if the beforeopen',
'    // event could tell you directly what button opened it',
'    const context$ = $( ".ir-actions-btn.is-active" ); ',
'',
'    let items = data.menu.items; ',
'    ',
'    items = items.map( ( item ) => {',
'        if ( item.prepareUrl ) {',
'            item.prepareUrl( context$ );',
'        }',
'        return item;',
'    } );',
'});'))
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'.t-Body-inlineDialogs {border: 0;clip: rect(0 0 0 0);height: 1px;margin: -1px;overflow: hidden;padding: 0;position: absolute;width: 1px;}',
''))
,p_page_template_options=>'#DEFAULT#'
,p_page_component_map=>'18'
);
