,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Add feature push notifications'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'    declare',
'    l_feature_page       wwv_flow_app_feature_v3.t_feature_page;',
'    l_user_settings_page wwv_flow_app_feature_v3.t_user_settings_page;',
'    l_credentials_id     number;',
'begin',
'    l_feature_page.page_id := :P1318_PAGE_ID;',
'',
'    if :P1318_USER_SETTINGS_PAGE_TYPE = ''NEW'' then',
'        l_user_settings_page.page_id := :P1318_USER_SETTINGS_PAGE_ID;',
'    elsif :P1318_USER_SETTINGS_PAGE_TYPE = ''EXISTING'' then',
'        l_user_settings_page.page_id := :P1318_EXISTING_PAGE;',
'    end if;',
'',
'    l_user_settings_page.include_in_navbar := ( :P1318_USER_SETTINGS_PAGE_TYPE = ''NEW'' );',
'',
'    wwv_flow_app_feature_v3.add_feature_push_notifications(',
'        p_app_id             => :FB_FLOW_ID,',
'        p_feature_page       => l_feature_page,',
'        p_user_settings_page => l_user_settings_page );',
'',
'    :FB_FLOW_PAGE_ID := l_user_settings_page.page_id;',
'',
'    l_credentials_id := wwv_flow_pwa_dev.generate_push_credentials (',
'                            p_application_id  => :FB_FLOW_ID );',
'',
'    update wwv_flows',
'       set pwa_is_push_enabled = ''Y''',
'     where id                  = :FB_FLOW_ID',
'       and security_group_id   = :WORKSPACE_ID',
'       and pwa_is_push_enabled = ''N'';',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(20215994890240611)
,p_process_success_message=>'Push notification settings page created.'
,p_internal_uid=>20227560024240635
);
