,p_plug_display_column=>1
,p_plug_display_point=>'REGION_POSITION_03'
,p_plug_item_display_point=>'BELOW'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Create a <strong>REST Enabled SQL</strong> service to execute SQL or PL/SQL defined in &PRODUCT_NAME. components on a remote Oracle database.</p>',
'',
'<p><strong>Requirement:</strong> The remote database must include Oracle REST Data Services (ORDS) release 20.3 or later on the front-end and have the <em>REST Enabled SQL</em> feature enabled. All SQL and PL/SQL is sent to the ORDS instance which ex'
||'ecutes it on the remote database.</p>',
'',
'<p>REST Enabled SQL references are stored at the workspace level and therefore visible in all applications.</p>',
'',
'<p>When you export an application, used REST Enabled SQL references are added to the export file. If you export an application and import it into another workspace, &PRODUCT_NAME. checks whether the target workspace already contains REST Enabled SQL '
||'references with the same <strong>static ID</strong>. If a REST Enabled SQL reference already exists, the application uses the existing reference. If the reference does not exist, it is created in the target workspace.</p>'))
,p_plug_display_condition_type=>'EXPRESSION'
,p_plug_display_when_condition=>'nvl(#OWNER#.wwv_flow_preferences.get_preference(''FP_PREF_SHOW_INFORMATION''),''YES'') = ''YES'''
,p_plug_display_when_cond2=>'PLSQL'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
