wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(157709882691474177)
,p_plug_name=>'REST Enabled SQL Servers'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(646287526247383209)
,p_plug_display_sequence=>30
,p_plug_new_grid_row=>false
,p_plug_display_column=>1
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select id,',
'       server_name,',
'       --',
'       -- Usable',
'       case when remote_sql_database_type is not null then ''check'' else ''remove'' end as is_usable_icon,',
'       wwv_flow_lang_dev.builder_message( ''WWV_FLOW_EXEC_REMOTE.SERVER_IS_'' || case when remote_sql_database_type is null then ''UN'' end || ''USABLE'' ) as is_usable_text,',
'       --',
'       base_url,',
'       nvl2( configuration_procedure, ''Y'', ''N'' ) dynamic,',
'       authentication_type,',
'       --',
'       -- REST Enabled SQL database details',
'       remote_sql_database_type,',
'       case when remote_sql_database_type is not null ',
'            then nullif( ',
'                     json_value( remote_sql_database_info, ''$.database_major_version'' ) ',
'                     || ''.''',
'                     || json_value( remote_sql_database_info, ''$.database_minor_version'' ),',
'                    ''.'' ) ',
'       end as remote_sql_database_version,',
'       case when remote_sql_database_type is not null ',
'            then remote_sql_default_schema ',
'       end as remote_sql_default_schema,',
'       --',
'       -- Icon View',
'       wwv_flow_utilities.prepare_url(''f?p=4000:1601:'' || :APP_SESSION || '':::1601:P1601_ID:'' || id ) as link,',
'       ''icon-admin-workspace-preferences'' as img,',
'       --',
'       -- Test Button',
'       wwv_flow_utilities.prepare_url(''f?p=4000:1605:'' || :APP_SESSION || ''::''|| :DEBUG || '':1605:P1605_ID:'' || id) as test_link',
'  from wwv_remotesql_servers_dev ',
' where security_group_id = :flow_security_group_id',
'       '))
,p_plug_source_type=>'NATIVE_IR'
,p_plug_query_show_nulls_as=>' - '
,p_pagination_display_position=>'BOTTOM_RIGHT'
);
