,p_validation_type=>'ITEM_NOT_NULL'
,p_error_message=>'Client ID or Username is required.'
,p_validation_condition=>'wwv_flow.g_request in ( ''Create'', ''Update'' ) and :P1601_AUTH_REQUIRED = ''Y'' and :P1601_CRED_STORE is null'
,p_validation_condition2=>'PLSQL'
,p_validation_condition_type=>'EXPRESSION'
,p_associated_item=>wwv_flow_imp.id(153985439821443615)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
