wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(9470935922569850)
,p_validation_name=>'Credential Static ID must be unique'
,p_validation_sequence=>20
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select id',
'  from wwv_credentials',
' where security_group_id = :FLOW_SECURITY_GROUP_ID',
'   and static_id         = regexp_replace( lower( :P1616_CREDENTIALS_NAME ), ''[^abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ1234567890]+'', ''_'' )'))
,p_validation_type=>'NOT_EXISTS'
,p_error_message=>wwv_flow_string.join(wwv_flow_t_varchar2(
'The credential name "&P1616_CREDENTIALS_NAME!HTML." will lead to a static ID which is already taken. Choose a different name.',
''))
,p_validation_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_result number;',
'begin',
'    l_result := case when :P1616_CRED_STORE is not null then 1 end;',
'',
'    if l_result is null then',
'        begin',
'            select 1',
'              into l_result',
'              from wwv_credentials',
'             where security_group_id = :FLOW_SECURITY_GROUP_ID',
'               and name              = :P1616_CREDENTIALS_NAME',
'               and rownum            = 1;',
'        exception',
'            when NO_DATA_FOUND then null;',
'        end;',
'    end if;',
'',
'    return l_result is null;',
'end;'))
,p_validation_condition2=>'PLSQL'
,p_validation_condition_type=>'FUNCTION_BODY'
,p_when_button_pressed=>wwv_flow_imp.id(249362037539932994)
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
