wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(2545228608236501)
,p_name=>'P1621_USE_DB_CREDENTIAL'
,p_item_sequence=>70
,p_item_plug_id=>wwv_flow_imp.id(308592151420746764)
,p_prompt=>'Use Database Credential'
,p_display_as=>'NATIVE_YES_NO'
,p_display_when=>'wwv_flow_db_version.c_has_utl_http_credential'
,p_display_when2=>'PLSQL'
,p_display_when_type=>'EXPRESSION'
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'    Enable to use the secrets stored within a database credential.',
'    Available credentials can be obtained from the <strong>ALL_CREDENTIALS</strong>',
'    dictionary view. Use the <strong>DBMS_CREDENTIAL</strong> package ',
'    to maintain database credentials.</p>',
'<p>',
'    <em>Using a database credential changes the behavior of HTTP requests being done and how Web Credentials work:</em></p>',
'<ul>',
'    <li>',
'        If a database credential is used, all HTTP requests will be done in the ',
'        context of the application''s parsing schema, and not in the context of the',
'        APEX engine. That means that <em>PL/SQL network ACLs</em> must be granted',
'        to the application''s parsing schema. See the documentation for the',
'        <strong>DBMS_NETWORK_ACL_ADMIN</strong> for more details.</li>',
'    <li>',
'        A database credential is completely maintained by the database, &PRODUCT_NAME.',
'        does not have access to the stored secrets. As &PRODUCT_NAME. thus cannot enforce ',
'        the <strong>Valid for URLs</strong> attribute, this attribute is disabled when a',
'        database credential is used.</li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'use_defaults', 'Y')).to_clob
);
