wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(21464803891466404)
,p_validation_name=>'Credential Static ID is unique'
,p_validation_sequence=>70
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select id',
'  from wwv_credentials',
' where security_group_id  = :FLOW_SECURITY_GROUP_ID',
'   and static_id         = regexp_replace( lower( nvl( :P1621_CREDENTIALS_STATIC_ID,:P1621_CREDENTIALS_NAME ) ), ''[^abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ1234567890]+'', ''_'' )',
'   and ( id != :P1621_ID or :P1621_ID is null )'))
,p_validation_type=>'NOT_EXISTS'
,p_error_message=>'The credential Static ID (provided or derived from the name) must be unique within the application.'
,p_validation_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_result number;',
'begin',
'    l_result := case when :REQUEST in (''Update'',''Create'') then null else 1 end;',
'',
'    if l_result is null then',
'        begin',
'            select 1',
'              into l_result',
'              from wwv_credentials',
'             where security_group_id = :FLOW_SECURITY_GROUP_ID',
'               and name              = :P1621_CREDENTIALS_NAME',
'               and ( id != :P1621_ID or :P1621_ID is null )',
'               and rownum            = 1;',
'        exception',
'            when NO_DATA_FOUND then null;',
'        end;',
'    end if;',
'',
'    return l_result is null;',
'end;'))
,p_validation_condition2=>'PLSQL'
,p_validation_condition_type=>'FUNCTION_BODY'
,p_associated_item=>wwv_flow_imp.id(385808740658243612)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
