,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'    A <strong>Data Load Definition</strong> allows developers to add <em>Data Loading</em> ',
'    functionality to an Oracle APEX application.',
'</p>',
'<p>',
'    A Data Load Definition consists of information about where to store uploaded ',
'    data, as well as details about the loading method, for instance whether to ',
'    <em>append</em> data or whether to <em>replace</em> existing data. ',
'    It can be referenced in <strong>Data Loading</strong> page processes, ',
'    as well as with the <code>APEX_DATA_LOADING</code> PL/SQL package.',
'</p>',
'<p>',
'    The <strong>Data Profile</strong> contains information about ',
'    structure of uploaded data, and about additional columns',
'     based on SQL Expression, SQL Query, Lookups or Transformation Rules.',
'</p>',
'<p>',
'    After creating the Data Load Definition, the wizard allows you to add a ',
'    Data Loading page to your application. The created page can be customized ',
'    afterwards to meet the needs of your application.',
'</p>'))
,p_plug_query_headings_type=>'QUERY_COLUMNS'
,p_plug_query_show_nulls_as=>' - '
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
