wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(212980031120458358)
,p_plug_name=>'Manage Concurrency'
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(174794400314076650)
,p_plug_display_sequence=>50
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_item_display_point=>'BELOW'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>This option gives the developer the option to specify a column that can used to check against the version of the data in the underlying table. This is particularly important if uploading into a table that is regularly updated.</p>',
'<p>For any updates, the column used to check concurrency will be queried and compared against the database value, for that column, before committing the record. If between the time the record is queried and the data upload is processed the concurrent'
||' column is changed, then the record will be flagged and not committed. If the concurrency column is not specified then the data upload will always update all records, potentially overwriting any changes made by other users.</p>'))
,p_plug_query_headings_type=>'QUERY_COLUMNS'
,p_plug_query_num_rows=>15
,p_plug_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_plug_query_show_nulls_as=>' - '
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
