,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Initialize Create Page Wizard'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_page_type_display     wwv_flow_page_types_dev.page_type_display%type;',
'    l_ut_nav_icon           wwv_flow_page_types_dev.ut_nav_icon%type;',
'    l_navigation_type       wwv_flow_themes.navigation_type%type;',
'    l_navlist_id            wwv_flows.navigation_list_id%type;',
'    l_is_navlist_subscribed varchar2(1);',
'    l_navbar_id             wwv_flows.nav_bar_list_id%type;',
'    l_theme_id              number;',
'    l_is_ut_based           varchar2(1);',
'    l_is_rw_based           varchar2(1);',
'    l_is_font_apex          varchar2(1);',
'begin',
'    htmldb_util.clear_page_cache(2500);',
'',
'    wwv_flow_wizard_api.init_create_page_wiz(',
'        p_application_id        => :FB_FLOW_ID,',
'        p_navigation_type       => l_navigation_type,',
'        p_navlist_id            => l_navlist_id,',
'        p_is_navlist_subscribed => l_is_navlist_subscribed,',
'        p_navbar_id             => l_navbar_id,',
'        p_theme_id              => l_theme_id,',
'        p_is_ut_based           => l_is_ut_based,',
'        p_is_rw_based           => l_is_rw_based,',
'        p_is_font_apex          => l_is_font_apex );',
'',
'    select page_type_display,',
'           case when l_is_ut_based = ''Y'' and l_is_font_apex = ''Y'' then ut_nav_icon end',
'      into l_page_type_display,',
'           l_ut_nav_icon',
'      from wwv_flow_page_types_dev',
'     where page_type = ''DATALOAD'';',
'',
'    htmldb_util.set_session_state( ''P2500_NAVIGATION_TYPE'', l_navigation_type );',
'    htmldb_util.set_session_state( ''P2500_NAVLIST_ID'', l_navlist_id );',
'    htmldb_util.set_session_state( ''P2500_IS_NAVLIST_SUBSCRIBED'', l_is_navlist_subscribed );    ',
'    htmldb_util.set_session_state( ''P2500_NAVBAR_ID'', l_navbar_id );',
'    htmldb_util.set_session_state( ''FB_THEME_ID'', l_theme_id );',
'    htmldb_util.set_session_state( ''P2500_IS_UT_BASED'', l_is_ut_based );',
'    htmldb_util.set_session_state( ''P2500_IS_RW_BASED'', l_is_rw_based );',
'    htmldb_util.set_session_state( ''P2500_IS_FONT_APEX'', l_is_font_apex );',
'    htmldb_util.set_session_state( ''P2500_PAGE_TYPE'', ''DATALOAD'' );',
'    htmldb_util.set_session_state( ''P2500_PAGE_TYPE_DISPLAY'', l_page_type_display );',
'    htmldb_util.set_session_state( ''P2500_UT_NAV_ICON'', l_ut_nav_icon );',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(1999513044366605)
,p_internal_uid=>4613432590691750
);
