,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'    Specify how to handle errors during data load. Possible values are:',
'</p>',
'<ul>',
'    <li><strong>Ignore</strong>: The error rows are silently ignored, and Data Loading simply continues.</li>',
'    <li><strong>Stop</strong>: The data loading stops on the first error and raises an error message.</li>',
'    <li><strong>Log into Collection</strong>: Error rows are logged into an &PRODUCT_NAME. collection.</li>',
'    <li><strong>Log into Error Log</strong>: Error rows are logged into a DML error logging table using the <strong>DML Error Logging</strong> database functionality. This is only available when loading into a table, and only if the <strong>Append</s'
||'trong> method is used <em>without</em> a primary key.</li>',
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
