'                                 p_app_id        => :FB_FLOW_ID,',
'                                 p_url           => :P1850_BASE_URL || :P1850_BUCKET_NAME,',
'                                 p_credential_id => :P1850_CREDENTIAL_ID );'))
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(2410971611988425)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'migrate to object storage'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_sum_bytes number;',
'begin',
'    select sum(sys.dbms_lob.getlength(file_content))',
'      into l_sum_bytes',
'      from wwv_flow_static_files',
'     where security_group_id = :WORKSPACE_ID',
'       and flow_id = :FB_FLOW_ID;',
'',
'    if l_sum_bytes > wwv_flow_object_store.c_max_sync_bytes then --background',
'        wwv_flow_object_store.migrate_bg(',
'            p_app_id       => :FB_FLOW_ID,',
'            p_session_id   => :FLOW_SESSION,',
'            p_workspace_id => :WORKSPACE_ID );',
'    else',
'        wwv_flow_object_store.migrate(',
'            p_app_id       => :FB_FLOW_ID,',
'            p_workspace_id => :WORKSPACE_ID );       ',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'#SQLERRM#'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(3801122087547848)
,p_process_when=>'P1851_MIGRATE_FILES'
,p_process_when_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
,p_process_when2=>'Y'
,p_process_success_message=>'Files migrated to Object Storage.'
,p_internal_uid=>2410971611988425
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(9035702284844501)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Set Application File Storage'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_server_id         number;',
'begin',
'    insert into wwv_remote_servers (',
'        name,',
'        static_id,',
'        base_url,',
'        server_type,',
'        prompt_on_install,',
'        credential_id',
'    ) values (',
'        :P1850_NAME,',
'        :P1850_STATIC_ID,',
'        :P1850_BASE_URL||:P1850_BUCKET_NAME||''/o/'',',
'        ''CLOUD_OBJECT_STORE'',',
'        ''Y'',',
'        :P1850_CREDENTIAL_ID',
'        )',
'    returning id into l_server_id;',
'',
'    update wwv_flows',
'       set file_storage           = ''OBJECT_STORE'',',
'           file_remote_server_id  = l_server_id',
'     where id                     = :FB_FLOW_ID',
'       and security_group_id      = :FLOW_SECURITY_GROUP_ID;',
'',
'    if wwv_flow_collection.collection_exists(''F4000_OB_FILES'') then',
'        wwv_flow_collection.delete_collection(''F4000_OB_FILES'');',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'P1851_RESULT'
,p_process_when_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
,p_process_when2=>'success'
,p_internal_uid=>9035702284844501
);
end;
