wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(3292574859489450)
,p_name=>'P1921_WEB_SOURCE_TYPE'
,p_is_required=>true
,p_item_sequence=>60
,p_item_plug_id=>wwv_flow_imp.id(3292099913489445)
,p_use_cache_before_default=>'NO'
,p_prompt=>'REST Data Source Type'
,p_source=>'WEB_SOURCE_TYPE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'WEB_SOURCE_MODULE_TYPES'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select d,',
'       r',
'  from (',
'         select wwv_flow_lang.system_message(''WEB_SOURCE.''|| name_with_prefix) as d,',
'               name_with_prefix as r',
'          from wwv_flow_native_plugins',
'         where plugin_type = ''WEB SOURCE TYPE''',
'         union all',
'        select display_name || wwv_flow_lang.system_message(''PLUGIN.DISPLAY_NAME_POSTFIX'') as d,',
'               ''PLUGIN_'' || name     as r',
'          from wwv_flow_plugins',
'         where flow_id           = to_number(:FB_FLOW_ID)',
'           and security_group_id = to_number(:WORKSPACE_ID)',
'           and plugin_type       = ''WEB SOURCE TYPE''',
'       )',
' order by 1'))
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(452656722938220607)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Determines the REST Data Source type.',
'<ul>',
'<li><strong>Simple HTTP</strong> denotes simple HTTP data feeds. &PRODUCT_NAME. assumes that all data is returned with the first request and that the server does not support server-side filtering, ordering or other advanced REST service feature. All '
||'invocation details and parameters must be configured manually.</li>',
'<li><strong>Oracle REST Data Services</strong> (ORDS) denotes RESTful Services provided by ORDS. These REST services follow the <em>Oracle REST standard</em>, which means that GET, POST, PUT or DELETE operations are standardized. Server-side filterin'
||'g and ordering are supported. &PRODUCT_NAME. can leverage these features by delegating report order-bys and filters to the REST service.</li>',
'<li><strong>REST Enabled SQL Query</strong> denotes a REST Source on top of a SQL Query executed on a REST Enabled SQL Reference. &PRODUCT_NAME. supports filtering and pagination, but no DML on these endpoints.</li>',
'<li><strong>Oracle Cloud Applications (SaaS) REST Service</strong> denotes RESTful services provided by Oracle Cloud Applications (SaaS). Use this web service type to integrate Oracle SaaS REST Services into your &PRODUCT_NAME. application. &PRODUCT_'
||'NAME. supports pagination for these Services.</li>',
'<li><strong>Oracle Cloud Infrastructure (OCI) REST Service</strong> denotes RESTful web services provided by Oracle Cloud Infrastructure. Use this web service type to integrate OCI REST Services (for example, accessing the Object Store) into your &PR'
||'ODUCT_NAME. application. &PRODUCT_NAME. supports pagination for these Services.</li>',
'<li><strong>OData REST Service</strong> denotes a REST service which implements the Open Data (OData) protocol, which is an ISO/IEC approved, OASIS standard that defines a set of best practices for building and consuming RESTful APIs. <em>&PRODUCT_NA'
||'ME. currently only supports the <em>Fetch</em> APIs (read data); DML operations for OData are not yet supported.</em></li>',
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
