wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1418382946635714)
,p_name=>'P1922_FORCE_RAISE_404_ERROR'
,p_is_required=>true
,p_item_sequence=>80
,p_item_plug_id=>wwv_flow_imp.id(3469784605842432)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Force Raise HTTP-404 Error'
,p_source=>'FORCE_ERROR_FOR_HTTP_404'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_YES_NO'
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'If the HTTP request, executed by the <strong>Fetch Rows</strong> database operation, receives the ',
'<strong>404</strong> HTTP status code ("Not Found"), APEX treats this as a "No Rows Found" situation - and does thus not raise an error (an error is raised only when <em>Debug</em> is enabled). Enabling this switch forces APEX to <em>always</em> sign'
||'al HTTP-404 situations as errors.'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'use_defaults', 'Y')).to_clob
);
