wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(3507516611076974)
,p_name=>'P1922_CACHING'
,p_item_sequence=>10
,p_item_plug_id=>wwv_flow_imp.id(3632686677195912646)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Caching'
,p_source=>'CACHING'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'CACHING_MODE'
,p_lov=>'.'||wwv_flow_imp.id(225840272947805161)||'.'
,p_lov_display_null=>'YES'
,p_lov_null_text=>'Disabled'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'    Select how the &PRODUCT_NAME. engine can cache REST Source responses on the server side. If caching can be used, the component will be rendered based on cached results instead of fetching from the web service again. Only HTTP "GET" requests will '
||'be cached, which will cut down expensive HTTP requests. This feature is unrelated to the browser''s caching capabilities.</p>',
'<p>',
'    Available options include:',
'</p>',
'<ul>',
'    <li><strong>Disabled</strong>: Content is not cached and fetched from the REST source for each request.</li>',
'    <li><strong>For all users</strong>: Content is cached and utilized by all users.</li>',
'    <li><strong>By User</strong>: Content is cached specifically for each user.</li>',
'    <li><strong>By Session</strong>: Content is cached specifically for each session.</li>',
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(3507960502076974)
,p_name=>'P1922_INVALIDATE_WHEN'
,p_item_sequence=>20
,p_item_plug_id=>wwv_flow_imp.id(3632686677195912646)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Invalidate When'
,p_source=>'INVALIDATE_WHEN'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXTAREA'
,p_cSize=>60
,p_cMaxlength=>4000
,p_cHeight=>4
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'    Specify when cached content is to be invalidated. Provide either the amount of minutes or a "DBMS_SCHEDULER Calendaring Expression". ',
'    With the latter, cached content can be invalidated using flexible intervals, for instance at the top of the hour, at midnight, or another specific recurring point in time.',
'</p> ',
'<p>',
'    Use a value of zero to only cache contents in memory, for the current page processing.',
'</p>',
'<p>Examples:</p>',
'<ul>',
'    <li><strong>15</strong>: The content will expire 15 minutes after it has been cached.</li>',
'    <li><strong>FREQ=HOURLY;BYMINUTE=0;BYSECOND=0</strong>: The content will be cached until the next top of the hour.</li>',
'    <li><strong>FREQ=DAILY;BYHOUR=0;BYMINUTE=0;BYSECOND=0</strong>: The content will be cached until midnight.</li>',
'    <li><strong>0</strong>: The content will be cached only in memory, for the current page processing.</li>',
'</ul>',
'<p></p>',
'<p>See the documentation on <code>DBMS_SCHEDULER.EVALUATE_CALENDAR_STRING</code> for more details.</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'auto_height', 'N',
  'character_counter', 'N',
  'resizable', 'Y',
  'trim_spaces', 'BOTH')).to_clob
);
