wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(238756237141331835)
,p_name=>'P1922_ALLOW_FETCH_ALL_ROWS'
,p_item_sequence=>50
,p_item_plug_id=>wwv_flow_imp.id(3469784605842432)
,p_use_cache_before_default=>'NO'
,p_item_default=>'N'
,p_prompt=>'Allow Fetching All Rows'
,p_source=>'ALLOW_FETCH_ALL_ROWS'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_YES_NO'
,p_display_when=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select 1 from ',
'wwv_flow_web_src_modules',
'where id = :P1922_WEB_SRC_MODULE_ID and :P1922_DATABASE_OPERATION = ''FETCH_COLLECTION''',
''))
,p_display_when_type=>'EXISTS'
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'    Specify whether &PRODUCT_NAME. components are allowed to fetch all rows, thus executing multiple HTTP requests, from this REST source operation. ',
'</p>',
'<p>',
'   This applies for REST sources which return their data page-wise, like Oracle REST Data Services does. For instance, a chart or the Group By view of Interactive Reports need to access all rows to compute correct results. When the REST service retur'
||'n their data page-wise, this requires multiple HTTP requests to the REST service. ',
'</p>',
'<p>',
'    If the REST source only returns a few pages, which can be fetched in a few seconds, this is acceptable for most use-cases. For these services, set this attribute to <strong>On</strong>. On the other hand, when the REST service returns thousands o'
||'f rows in hundreds of pages, fetching all rows would take too much time to complete - for such services, set this attribute to <strong>Off</strong>.',
'</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'use_defaults', 'Y')).to_clob
);
