wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(3632686934550912649)
,p_name=>'P1922_REST_OPERATION'
,p_is_required=>true
,p_item_sequence=>100
,p_item_plug_id=>wwv_flow_imp.id(3500552115076908)
,p_use_cache_before_default=>'NO'
,p_prompt=>'HTTP Method'
,p_source=>'OPERATION'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'WEB_SOURCE_HTTP_METHODS'
,p_lov=>'.'||wwv_flow_imp.id(225847729464891335)||'.'
,p_lov_display_null=>'YES'
,p_lov_null_text=>'- Select -'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(452656722938220607)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'    HTTP Operation or <em>Method</em> (GET, POST, PUT, DELETE) to be executed on the REST Web Service. The combination of URL pattern and HTTP Operation identifies the operation within a REST Data Source. A REST Data Source may contain the same URL p'
||'attern for different HTTP operations and different URL patterns for the same HTTP operation.',
'</p>',
'<p>',
'    Following is a brief explanation of HTTP methods and their usage in REST services. Note this this is all convention - REST services should adhere to this, but real implementations can be different. Always check the documentation of the REST servi'
||'ce you plan to access on which methods can be called and how they work.',
'</p>',
'<ul>',
'    <li>',
'        <strong>GET</strong> to fetch data from the REST service. GET is supposed to be idempotent; it''s invocation does not change anything at the server side. For this reason, GET requests can be typically be cached or called multiple times. GET re'
||'quests do also <em>not</em> have a request body in normal cases.',
'    </li>',
'    <li>',
'        <strong>POST</strong> is typically used to create a new resource on the server. However, in practice, POST requests can',
'        do all sort of things. POST requests typically require a request body to be sent.',
'    </li>',
'    <li>',
'        <strong>PUT</strong> is typically used to <em>replace</em> a new resource on the server. A request body is typically required. Note that you need to pass <em>all</em> attributes to the server - missing attributes are likely to be written as n'
||'ull or empty values.',
'    </li>',
'    <li>',
'        <strong>DELETE</strong> is typically used to remove a resource on the server. A request body is typically not required.',
'    </li>',
'    <li>',
'        <strong>PATCH</strong> is typically used to <em>change</em> a new resource on the server. Not all REST services provide PATCH endpoints. A request body, containing information on which attribute to change to which value, is required. PATCH th'
||'us allows to do partial updates on a server resource. Note that there is no standard on how the request body for a PATCH endpoint should look like - check the documentation of your REST service before invoking it. ',
'    </li>',
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
