,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(452656722938220607)
,p_item_css_classes=>'apex-button-group'
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'    Choose the type of this REST Source Parameter. Available values are:',
'</p>',
'<dl>',
'<dt>URL Pattern (IN)</dt>',
'<dd>Replace placeholders in the endpoint URL with parameter values.</dd>',
'<dt>URL Query String (IN)</dt>',
'<dd>Add parameter name and value to the URL, as the query string</dd>',
'<dt>HTTP Header (IN, OUT)</dt>',
'<dd>Send the parameter as a HTTP Request Header, or receive from the Response Headers</dd>',
'<dt>Cookie (IN, OUT)</dt>',
'<dd>Send the parameter as a cookie, or receive from the response cookies</dd>',
'<dt>Data Profile Column (OUT)</dt>',
'<dd>Parse the response using the data profile and use the column value. This type is only supported in the <strong>Invoke API</strong> process type.</dd>',
'<dt>Request or Response Body (IN, OUT)</dt>',
'<dd>Perform placeholder substitutions in the request body with the parameter value. For OUT parameters, the <em>full response</em> will be retrieved.</dd>',
'<dt>Status Code (OUT)</dt>',
'<dd>Receive the HTTP Status Code</dd>',
'<dt>Reason Phrase (OUT)</dt>',
'<dd>Receive the HTTP Reason Phrase</dd>',
'</dl>',
'<p>',
'    Example for Parameters of type <strong>URL Pattern</strong>',
'</p>',
'<ul>',
'    <li>URL Endpoint: <code>http://{server}:{port}/ords/:schema/emp/:deptno</code></li>',
'    <li>Parameter 1: <em>URL Pattern Variable</em> "deptno" with a value of "10"</li>',
'    <li>Parameter 2: <em>URL Pattern Variable</em> "schema" with a value of "scott"</li>',
'</ul>',
'<p>',
'<br>',
'    Do <em>not</em> add the colon (:) to the parameter name. &PRODUCT_NAME. will build the URL to invoke as follows:<br>',
'    <code>http://{server}:{port}/ords/<strong>scott</strong>/emp/<strong>10</strong></code>',
'</p>',
'<p>',
'    Example for Parameters of type <strong>Query String</strong>',
'</p>',
'<ul>',
'    <li>URL Endpoint: <code>http://{server}:{port}/ords/scott/emp</code></li>',
'    <li>Parameter 1: <em>Query String Variable</em> "query_filter" with a value of "KING"</li>',
'</ul>',
'<p>',
'<br>',
'    &PRODUCT_NAME. will build the URL to invoke as follows:<br>',
'    <code>http://{server}:{port}/ords/scott/emp?<strong>query_filter</strong>=<strong>KING</strong></code>',
'</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
,p_show_quick_picks=>'Y'
,p_quick_pick_label_01=>'URL Pattern'
,p_quick_pick_value_01=>'URL_PATTERN'
,p_quick_pick_label_02=>'URL Query String'
,p_quick_pick_value_02=>'QUERY_STRING'
,p_quick_pick_label_03=>'HTTP Header'
,p_quick_pick_value_03=>'HEADER'
,p_quick_pick_label_04=>'Data Profile'
,p_quick_pick_value_04=>'DATA_PROFILE'
,p_quick_pick_label_05=>'Body'
,p_quick_pick_value_05=>'BODY'
);
