,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'    If set to <strong>On</strong>, &PRODUCT_NAME. will only add the parameter to the request, when the value is not empty. When set to <strong>Off</strong>, the parameter will always be added to the request. This only applies to parameters of the <em'
||'>Query String</em>, <em>Cookie</em> or <em>HTTP Header</em> type. ',
'</p>',
'<p>',
'    Example for a parameter <strong>param2</strong> of type Query String with an empty value.',
'</p>',
'<ul>',
'    <li>Omit when value is empty set to <strong>Off</strong>:<br>',
'    http://api.example.com/url/path?param1=value1&amp;param2=</li>',
'    <li>Omit when value is empty set to <strong>On</strong>:<br>',
'    http://api.example.com/url/path?param1=value1</li>',
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'use_defaults', 'Y')).to_clob
);
