 p_id=>wwv_flow_imp.id(473241645223135113)
,p_name=>'P1923_IS_QUERY_PARAM'
,p_is_required=>true
,p_item_sequence=>30
,p_item_plug_id=>wwv_flow_imp.id(1718664379469919)
,p_use_cache_before_default=>'NO'
,p_item_default=>'N'
,p_prompt=>'Use for Row Search'
,p_source=>'IS_QUERY_PARAM'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_YES_NO'
,p_display_when=>'P1923_WEB_SRC_OPERATION_ID'
,p_display_when_type=>'ITEM_IS_NULL'
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'    If <strong>Use for Row Search</strong> is enabled for a REST Data Source parameter, <em>Row Search</em> queries (from Interactive Reports, Interactive Grids or Popup LOVs) will be passed to the Web Service using this parameter. This is useful if '
||'your REST service supports <em>search</em> or <em>query</em> parameters.',
'</p>',
'<p>Example:</p>',
'<p>',
'    A REST service endpoint is invoked using a query parameter "q", e.g. <code>http://{server}/path/to/service?p={search-term}</code>. The REST Data Source will have the <strong>q</strong> query string parameter defined. If the <strong>Use for Row Se'
||'arch</strong> is enabled, search terms from Interactive Report or Interactive Grid row searches will be passed to the REST service as the <strong>q</strong> parameter.',
'</p>',
'<p>Only Parameters defined at the REST Source level can be used for Row Search.</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'use_defaults', 'Y')).to_clob
);
wwv_flow_imp_page.create_page_computation(
 p_id=>wwv_flow_imp.id(1717676791469909)
,p_computation_sequence=>10
,p_computation_item=>'P1923_NAME'
,p_computation_type=>'ITEM_VALUE'
,p_computation=>'P1923_PROFILE_COLUMN'
,p_compute_when=>'P1923_PARAM_TYPE'
,p_compute_when_text=>'DATA_PROFILE'
,p_compute_when_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
