wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(2005950886904814)
,p_validation_name=>'Value provided for Required  Parameters'
,p_validation_sequence=>40
,p_validation=>'P1923_VALUE'
,p_validation_type=>'ITEM_NOT_NULL'
,p_error_message=>'Default value must be provided for required parameters, as the REST Source is in use.'
,p_validation_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_result number;',
'begin',
'    if :REQUEST in (''APPLY_CHANGES'', ''CREATE'', ''CREATE_AND_ANOTHER'' ) and :P1923_IS_REQUIRED = ''Y'' then',
'        begin',
'            select result ',
'              into l_result',
'              from (',
'                     select 1 as result',
'                       from wwv_flow_web_src_module_usage',
'                      where security_group_id  = :FLOW_SECURITY_GROUP_ID',
'                        and flow_id            = :FB_FLOW_ID',
'                        and web_src_module_id  = :P1923_WEB_SRC_MODULE_ID',
'                        and :P1923_ID         is  null',
'                     union all (',
'                         select 1 as result',
'                           from wwv_flow_web_src_modules',
'                          where security_group_id  = :FLOW_SECURITY_GROUP_ID',
'                            and flow_id            = :FB_FLOW_ID      ',
'                            and id                 = :P1923_WEB_SRC_MODULE_ID',
'                            and sync_table_name   is not null',
'                            and :P1923_ID         is  null ) )',
'             where rownum = 1;',
'             return true;',
'        exception',
'            when no_data_found then',
'                null;',
'        end;',
'',
'    end if;',
'',
'    return false;',
'end;'))
,p_validation_condition2=>'PLSQL'
,p_validation_condition_type=>'FUNCTION_BODY'
,p_associated_item=>wwv_flow_imp.id(226076748969270124)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
