 p_id=>wwv_flow_imp.id(225857161514926537)
,p_plug_name=>'Columns'
,p_region_name=>'profile_columns'
,p_parent_plug_id=>wwv_flow_imp.id(3439310821106145)
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(208928010704475743)
,p_plug_display_sequence=>60
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select c.id,',
'       c.rowid,',
'       c.flow_id,',
'       c.data_profile_id,',
'       c.name,',
'       c.sequence,',
'       c.is_primary_key,',
'       c.is_hidden,',
'       c.is_common,',
'       c.data_type,',
'       c.max_length,',
'       c.column_type,',
'       (select pc.name ',
'          from wwv_flow_data_profile_cols pc',
'         where pc.security_group_id = :FLOW_SECURITY_GROUP_ID',
'           and pc.data_profile_id   = :P1925_DATA_PROFILE_ID',
'           and pc.id                = c.parent_column_id ) as parent_column,',
'       c.selector_type,',
'       c.selector_type as selector_type_orig,',
'       c.selector as definition,',
'       case when :P1925_CAN_DELETE_COLUMNS = ''N'' then ''U'' else ''UD'' end as allowed_operations',
'  from wwv_flow_data_profile_cols c',
' where c.flow_id           = :FB_FLOW_ID',
'   and c.data_profile_id   = :P1925_DATA_PROFILE_ID',
'   and c.security_group_id = :FLOW_SECURITY_GROUP_ID'))
,p_plug_source_type=>'NATIVE_IG'
);
