wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(226131367554626803)
,p_name=>'P1925_ROW_SELECTOR'
,p_item_sequence=>60
,p_item_plug_id=>wwv_flow_imp.id(225858059630926546)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Row Selector'
,p_source=>'ROW_SELECTOR'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>50
,p_cMaxlength=>255
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'    For a data profile returning a table, enter the expression to select the collection of rows within the Data Source. The rows collection is typically a JSON array or XML <em>collection</em> (in XML a sequence of tags with the same name). Nested ar'
||'rays or nested XML <em>collections</em> are not supported.',
'</p>',
'<p>',
'    If the row selector ',
'    references a single JSON object or an XML tag which is not a collection, the <strong>Contains Single Row</strong> data profile attribute must be set to <strong>Yes</strong>. Leave the attribute empty or enter <strong>"."</strong>, if the JSON arr'
||'ay or object is at the root level. ',
'</p>',
'<h2>',
'    Example 1:',
'</h2>',
'<pre>',
'{ "items": [',
'    { "ename": "SMITH", "sal": 200 },',
'    { "ename": "SCOTT", "sal": 100 } ] }',
'</pre>',
'<p>',
'    The JSON attribute contains an array in the <strong>items</strong> attribute, so choose that as the row selector. An element within that array will be considered as a row and each attribute will be considered as a column.',
'</p>',
'<h2>',
'    Example 2:',
'</h2>',
'<pre>',
'{ "header": { "generated": "2018-10-19", "version": "1.0" },',
'  "body": { "items": [',
'          { "ename": "SMITH", "sal": 200 },',
'          { "ename": "SCOTT", "sal": 100 } ] } }',
'</pre>',
'<p>',
'    The JSON attribute contains an array in the <strong>body.items</strong> attribute, so choose that as the row selector. An element within that array will be considered as a row and each attribute will be considered as a column.',
'</p>',
' <h2>',
'    Example 3:',
'</h2>',
'<pre>',
'&lt;xml-document&gt;',
'  &lt;row&gt;',
'    &lt;ename&gt;SMITH&lt;/ename&gt;&lt;sal&gt;200&lt;/sal&gt;',
'  &lt;/row&gt;',
'  &lt;row&gt;',
'    &lt;ename&gt;SCOTT&lt;/ename&gt;&lt;sal&gt;100&lt;/sal&gt;',
'  &lt;/row&gt;',
'&lt;xml-document&gt;',
'</pre>   ',
'    <p>',
'    The XML tag attribute <strong>/xml-document/row</strong> contains a <em>collection</em>, so choose that as the row selector. Each <strong>row</strong> object will be considered as a row and each child tag of &lt;row&gt; will be considered as a co'
||'lumn.',
'</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'TEXT',
  'trim_spaces', 'BOTH')).to_clob
);
