wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(4702017184940016)
,p_name=>'P1926_TRANSFORM_TYPE'
,p_item_sequence=>10
,p_item_plug_id=>wwv_flow_imp.id(4701992042940015)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Value Transformation'
,p_source=>'TRANSFORM_TYPE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'DATA.LOAD.TRANSFORM_TYPE'
,p_lov=>'.'||wwv_flow_imp.id(4818478622110870)||'.'
,p_lov_display_null=>'YES'
,p_lov_null_text=>'None'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'    Select a simple transformation rule to change the uploaded value. For example, if the source data contains column data in mixed case format, the <strong>To Lower Case</strong> or <strong>To Upper Case</strong> allow to convert the data to the des'
||'ired case.',
'    </p>',
'<ul>',
'    <li><strong>Left Trim</strong>, <strong>Right Trim</strong> and <strong>Trim</strong>:<br> Trim characters specified in <strong>Expression 1</strong> from the left side, the right side or from both sides of the uploaded data value.</li>',
'    <li><strong>Replace</strong>:<br> Simple replacement of <strong>Expression&nbsp;1</strong> occurrences with <strong>Expression&nbsp;2</strong>.</li>',
'    <li><strong>To Upper Case</strong>:<br> Convert the value to upper case.</li>',
'    <li><strong>To Lower Case</strong>:<br> Convert the value to lower case.</li>',
'    <li><strong>Null If</strong>:<br> If the uploaded value equals the string specified in <strong>Expression&nbsp;1</strong>, the value will be uploaded as NULL.</li>',
'    <li><strong>Regular Expression Replace</strong>:<br> Apply the regular expression specified in <strong>Expression&nbsp;1</strong>, and replace all matches with <strong>Expression&nbsp;2</strong>.</li>',
'    <li><strong>Regular Expression Null If</strong>:<br> If the regular expression specified in <strong>Expression&nbsp;1</strong> matches, upload the column value as NULL.</li>',
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
