,p_lov=>'.'||wwv_flow_imp.id(5203249727555533)||'.'
,p_display_when=>'P1926_FORMAT'
,p_display_when2=>'CSV:XLSX'
,p_display_when_type=>'VALUE_OF_ITEM_IN_CONDITION_IN_COLON_DELIMITED_LIST'
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_css_classes=>'apex-button-group'
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'    For <strong>CSV</strong> or <strong>XLSX</strong> data profiles, specify whether the column value is referenced by the (numeric) column sequence, by the column name or by a regular expression. The <strong>Name</strong> or <strong>Regular Expressi'
||'on</strong> options require the CSV or XLSX data to contain column names in the first row. ',
'    The <strong>Regular Expression</strong> option is useful if the column names in uploaded data are likely to change.',
'</p>',
'<p>',
'The <strong>Sequence</strong> option has a performance advantage, since &PRODUCT_NAME. does not need to determine column names and positions before loading the data. However use this option only if the uploaded data always has the same columns in the'
||' same sequence. ',
'</p>',
''))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'number_of_columns', '4',
  'page_action_on_selection', 'NONE')).to_clob
);
