wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(225901683035244541)
,p_name=>'P1926_HAS_TIME_ZONE'
,p_item_sequence=>170
,p_item_plug_id=>wwv_flow_imp.id(225899656946244521)
,p_use_cache_before_default=>'NO'
,p_item_default=>'Y'
,p_prompt=>'Has Time Zone'
,p_source=>'HAS_TIME_ZONE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_YES_NO'
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'    Indicates whether the DATE or TIMESTAMP value in the <em>source data (REST Source response or uploaded data)</em> contains timestamp information. If enabled, &PRODUCT_NAME. respects the time zone and converts the value to the local application ti'
||'me zone. If not, the value is taken as-is.',
'</p>',
'<p>',
'   Examples:    ',
'</p>',
'<ul>',
'    <li><code>2019-01-01T20:00:00Z</code> does contain time zone information</li>',
'    <li><code>2019-01-01T20:00:00 Europe/Berlin</code> does contain time zone information</li>',
'    <li><code>2019-01-01T20:00:00</code> does not contain time zone information</li>',
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'use_defaults', 'Y')).to_clob
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(225901911120244544)
,p_name=>'P1926_SELECTOR'
,p_item_sequence=>50
,p_item_plug_id=>wwv_flow_imp.id(225901106053244536)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Selector'
,p_source=>'SELECTOR'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>75
,p_cMaxlength=>255
,p_field_template=>wwv_flow_imp.id(452656722938220607)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>The <strong>Selector</strong> expression is being used to extract the column value from the source data.',
'<ul>',
'    <li><p>For <strong>XML</strong> and <strong>JSON</strong> formats, this selector is <em>relative</em> to the <strong>Row Selector</strong> which is configured at the data profile level. Use XPath-Syntax for XML, and JSON path expressions for JSON'
||' formats.</p><p>Note: When using the <strong>APEX_EXEC</strong> package to access data within <em>Array</em> columns using PL/SQL, <em>only simple selectors</em>, i.e. without filter expressions or array indexes are allowed.</p></li>',
'    <li>For <strong>CSV</strong> or <strong>XLSX</strong>, use the column name, sequence or a regular expression, based on the <strong>Selector Type</strong> attribute. Note that column names and regular expressions are matched in a <em>case-insensit'
||'ive</em> manner for CSV and XLSX files.</li> ',
'</ul>',
'<p>',
'<br><strong>JSON Example:</strong>',
'</p>',
'<pre>',
'{ "items": [',
'    { "ename": "SMITH", "sal": 200 },',
'    { "ename": "SCOTT", "sal": 100 } ] }',
'</pre>',
'<p>',
'    <strong>items</strong> is used as the <strong>Row Selector</strong> attribute, so choose <strong>ename</strong> as the selector for the ENAME column and <strong>sal</strong> as the selector for the SAL column. Note that the selector must not refe'
||'rence a JSON array.',
'</p>',
'<p>',
'<br><strong>CSV Example:</strong></p>',
'<pre>',
'EMPNO   ENAME   SAL ',
'------- ------- --------',
'   7839 KING        5000',
'   7844 FORD        2850',
'      : :              :',
'</pre>',
'<p>',
'    If <strong>Name</strong> is used as the Selector Type, use the column names from the first line of CSV or XLSX data: <strong>EMPNO</strong>, <strong>ENAME</strong> or <strong>SAL</strong>. If the selector type is <strong>Sequence</strong>, use <s'
||'trong>1</strong>, <strong>2</strong> or <strong>3</strong>, to reference the column by its sequence number. The same semantics applies for XLSX data profiles.',
'</p>',
'<p>',
'Note that the <strong>Sequence</strong> option has a performance advantage, since &PRODUCT_NAME. does not need to determine column names and positions before loading the data. However use this option only if the uploaded data always has the same colu'
||'mns in the same sequence. ',
'</p> '))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'TEXT',
  'trim_spaces', 'BOTH')).to_clob
);
