wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(1402073230748305)
,p_process_sequence=>10
,p_process_point=>'BEFORE_BOX_BODY'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Init Values'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    select round(sys.dbms_lob.getlength(clob001) / 1000), -- transform to kilobytes',
'           substr(clob001, 1, 500)',
'      into :P1927_RESPONSE_LENGTH,',
'           :P1927_BODY_PART',
'      from wwv_flow_collections ',
'     where collection_name = ''WEB_SOURCE_INFO'' ',
'       and c001            = ''DATA'' ',
'       and rownum          = 1;',
'exception',
'    when no_data_found then',
'        null;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>1402073230748305
);
