,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Invoke URL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'if wwv_flow_plugin_dev.has_standard_attribute(',
'       p_application_id => :FB_FLOW_ID,',
'       p_plugin_type    => wwv_flow_plugin.c_plugin_type_web_source,',
'       p_plugin_name    => :P1941_WEB_SRC_TYPE,',
'       p_feature        => ''NO_TEST_ENDPOINT'' )',
'then',
'    :P1941_SUCCESS           := ''Y'';',
'    :P1941_MUST_AUTHENTICATE := ''N'';',
'else',
'    wwv_flow_web_src_dev.f4000_test_endpoint_url(',
'        p_application_id   => :FB_FLOW_ID,',
'        p_endpoint_url     => :P1941_ENDPOINT_URL,',
'        p_https_host       => :P1941_HTTPS_HOST,',
'        p_web_source_type  => :P1941_WEB_SRC_TYPE,',
'        p_url_param1_name  => :P1941_URL_PARAM1_NAME,',
'        p_url_param1_value => :P1941_URL_PARAM1_VALUE,',
'        p_url_param2_name  => :P1941_URL_PARAM2_NAME,',
'        p_url_param2_value => :P1941_URL_PARAM2_VALUE,',
'        --',
'        p_param1_name      => :P1944_PARAM_NAME_1,',
'        p_param1_type      => :P1944_PARAM_TYPE_1,',
'        p_param1_value     => :P1944_PARAM_VALUE_1,',
'        p_param2_name      => :P1944_PARAM_NAME_2,',
'        p_param2_type      => :P1944_PARAM_TYPE_2,',
'        p_param2_value     => :P1944_PARAM_VALUE_2,',
'        --',
'        p_auth_required    => :P1941_MUST_AUTHENTICATE,',
'        p_success          => :P1941_SUCCESS,',
'        p_message          => :P1941_MESSAGE );',
'end if;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(3850682751787121728)
