wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(226574766423012964)
,p_name=>'P1943_AUTH_TYPE'
,p_item_sequence=>40
,p_item_plug_id=>wwv_flow_imp.id(229756918559737172)
,p_prompt=>'Authentication Type'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'CREDENTIALS_TYPE'
,p_lov=>'.'||wwv_flow_imp.id(154078822199034715)||'.'
,p_lov_display_null=>'YES'
,p_lov_null_text=>'- Select -'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(452656722938220607)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'    Specify the Authentication type here. Currently, Oracle APEX supports the following authentication types:',
'</p>',
'<ul>',
'    <li><strong>Basic Authentication</strong> - Sends username and password in Base64-encoded form as the <strong>Authorization</strong> request header.',
'    </li>',
'    <li><strong>OAuth2 Client Credentials</strong> - Oracle APEX exchanges the client ID and client secret for an <strong>Access Token</strong> using a token server URL. The access token is then used to perform the actual request. If the access token'
||' is expired, APEX will transparently request a new one.</li>',
'    <li><strong>OCI Native Authentication</strong> - Oracle APEX signs requests to the <em>Oracle Cloud Infrastructure (OCI)</em> REST API, as described in the <a rel="noopener noreferrer" href="https://docs.cloud.oracle.com/en-us/iaas/Content/API/Co'
||'ncepts/signingrequests.htm">OCI Documentation</a>. This type is only available in Oracle Database 18c and higher.</li>',
'    <li><strong>HTTP Header</strong> - The credential is added to the REST Request as a HTTP Header. The name of the credential is the HTTP Header name, the Secret of the credential is the HTTP Header value. Oracle APEX does not add these secrets to '
||'the Debug log or any other logs.</li>',
'    <li><strong>URL Query String</strong> -  The credential is added to the URL of the REST Request as a <em>Query String</em> Parameter (for example: <strong>?name=value</strong>). This option can be useful with API keys. Oracle APEX does not add th'
||'ese secrets to the Debug log or any other logs. However,proxy or other intermediate servers will log these credentials in their log files.</li>',
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
