,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>The <strong>Row Selector</strong> denotes the JSON or XML path expression which navigates to the JSON attribute or XML tag containing the array of rows. When no value is provided, &PRODUCT_NAME. will try to automatically detect the row selector. ',
'</p>',
'<p>XML Examples:</p>',
'<ul>',
'<li>/rss/channel/item</li>',
'<li>/root/tag/array</li>',
'</ul>',
'<p>',
'    ',
'</p>',
'<p>JSON Examples:</p>',
'<ul>',
'<li>.</li>',
'<li>items</li>',
'<li>result.items</li>',
'<li>items[0].results</li>',
'</ul>',
'<p>',
'    ',
'</p><p>',
'    You cannot use the "[*]" expression within a JSON row selector. For instance, <span style="text-decoration: line-through";>items[*].employees</span> is forbidden.',
'</p>'))
,p_encrypt_session_state_yn=>'N'
