,p_field_template=>wwv_flow_imp.id(452656722938220607)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>The URL endpoint of the REST Data Source will consist of the Base URL (starting with http:// or https://) and the service path suffix being appended to that. The Base URL is being stored as a Remote Server object and can be shared between multiple'
||' REST Data Sources. Note that the Base URL can (and frequently should) be more than just the server name and the port. Most often the first parts of the URL path (for example, the context root) are also server-specific.</p>',
'<p>Examples:</p>',
'<ul>',
'    <li>http://api.example.com:8080/myservices/test/</li>',
'    <li>https://api.example.com/ords/scott/</li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'URL',
  'trim_spaces', 'BOTH')).to_clob
);
