'declare',
'    l_openapi clob;',
'begin',
'    select c.clob001',
'      into l_openapi',
'      from wwv_flow_collections c',
'     where c.collection_name = :P1971_COLLECTION_NAME;',
'',
'    wwv_web_src_catalog.catalog_from_openapi (',
'        p_openapi                         => l_openapi,',
'        p_id                              => :P1971_CATALOG_ID,',
'        p_group_id                        => :P1971_CATALOG_GROUP_ID,',
'        p_internal_name                   => :P1971_INTERNAL_NAME,',
'        p_name                            => :P1971_NAME,',
'        p_description                     => :P1971_DESCRIPTION,',
