wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(17570430382429314)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Initialize page'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  l_is_multistep_yn      number;',
'begin',
'    select count(*) into l_is_multistep_yn',
'      from (',
'          select 1 from wwv_flow_install_checks    where security_group_id = :flow_security_group_id and flow_id = :fb_flow_id union all',
'          select 1 from wwv_flow_install_build_opt where security_group_id = :flow_security_group_id and flow_id = :fb_flow_id union all',
'          select 1 from wwv_flow_install           ',
'           where ( replace(prompt_substitution_01_yn||',
'                         prompt_substitution_02_yn||',
'                         prompt_substitution_03_yn||',
'                         prompt_substitution_04_yn||',
'                         prompt_substitution_05_yn||',
'                         prompt_substitution_06_yn||',
'                         prompt_substitution_07_yn||',
'                         prompt_substitution_08_yn||',
'                         prompt_substitution_09_yn||',
'                         prompt_substitution_10_yn||',
'                         prompt_substitution_11_yn||',
'                         prompt_substitution_12_yn||',
'                         prompt_substitution_13_yn||',
'                         prompt_substitution_14_yn||',
'                         prompt_substitution_15_yn||',
'                         prompt_substitution_16_yn||',
'                         prompt_substitution_17_yn||',
'                         prompt_substitution_18_yn||',
'                         prompt_substitution_19_yn||',
'                         prompt_substitution_20_yn,''N'','''') is not null',
'                      or license_message is not null )',
'                     and flow_id = :fb_flow_id',
'                     and security_group_id = :flow_security_group_id',
'      );',
'',
'    if l_is_multistep_yn > 0 then',
'        :P2100_MULTISTEP_YN := ''Y'';',
'    else ',
'        :P2100_MULTISTEP_YN := ''N'';',
'    end if;',
'',
'    if :REQUEST = ''APP_INSTALLED'' and :P2100_MULTISTEP_YN = ''N'' then',
'       :P2100_PAGE_NAME := wwv_flow_lang.message( ''INSTALLER.TITLE.APP_INSTALLED'' );',
'    else',
'       :P2100_PAGE_NAME := wwv_flow_lang.message( ''INSTALLER.TITLE.INSTALL_SUPP_OBJ'' );',
'    end if;',
'',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>17570430382429314
);
end;
