,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'Unable to delete application definition.'
,p_process_when_button_id=>wwv_flow_imp.id(37419900654747681)
,p_process_when=>'APPLICATION'
,p_process_when_type=>'CONDITION1_IN_VALUE_OF_ITEM_IN_CONDITION2'
