wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(15901685876127513)
,p_process_sequence=>10
,p_process_point=>'AFTER_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Derive Branch Pages'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_branch_page number;',
'    l_url         varchar2(4000);',
'begin',
'    -- try to default the branch pages based on breadcrumb parent, if selected',
'    if :P2501_BREADCRUMB_PARENT_ID is not null then',
'        select link',
'          into l_url',
'          from wwv_flow_menu_options',
'         where id                = :P2501_BREADCRUMB_PARENT_ID',
'           and flow_id           = :FB_FLOW_ID',
'           and security_group_id = :WORKSPACE_ID;',
'',
'        l_branch_page := wwv_flow_page_map.extract_page_id (',
'                             p_url               => l_url,',
'                             p_application_id    => :FB_FLOW_ID );',
'    -- if no breadcrumb parent selected, check if list entry parent is selected',
'    -- try to derive branch page based on parent list entry',
'    elsif :P2501_BREADCRUMB_PARENT_ID is null and :P2501_NAVLIST_PARENT_ID is not null then',
'        select list_item_link_target',
'          into l_url',
'          from wwv_flow_list_items',
'         where id                = :P2501_NAVLIST_PARENT_ID',
'           and flow_id           = :FB_FLOW_ID',
'           and security_group_id = :WORKSPACE_ID;',
'',
'        l_branch_page := wwv_flow_page_map.extract_page_id (',
'                             p_url               => l_url,',
'                             p_application_id    => :FB_FLOW_ID );',
'    end if;',
'',
'    if l_branch_page is null then',
'        l_branch_page := wwv_flow_page_map.get_home_page_id (',
'                             p_application_id    => :FB_FLOW_ID );',
'    end if;',
'    ',
'    :P2502_SUBMIT_BRANCH := l_branch_page;',
'    :P2502_CANCEL_BRANCH := l_branch_page;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>':P2500_PAGE_TYPE = ''FORM'' and :P2501_PAGE_MODE = ''NORMAL'''
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_internal_uid=>15901685876127513
);
