wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(5801940262086775)
,p_validation_name=>'Validate Aggregation'
,p_validation_sequence=>30
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_data_type wwv_flow_global.t_dbms_id;',
'begin ',
'    for c1 in ( select c003 dataType',
'                  from wwv_flow_collections',
'                 where collection_name  = ''WIZ_COLUMNS_LIST''',
'                   and c003 in  ( ''VARCHAR2'', ''NUMBER'', ''DATE'', ''TIMESTAMP'', ''TIMESTAMP_TZ'', ''TIMESTAMP_LTZ'' )',
'                   and c002 = :P2505_LABEL_COL )',
'    loop',
'        l_data_type := c1.dataType;',
'    end loop;',
'',
'    -- SUM & AVG should only be applied to NUMBER',
'    if :P2505_AGGREGATE_FUNCTION in (''SUM'',''AVG'') then ',
'        return false;',
'    -- MEDIAN should not be applied to VARCHAR2    ',
'    elsif :P2505_AGGREGATE_FUNCTION = ''MEDIAN'' then ',
'        if l_data_type = ''VARCHAR2'' then',
'            return false;',
'        end if;',
'    -- All other aggregates require Value to be selected regardless of Label Datatype    ',
'    elsif :P2505_AGGREGATE_FUNCTION in (''MIN'',''MAX'',''COUNT_DISTINCT'',''APPROX_COUNT_DISTINCT'') then',
'        return false;',
'    elsif :P2505_AGGREGATE_FUNCTION = ''COUNT'' then ',
'        return true;',
'    end if;    ',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>'You must select a Value Column for the chosen aggregation'
,p_validation_condition=>':P2505_AGGREGATE_FUNCTION is not null and :P2505_LABEL_COL is not null and :P2505_VALUE_COL is null'
,p_validation_condition2=>'PLSQL'
,p_validation_condition_type=>'EXPRESSION'
,p_when_button_pressed=>wwv_flow_imp.id(4801074006449876)
,p_associated_item=>wwv_flow_imp.id(5009542776617777)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
