wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(7214494484307295)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Create Map Page'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_geom_col_type wwv_flow_map_region.t_feature_data_type;',
'begin',
'    if :P2506_GEOMETRY_COLUMN_TYPE = ''NUMBER'' then',
'        l_geom_col_type := wwv_flow_map_region.c_feature_number_columns;',
'    else',
'        l_geom_col_type := wwv_flow_map_region.c_feature_geojson;',
'',
'        for c in (',
'            select c003 ',
'              from wwv_flow_collections',
'             where collection_name = ''WIZ_COLUMNS_LIST''',
'               and c002            = :P2506_GEOM_COLUMN_NAME',
'               and c003            = ''SDO_GEOMETRY''',
'               and rownum          = 1         ',
'        ) loop',
'            l_geom_col_type := wwv_flow_map_region.c_feature_sdo_geometry;',
'        end loop;',
'    end if;',
'',
'    wwv_flow_map_region_dev.create_map_page(',
'        p_app_id                     => :FB_FLOW_ID,',
'        p_page_id                    => :P2501_PAGE_ID,',
'        p_page_name                  => :P2501_PAGE_NAME,',
'        p_page_mode                  => :P2501_PAGE_MODE,',
'        --',
'        p_nav_list_id                => :P2500_NAVLIST_ID,',
'        p_nav_list_parent_item_id    => :P2501_NAVLIST_PARENT_ID,',
'        p_nav_list_child_item_name   => case when :P2501_NAVLIST_OPTIONS = ''NEW'' then :P2501_PAGE_NAME end,',
'        p_nav_list_item_icon         => :P2501_PAGE_ICON,',
'        --',
'        p_breadcrumb_id              => :P2501_BREADCRUMB_ID,',
'        p_breadcrumb_entry_name      => :P2501_PAGE_NAME,',
'        p_parent_breadcrumb_entry_id => :P2501_BREADCRUMB_PARENT_ID,',
'        --',
'        p_location                   => :P2501_LOCATION,',
'        p_query_type                 => :P2501_QUERY_TYPE,',
'        p_table_owner                => :P2501_TAB_OWNER,',
'        p_table_name                 => :P2501_TAB_NAME,',
'        p_map_source                 => :P2501_SQL_SOURCE,',
'        --',
'        p_remote_server_id           => :P2501_REMOTE_SERVER_ID,',
'        p_web_source_module_id       => :P2501_WEB_SRC_MODULE_ID,',
'        p_document_source_id         => :P2501_DOCUMENT_SOURCE_ID,',
'        p_array_column_id            => :P2501_ARRAY_COLUMN_ID,  ',
'        --',
'        p_layer_name                 => :P2501_PAGE_NAME,',
'        p_layer_type                 => case :P2506_LAYER_TYPE',
'                                            when ''POINT''      then wwv_flow_map_region.c_map_layer_points',
'                                            when ''LINE''       then wwv_flow_map_region.c_map_layer_lines',
'                                            when ''POLYGON''    then wwv_flow_map_region.c_map_layer_polygons',
'                                            when ''HEATMAP''    then wwv_flow_map_region.c_map_layer_heat_map',
'                                            when ''POLYGON_3D'' then wwv_flow_map_region.c_map_layer_3d_polygons',
'                                        end,',
'        p_geometry_column_type       => l_geom_col_type,',
'        p_geometry_column            => :P2506_GEOM_COLUMN_NAME,',
'        p_longitude_column           => :P2506_LON_COLUMN_NAME,',
'        p_latitude_column            => :P2506_LAT_COLUMN_NAME,',
'        p_value_column               => case :P2506_LAYER_TYPE',
'                                            when ''HEATMAP'' then :P2506_HEAT_VALUE_COLUMN_NAME',
'                                            else                :P2506_VALUE_COLUMN_NAME',
'                                         end,',
'        p_extrude_value_column       => :P2506_3D_VALUE_COLUMN_NAME,',
'        p_tooltip_column             => :P2506_TOOLTIP_COLUMN_NAME,',
'        --',
'        p_faceted_search_page        => :P2506_FACETED_SEARCH = ''Y'' );',
'                ',
'    :FB_FLOW_PAGE_ID       := :P2501_PAGE_ID;',
'    :F4000_RUN_EDIT_PAGE   := :P2501_PAGE_ID;',
'end;',
''))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'Unable to create the Map page. #SQLERRM#'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(7201600601307238)
,p_internal_uid=>7214494484307295
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(7214042577307295)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_CLOSE_WINDOW'
,p_process_name=>'Close Dialog'
,p_attribute_01=>'FB_FLOW_ID,FB_FLOW_PAGE_ID,REQUEST'
,p_attribute_02=>'N'
,p_process_error_message=>'Error creating &P2500_PAGE_TYPE_DISPLAY. page.'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(7201600601307238)
,p_process_success_message=>'&P2500_PAGE_TYPE_DISPLAY. page created.'
,p_internal_uid=>7214042577307295
);
end;
