wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(283181239075910775)
,p_name=>'Select procedure arguments to be included in form:'
,p_template=>wwv_flow_imp.id(174794400314076650)
,p_display_sequence=>20
,p_region_template_options=>'#DEFAULT#:a-Region--noTopBorder:a-Region--paddedBody:a-Region--noBorder'
,p_component_template_options=>'#DEFAULT#'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'FUNC_BODY_RETURNING_SQL'
,p_function_body_language=>'PLSQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  q varchar2(32767);',
'begin',
'    q := ''select '';',
'    q :=q||''wwv_flow_item.select_list_from_lov(3,''''YES'''',''''YES_NO_RETURNS_YES_OR_NO'''',null,''''NO'''') include, '';',
'    q :=q||''wwv_flow_escape.html(x.argument_name) || '';',
'    q :=q||''wwv_flow_item.hidden(1,x.argument_name), ''; ',
'    q :=q||''wwv_flow_item.text(2,initcap(replace( ltrim(x.argument_name, ''''P_''''),''''_'''','''' ''''))) prompt, '';',
'    q :=q||''wwv_flow_item.text(4) def, '';',
'    q :=q||''wwv_flow_item.select_list_from_lov(5,''''NATIVE_TEXT_FIELD'''', '';',
'    q :=q||''''''FORM_ON_SP.ITEM_DISPLAY_TYPES'''',null,''''NO'''') typ '';',
'    q :=q||''from ( '';',
'    q :=q||''select '';',
'    q :=q||''argument_name, '';',
'    q :=q||''sequence '';',
'    q :=q||''from sys.dba_arguments '';',
'    q :=q||''where owner = :P2507_OWNER '';',
'    q :=q||''and argument_name is not null '';',
'    if instr(:P2507_PROCEDURE,''.'') > 0 then',
'      q := q||'' and object_name=substr(:P2507_PROCEDURE,instr(:P2507_PROCEDURE,''''.'''')+1)'';',
'      q := q||'' and package_name=substr(:P2507_PROCEDURE,1,instr(:P2507_PROCEDURE,''''.'''')-1)'';      ',
'   else',
'      q := q||'' and object_name = :P2507_PROCEDURE '';     ',
'      q := q||'' and package_name is null '';     ',
'   end if;',
'   q := q||'' order by sequence) x'';',
'  --end if;',
'  return q;',
'end;'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P2507_OWNER,P2507_PROCEDURE'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(123728124628276646)
