wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(10902049747976092)
,p_name=>'P2507_PROCEDURE'
,p_item_sequence=>11
,p_item_plug_id=>wwv_flow_imp.id(10900568987980949)
,p_prompt=>'Stored Procedure Name'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with',
'    l_pkg_functions as (',
'      select a.package_name||''.''||a.object_name object_name',
'        from sys.dba_arguments a',
'       where a.package_name is not null',
'         and a.argument_name is null',
'         and a.owner = :P2507_OWNER ),',
'    l_arguments as (',
'      select distinct',
'             decode(a.package_name, null, null, a.package_name||''.'')||a.object_name object_name',
'        from sys.dba_arguments a,',
'             sys.dba_procedures p',
'      where a.owner = p.owner',
'        and a.object_id = p.object_id',
'        and a.object_name = coalesce( p.procedure_name, p.object_name )',
'        and p.object_type != ''FUNCTION''',
'        and a.owner = :P2507_OWNER',
'        and ( exists (select null',
'                       from sys.dba_tab_privs tp',
'                      where (tp.grantee = (select f.owner',
'                                             from wwv_flows f',
'                                            where f.id = :FB_FLOW_ID',
'                                              and f.security_group_id = :WORKSPACE_ID) or tp.grantee=''PUBLIC'')',
'                        and tp.privilege = ''EXECUTE''',
'                        and (tp.table_name = a.object_name or tp.table_name = a.package_name)',
'                        and tp.owner = a.owner) or',
'              exists (select null',
'                        from wwv_flows f',
'                       where f.owner = :P2507_OWNER',
'                         and f.id = :FB_FLOW_ID',
'                         and f.security_group_id = :WORKSPACE_ID) )  )',
'select ag.object_name d, ag.object_name r',
'  from l_arguments ag',
' where ag.object_name not in (',
'        select pf.object_name',
'        from l_pkg_functions pf )'))
,p_lov_cascade_parent_items=>'P2507_OWNER'
,p_ajax_optimize_refresh=>'Y'
,p_cSize=>30
,p_field_template=>wwv_flow_imp.id(452656722938220607)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>'Select a procedure or package procedure for the form to use.'
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'case_sensitive', 'N',
  'display_as', 'DIALOG',
  'fetch_on_search', 'N',
  'initial_fetch', 'FIRST_ROWSET',
  'manual_entry', 'N',
  'match_type', 'CONTAINS',
  'min_chars', '0')).to_clob
);
