wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(10930217262976177)
,p_validation_name=>'proc exists'
,p_validation_sequence=>30
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare ',
'  l_point   number;',
'  l_pack    varchar2(2000);',
'  l_obj     varchar2(2000);',
'begin',
'  l_point := instr(:P2507_PROCEDURE,''.'');',
'  if l_point > 0 then',
'    l_pack := substr(:P2507_PROCEDURE,0,l_point-1);',
'	l_obj  := substr(:P2507_PROCEDURE,l_point+1);',
'	for c in ( select 1 from sys.dba_arguments',
'		  	   where owner = :P2507_OWNER',
'			    and object_name = l_obj',
'			    and package_name = l_pack ) loop',
'	  return TRUE;',
'	end loop;',
'  else',
'	for c in ( select * from sys.dba_arguments',
'		  	   where owner = :P2507_OWNER',
'			    and object_name = :P2507_PROCEDURE ) loop',
'	  return TRUE;',
'	end loop;',
'  end if;',
'    return FALSE;',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>'Procedure specified not found, please pick a valid store procedure name.'
,p_when_button_pressed=>wwv_flow_imp.id(10904021228976104)
,p_associated_item=>wwv_flow_imp.id(10902049747976092)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
