wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(19904590727194935)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Create Wizard Pages'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_first_page_id number := null;',
'begin  ',
'    for c1 in ( select c002 page_id',
'                  from wwv_flow_collections',
'                 where collection_name = ''CREATE_WIZARD''',
'                 order by c001 ) loop',
'        l_first_page_id := c1.page_id;',
'        exit;',
'    end loop;',
'    ',
'    wwv_flow_wizard_api.create_wizard (',
'        p_flow_id                  => :FB_FLOW_ID,   ',
'        p_steps                    => wwv_flow_collection.collection_member_count( p_collection_name => ''CREATE_WIZARD''),',
'        p_page_mode                => :P2508_PAGE_MODE,',
'        p_wizard_name              => :P2508_WIZARD_NAME,',
'        --',
'        p_nav_list_id              => :P2500_NAVLIST_ID,',
'        p_nav_list_parent_item_id  => :P2508_NAVLIST_PARENT_ID,',
'        p_nav_list_child_item_name => case when :P2508_NAVLIST_OPTIONS = ''NEW'' then :P2508_WIZARD_NAME end,',
'        p_nav_list_item_icon       => :P2508_PAGE_ICON,        ',
'        --',
'        p_cancel_branch            => case when :P2508_PAGE_MODE = ''NORMAL'' then :P2508_CANCEL_BRANCH end,',
'        p_finish_branch            => case when :P2508_PAGE_MODE = ''NORMAL'' then :P2508_FINISH_BRANCH end,  ',
'        p_cancel_button_name       => wwv_flow_lang_dev.builder_message(''CANCEL''),',
'        p_finish_button_name       => wwv_flow_lang_dev.builder_message(''FINISH''),',
'        p_previous_button_name     => wwv_flow_lang_dev.builder_message(''PREVIOUS''),',
'        p_next_button_name         => wwv_flow_lang_dev.builder_message(''NEXT'') );   ',
'     ',
'    :FB_FLOW_PAGE_ID := l_first_page_id;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'Error creating wizard. #SQLERRM_TEXT#'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(16900857304321530)
,p_internal_uid=>19904590727194935
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(22900517250380766)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_CLOSE_WINDOW'
,p_process_name=>'Close Dialog'
,p_attribute_01=>'FB_FLOW_ID,FB_FLOW_PAGE_ID,REQUEST'
,p_attribute_02=>'N'
,p_process_error_message=>'Error creating wizard page.'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(16900857304321530)
,p_process_success_message=>'Wizard page created.'
,p_internal_uid=>22900517250380766
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(19904252956194932)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Initialize Collection'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_page_number number;',
'    l_collection_name varchar2(20) := ''CREATE_WIZARD'';',
'begin',
'    -- this collection is cleared during the brnach process to this page',
'    -- wwv_flow_collection.create_or_truncate_collection( l_collection_name );',
'    -- by default add 3 wizard steps',
'    if wwv_flow_collection.collection_member_count( p_collection_name => ''CREATE_WIZARD'') = 0 then',
'        for i in 1..3',
'        loop',
'            l_page_number := wwv_flow_utilities.minimum_free_page(:FB_FLOW_ID,1);',
'            wwv_flow_collection.add_member(',
'                p_collection_name => l_collection_name,',
'                p_c001            => i,',
'                p_c002            => l_page_number,',
'                p_c003            => wwv_flow_lang_dev.builder_message(''WIZARD.DEFAULT_PAGE_NAME'',i),',
'                p_c004            => 0 );',
'        end loop;',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>19904252956194932
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(19904408518194934)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_region_id=>wwv_flow_imp.id(18005186450209933)
,p_process_type=>'NATIVE_IG_DML'
,p_process_name=>'Update Collection'
,p_attribute_01=>'PLSQL_CODE'
,p_attribute_04=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_collection_name varchar2(20) := ''CREATE_WIZARD'';',
'begin',
'    case :APEX$ROW_STATUS',
'    when ''C'' then',
'        wwv_flow_collection.add_member(',
'            p_collection_name => l_collection_name,',
'            p_c001            => :STEP_NUMBER,',
'            p_c002            => :PAGE_ID,',
'            p_c003            => :PAGE_NAME,',
'            p_c004            => 0 );',
'    when ''U'' then',
'        wwv_flow_collection.update_member(',
'            p_collection_name => l_collection_name,',
'            p_seq             => :ID,',
'            p_c001            => :STEP_NUMBER,',
'            p_c002            => :PAGE_ID,',
'            p_c003            => :PAGE_NAME,',
'            p_c004            => 0 );',
'    when ''D'' then',
'        wwv_flow_collection.delete_member(',
'            p_collection_name => l_collection_name,',
'            p_seq => :ID );',
'    end case;',
'end;'))
,p_attribute_05=>'N'
,p_attribute_06=>'N'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>19904408518194934
);
end;
/
