 p_id=>wwv_flow_imp.id(4663588459677276)
,p_process_sequence=>5
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Update APEX Dictionary Cache'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_object_type wwv_flow_tables_views_dev.object_type%type;',
'begin',
'    select object_type',
'      into l_object_type',
'      from wwv_flow_tables_views_dev',
'     where owner       = :P2515_TABLE_OWNER',
'       and object_name = :P2515_TABLE_NAME;',
'',
'    --- if table, set APEX dictionary cache',
'    if l_object_type = ''TABLE'' then',
'        wwv_dictionary_cache_dev.set_dictionary_table_cache(',
'             p_workspace_name          => htmldb_util.find_workspace( p_security_group_id => :WORKSPACE_ID ),',
'             p_schema                  => :P2515_TABLE_OWNER,',
'             p_table_name              => :P2515_TABLE_NAME,',
'             p_flow_id                 => :FB_FLOW_ID,',
'             p_cache_fk_references     => true );',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(8231412845249320)
,p_process_when=>':P2515_LOCATION = ''LOCAL'' and :P2515_SOURCE_TYPE = ''TABLE'''
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_internal_uid=>4663588459677276
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(8260290820249344)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Set Data Source Items'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- reset previous values, if any',
':P2515_TAB_OWNER := null;',
':P2515_TAB_NAME := null;',
':P2515_QUERY_TYPE := null;',
':P2515_SQL_SOURCE := null;',
'',
'if :P2515_LOCATION = wwv_flow_exec_api.c_location_local_db then',
'    :P2515_TAB_OWNER        := :P2515_TABLE_OWNER;',
'    :P2515_TAB_NAME         := :P2515_TABLE_NAME;',
'    :P2515_QUERY_TYPE       := :P2515_SOURCE_TYPE;',
'    :P2515_SQL_SOURCE       := :P2515_SQL;',
'elsif :P2515_LOCATION = wwv_flow_exec_api.c_location_remote_db then',
'    :P2515_TAB_OWNER        := :P2515_REMOTE_TABLE_OWNER;',
'    :P2515_TAB_NAME         := :P2515_REMOTE_TABLE_NAME;',
'    :P2515_QUERY_TYPE       := :P2515_REMOTE_SOURCE_TYPE;',
'    :P2515_SQL_SOURCE       := :P2515_REMOTE_SQL;',
'end if;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(8231412845249320)
,p_internal_uid=>8260290820249344
);
