wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(4804252666096938)
,p_name=>'P2516_DETAIL_FK_CONS'
,p_item_sequence=>10
,p_item_plug_id=>wwv_flow_imp.id(4804179944096937)
,p_prompt=>'Master Detail Foreign Key'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with cc as (',
'    select /*+materialize*/',
'           cc.owner,',
'           cc.constraint_name,',
'           cc.table_name,',
'           cc.column_name,',
'           cc.position',
'      from sys.dba_cons_columns cc',
'     where cc.owner      = :P2501_TAB_OWNER',
'     -- 2501 is master items',
'     -- 2521 is detail items',
'       and cc.table_name in ( :P2501_TAB_NAME, :P2515_TAB_NAME ) ),',
'cons_cols as (',
'    select cc.owner,',
'           cc.constraint_name,',
'           cc.table_name,',
'           cc.column_name,',
'           cc.position,',
'           c.constraint_type,',
'           c.r_owner,',
'           c.r_constraint_name',
'      from cc,',
'           sys.dba_constraints  c',
'     where cc.owner           =  c.owner',
'       and cc.constraint_name =  c.constraint_name',
'       and c.constraint_type  in (''R'', ''P'', ''U'') )',
'select LISTAGG(parent.column_name, '', '') WITHIN GROUP (ORDER BY parent.position)||',
'       '' -> ''||',
'       LISTAGG(child.column_name, '', '')  WITHIN GROUP (ORDER BY child.position)  d,',
'       child.constraint_name r',
'    from cons_cols child,cons_cols parent',
'    where child.constraint_type  =  ''R''',
'    and parent.constraint_type  in (''P'',''U'')',
'    and child.r_constraint_name =  parent.constraint_name',
'    and child.r_owner           =  parent.owner',
'    and child.position          =  parent.position',
'    and parent.table_name       =  :P2501_TAB_NAME',
'group by child.constraint_name'))
,p_lov_display_null=>'YES'
,p_lov_null_text=>'- Select Master Detail Relationship -'
,p_cHeight=>1
,p_display_when=>':P2515_SHOW_RELATED_TABLES = ''Y'' and :P2515_LOCATION = ''LOCAL'''
,p_display_when2=>'PLSQL'
,p_display_when_type=>'EXPRESSION'
,p_field_template=>wwv_flow_imp.id(452656722938220607)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>'Select the foreign key that relates between the master and detail tables.'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
