,p_prompt=>'Master Column'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'WIZ_COLUMNS_LIST'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select c001 column_name_esc,',
'       c002 column_name',
'  from wwv_flow_collections',
