wwv_flow_imp_page.create_page_computation(
 p_id=>wwv_flow_imp.id(2418626056518814)
,p_computation_sequence=>30
,p_computation_item=>'P3120_LINK_TARGET'
,p_computation_type=>'FUNCTION_BODY'
,p_computation_language=>'PLSQL'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_link        varchar2(4000);',
'begin',
'    if :P3120_LINK_TARGET_TYPE in ( ''REDIRECT_APP'', ''REDIRECT_PAGE'' ) then',
'        l_link := ''f?p='' ||',
'                  case when :P3120_LINK_TARGET_TYPE = ''REDIRECT_APP'' then',
'                      :P3120_TARGET_APP_ID',
'                  when :P3120_LINK_TARGET_TYPE = ''REDIRECT_PAGE'' then',
'                      ''&'' || ''APP_ID.''',
'                  end || '':'' ||',
'                  :P3120_TARGET_PAGE_ID || '':&'' || ''APP_SESSION.:'' ||',
'                  :P3120_TARGET_REQUEST || '':&'' || ''DEBUG.:'' ||',
'                  case when :P3120_TARGET_CLEAR_PAGE = ''YES'' then',
'                      ''RP,'' || :P3120_TARGET_CLEAR_CACHE',
'                  else',
'                      :P3120_TARGET_CLEAR_CACHE',
'                  end || '':'' ||',
'                  :P3120_ARG_NAMES || '':'' || :P3120_ARG_VALUES;',
'    elsif :P3120_LINK_TARGET_TYPE is null then',
'        l_link := null;',
'    else',
'        l_link := :P3120_TARGET_URL;',
'    end if;',
'    ',
'    return l_link;',
'end;',
''))
);
