wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3162165201903351)
,p_plug_name=>'Generative AI Configurations'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(646287526247383209)
,p_plug_display_sequence=>20
,p_include_in_reg_disp_sel_yn=>'Y'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with messages as (',
'    select ( select wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_UP_TO_DATE'') from sys.dual ) up_to_date,',
'           ( select wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_NEEDS_REFRESH'') from sys.dual ) needs_refresh,',
'           ( select wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_UNKNOWN'') from sys.dual ) unknown_status,',
'           ( select wwv_flow_lang_dev.builder_message(''SUBSCRIBED_FROM.NONEXISTING_MASTER'') from sys.dual ) no_master',
'      from sys.dual )',
'select a.id,',
'       a.static_id,',
'       a.name,',
'       case when a.remote_server_id is not null then',
'           ( select rs.name',
'               from wwv_remote_servers rs',
'              where rs.server_type       = ''GENERATIVE_AI''',
'                and rs.security_group_id = :WORKSPACE_ID',
'                and rs.id                = a.remote_server_id )',
'       else',
'           ( select wwv_flow_lang.message( ''APPLICATION_DEFAULT'' ) from sys.dual )',
'       end as service,',
'       ( select count(*)',
'           from wwv_flow_ai_config_rag_sources rag',
'          where rag.ai_config_id      = a.id',
'            and rag.security_group_id = :WORKSPACE_ID ) as rag_sources,',
'       coalesce( a.last_updated_on, a.created_on ) last_updated,',
'       coalesce( a.last_updated_by, a.created_by ) last_updated_by,',
'       --',
'       case when a.reference_id is not null then',
'           coalesce ( to_char( master.flow_id ), messages.no_master )',
'       end as subscribed_from,',
'       ( select case when count(*) > 0 then count(*) end',
'           from wwv_flow_ai_configs sub',
'          where sub.reference_id      = a.id',
'            and sub.security_group_id = :WORKSPACE_ID ) as subscribers,',
'       case when a.reference_id is not null then',
'           case',
'               when master.version_scn = a.version_scn then',
'                   messages.up_to_date',
'               when master.version_scn != a.version_scn then',
'                   messages.needs_refresh',
'               else',
'                   messages.unknown_status',
'           end',
'       end subscription_status,',
'       --',
'       --',
'       null as action',
' from wwv_flow_ai_configs a,',
'      wwv_flow_ai_configs master,',
'      messages',
'where a.flow_id                    = :FB_FLOW_ID',
'  and a.security_group_id          = :WORKSPACE_ID',
'  and master.id (+)                = a.reference_id',
'  and master.security_group_id (+) = a.security_group_id'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
