);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(446769616471167960)
,p_plug_name=>'Generative AI Configurations History'
,p_region_template_options=>'#DEFAULT#:a-IRR-region--noOuterBorders'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(646287526247383209)
,p_plug_display_sequence=>20
,p_plug_display_column=>1
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select t.flow_user     as developer, ',
'       t.audit_date,',
'       case audit_action',
'         when ''I'' then i.a',
'         when ''D'' then d.a',
'         else          u.a',
'       end             as action,',
'       scn,',
'       audit_comment,',
'       flow_table_pk   as component_key,',
'       l.a             as object_type,',
'       t.object_name   as component_name',
'  from wwv_flow_builder_audit_trail t,',
'       ( select wwv_flow_lang.system_message(''F4350.CREATE'') a from sys.dual ) i,',
'       ( select wwv_flow_lang.system_message(''F4350.DELETE'') a from sys.dual ) d,',
'       ( select wwv_flow_lang.system_message(''F4350.CHANGE'') a from sys.dual ) u,',
'       ( select wwv_flow_lang.system_message(''PE.COMPONEN.TYPE.AI_CONFIG.SINGULAR'') a from sys.dual ) l',
' where t.flow_id           = :FB_FLOW_ID',
'   and t.security_group_id = :WORKSPACE_ID',
'   and t.flow_table        = ''WWV_FLOW_AI_CONFIGS''',
' union all',
'select t.flow_user     as developer, ',
'       t.audit_date,',
'       case audit_action',
'         when ''I'' then i.a',
'         when ''D'' then d.a',
'         else          u.a',
'       end             as action,',
'       scn,',
'       audit_comment,',
'       flow_table_pk   as component_key,',
'       l.a             as object_type,',
'       t.object_name   as component_name',
'  from wwv_flow_builder_audit_trail t,',
'       ( select wwv_flow_lang.system_message(''F4350.CREATE'') a from sys.dual ) i,',
'       ( select wwv_flow_lang.system_message(''F4350.DELETE'') a from sys.dual ) d,',
'       ( select wwv_flow_lang.system_message(''F4350.CHANGE'') a from sys.dual ) u,',
'       ( select wwv_flow_lang.system_message(''PE.COMPONEN.TYPE.AI_CONFIG_RAG_SOURCE.SINGULAR'' ) a from sys.dual ) l',
' where t.flow_id           = :FB_FLOW_ID',
'   and t.security_group_id = :WORKSPACE_ID',
'   and t.flow_table        = ''WWV_FLOW_AI_CONFIG_RAG_SOURCES'''))
,p_plug_source_type=>'NATIVE_IR'
,p_plug_query_show_nulls_as=>' - '
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_ai_enabled=>false
);
