,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'for l_rag in (',
'    select last_updated_by, last_updated_on, created_by, created_on ',
'      from wwv_flow_ai_config_rag_sources',
'     where id                = :P3505_ID',
'       and security_group_id = :WORKSPACE_ID ) ',
'loop',
'    wwv_flow_4000_ui.show_history (',
'        p_last_updated_by => l_rag.last_updated_by,',
'        p_last_updated_on => l_rag.last_updated_on,',
'        p_created_by      => l_rag.created_by,',
'        p_created_on      => l_rag.created_on );',
'     exit;',
'end loop;'))
,p_plug_source_type=>'NATIVE_PLSQL'
,p_plug_display_condition_type=>'ITEM_IS_NOT_NULL'
,p_plug_display_when_condition=>'P3505_ID'
);
