,p_is_persistent=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Specify a PL/SQL function body that returns a CLOB and generates the context for the AI service. Within the code, you can use the following special bind variables to access and evaluate the user''s prompt:',
'<dl>',
'    <dt><code>APEX$AI_LAST_USER_PROMPT</code></dt>',
'    <dd>Retrieves the most recent user-entered prompt.</dd>',
'    <dt><code>APEX$AI_ALL_USER_PROMPTS</code></dt>',
'    <dd>Retrieves all user prompts, concatenated into a single string.</dd>',
'</dl>',
'</p>',
'',
'<p>Example:</p>',
'<pre>',
'begin',
'    if lower( :APEX$AI_LAST_USER_PROMPT ) like ''%employee%'' then',
'        return ''Employee data'';',
'    else',
'        return ''Other data'';',
'    end if;',
'end;',
'</pre>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'PLSQL_FUNCTION_BODY',
