wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(146826158978)
,p_name=>'F4000_P4001_FLOW_STATUS'
,p_item_sequence=>170
,p_item_plug_id=>wwv_flow_imp.id(74090417789091344)
,p_use_cache_before_default=>'NO'
,p_item_default=>'AVAILABLE'
,p_prompt=>'Status'
,p_source=>'FLOW_STATUS'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'LIST_FLOW_STATUS'
,p_lov=>'.'||wwv_flow_imp.id(634347472712995)||'.'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_escape_on_http_input=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Specifies whether or not the application is available or unavailable for use. <p>',
'Options include:<br>',
'<ul>',
'<li><strong>Available</strong> - Application is available with no restrictions.</li>',
'<li><strong>Available with Developer Toolbar</strong> - Application is available for use. For developers, the Developer Toolbar is included on each page. Requires the developer to be logged in to the App Builder in the same browser session.</li>',
'<li><strong>Available to Developers Only</strong> - Application is available to users having developer privileges.</li>',
'<li><strong>Restricted Access</strong> - Application is available to developers named in Restrict to comma separated user list.</li>',
'<li><strong>Unavailable</strong> - Application cannot be run or edited. The message in Message for unavailable application displays when users attempt to access the application.</li>',
'<li><strong>Unavailable (Status Shown with PL/SQL)</strong> - Application cannot be run or edited.</li>',
'<li><strong>Unavailable (Redirect to URL)</strong> - Application cannot be run. The user is linked to the URL entered in Message for unavailable application.</li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
