wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1931095356915001)
,p_name=>'P4001_ORACLE_TEXT_FUNCTION_TYPE'
,p_item_sequence=>140
,p_item_plug_id=>wwv_flow_imp.id(198116031744061165)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Text Query Function'
,p_source=>'ORACLE_TEXT_FUNCTION_TYPE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'TEXT_QUERY_FUNCTION_TYPE'
,p_lov=>'.'||wwv_flow_imp.id(1936977999928971)||'.'
,p_lov_display_null=>'YES'
,p_lov_null_text=>'None'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>The Oracle Text query syntax is very complex and powerful and provides a rich set of query operators to deal with wildcards, stemming, fuzzy searches and so forth. For end users, this syntax is often hard to understand. To simplify the search proc'
||'ess for users, you can select a function that automatically converts simple end user input into an Oracle Text query, with the advanced search features applied automatically. Options include:</p>',
'<ul>',
'    <li><strong>None</strong> - &PRODUCT_NAME. encloses each query term with "{" and "}", except the keywords <strong>and</strong> and <strong>or</strong>.</li>',
'    <li><strong>Search Engine</strong> - This function performs a query relaxation search to retrieve relevant results beyond just exact matches. The goal is to get as many related results as possible, allowing users to easily find related informatio'
||'n without needing to input precise queries. The search process begins with an exact match search and then progressively relaxes the query using techniques like stemming and fuzzy matching. While maximizing the number of results, the search engine fun'
||'ction ensures that the most exact and relevant matches are always ranked at the top of the search results.</li>',
'    <li><strong>Expert Search</strong> - This function supports more advanced search operators for precise queries. It allows exact matching, Boolean operators (AND, OR, NOT), precedence with parentheses and proximity search. Additional parameters al'
||'low customizing search behavior. This is best when requiring highly accurate results from very specific queries. Also see the <code>QUERY_EXPERT_SEARCH</code> function within the <code>APEX_SEARCH</code> package.</li>',
'    <li><strong>Custom</strong> - Provide a custom function.</li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1950100044091138)
,p_name=>'P4001_TOKENIZE_ROW_SEARCH'
,p_is_required=>true
,p_item_sequence=>160
,p_item_plug_id=>wwv_flow_imp.id(198116031744061165)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Tokenize Row Search'
,p_source=>'TOKENIZE_ROW_SEARCH'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_YES_NO'
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Specify how the search terms are applied when a <em>row search</em> is performed within a component.</p>',
'<p>Selecting <strong>On</strong> will treat each word of a search term separately, to match a record where the words are contained in any of the columns, together or independently. To search for an exact phrase, use double quotes (") around the searc'
||'h terms. For example, "ui developer". To escape a double quote in a search term, use a double quote ("").',
'</p> ',
'<h4>Examples</h4>',
'<dl>',
'<dt>1- Any record including the words "red" and "shoes"<dt><dd>search term: red shoes</dd>',
'<dt>2- Any record including the word "developer" and the exact expression "ui designer"</dt><dd>search term: developer "ui designer"</dd>',
'<dt>3- Any record including the word "author" and the exact expression "the sky is "blue" and nice"</dt><dd>search term: author "the sky is ""blue"" and nice"</dd>',
'</dl>',
'<p>Selecting <strong>Off</strong> will treat the whole search term as an exact match.</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'use_defaults', 'Y')).to_clob
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(2001338047304309)
,p_name=>'P4001_TASK_VACATION_RULE_PROC'
,p_item_sequence=>10
,p_item_plug_id=>wwv_flow_imp.id(2200978967294804)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Task Vacation Rule Procedure'
,p_source=>'TASK_VACATION_RULE_PROCEDURE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>100
,p_cMaxlength=>500
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Specify the name of a PL/SQL procedure in the format <strong>[schemaName.[packageName.]]procedureName</strong>. ',
'The procedure is expected to return additional alternate participants for task definitions in this application.',
'The vacation rule procedure should implement the following interface.</p>',
'<pre>',
'    procedure my_vacation_rule (',
'        p_param   in apex_approval.t_vacation_rule_input,',
'        p_result  out apex_approval.t_vacation_rule_output );',
'</pre>',
'<p>The procedure input is of type <strong>apex_approval.t_vacation_rule_input</strong> and the result output is of type <strong>apex_approval.t_vacation_rule_output</strong> </p>',
'<p>',
'This example shows a vacation rule procedure implementation where SCOTT is added as an alternate participant as JANE ',
'would be on maternity leave.</p>',
'<pre>',
'',
'    procedure alternate_job_approvers(',
'                p_param    in apex_approval.t_vacation_rule_input,',
'                p_result  out apex_approval.t_vacation_rule_result)',
'    is ',
'        l_result            apex_approval.t_vacation_rule_result;',
'        l_changes           apex_approval.t_task_participant_changes;',
'        l_participants      apex_approval.t_task_participants;',
'        l_new_participant   apex_approval.t_task_participant;',
'        l_old_participant   apex_approval.t_task_participant;',
'        l_has_changed       boolean                             := false;',
'        l_index             pls_integer                         := 1;',
'    begin',
'        l_participants := p_param.original_participants;',
'        for i in 1..l_participants.count loop',
'            if l_participants(i).value = ''JANE'' then',
'                l_old_participant               :=  l_participants(i);',
'                l_new_participant.value         := ''SCOTT'';',
'                l_new_participant.type          := ''POTENTIAL_OWNER'';',
'                l_new_participant.identity      := ''USER'';',
'                l_has_changed                   := true;',
'            end if;',
'        end loop;',
'        if l_has_changed then',
'            l_participants(l_participants.count + 1) := l_new_participant;',
'        ',
'            l_changes(l_index).old_participant   := l_old_participant;',
'            l_changes(l_index).new_participant   := l_new_participant;',
'            l_changes(l_index).change_reason     := ''Jane is out on maternity leave'';',
'        end if;',
'        l_result.participant_changes            := l_changes;',
'        l_result.has_participant_changes        := l_has_changed;',
'        p_result                                := l_result;',
'    end;',
'</pre>',
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'TEXT',
  'trim_spaces', 'BOTH')).to_clob
);
