wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(632908701274265897)
,p_plug_name=>'Templates'
,p_region_template_options=>'#DEFAULT#:a-IRR-region--noOuterBorders:a-IRR-region--responsiveIconView'
,p_plug_template=>wwv_flow_imp.id(646287526247383209)
,p_plug_display_sequence=>80
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select decode( template_type,',
'               ''PAGE'',wwv_flow_lang.system_message_lit(''F4000.PAGE''),',
'               ''REGION'',wwv_flow_lang.system_message_lit(''F4000.REGION''),',
'               ''LABEL'',wwv_flow_lang.system_message_lit(''F4000.ITEM''),',
'               ''LIST'',wwv_flow_lang.system_message_lit(''F4000.LIST_INITCAP''),',
'               ''POPUP_LOV'',wwv_flow_lang.system_message_lit(''F4000.P371.POPUP_LOV''),',
'               ''CALENDAR'',wwv_flow_lang.system_message_lit(''LEGACY_CALENDAR''),',
'               ''MENU'',wwv_flow_lang.system_message_lit(''BREADCRUMB''),',
'               ''BUTTON'',wwv_flow_lang.system_message_lit(''F4000.BUTTON''),',
'               ''REPORT'',wwv_flow_lang.system_message_lit(''REPORT''),',
'               ''TEMPLATE_COMPONENT'',wwv_flow_lang.system_message_lit(''F4000.TEMPLATE_COMPONENT''),',
'               template_type ) t,',
'       upper_name,',
'       template_name n,',
'       internal_name,',
'       edit_page,',
'       reference_count c,',
'       case when x.security_group_id not in ( 11, 12 ) then last_updated_on end last_updated_on,',
'       case when x.security_group_id not in ( 11, 12 ) then lower(last_updated_by) end last_updated_by,',
'       ( select case',
'                  when x.security_group_id in ( 11, 12 ) then wwv_flow_lang.system_message( ''SUBSCRIBED_FROM.THEME'' )',
'                  when x.reference_id is not null then wwv_flow_lang.system_message( ''SUBSCRIBED_FROM.THEME'' )',
'                  else x.subscribed_from',
'                end',
'           from wwv_flow_themes',
'          where flow_id  = :FB_FLOW_ID',
'            and theme_id = x.theme_id',
'       ) as subscribed_from,',
'       subscribers,',
'       decode(is_default,',
'              0, ''N'',',
'              ''Y'' ) as is_default,',
'       decode(is_default,',
'              0,'''',',
'              ''icon-check'' ) as default_css,',
'       case template_type',
'           when ''REGION''             then ''538''',
'           when ''PAGE''               then ''568''',
'           when ''REPORT''             then ''569''',
'           when ''BUTTON''             then ''571''',
'           when ''CALENDAR''           then ''564''',
'           when ''LIST''               then ''573''',
'           when ''LABEL''              then ''574''',
'           when ''MENU''               then ''636''',
'           when ''TEMPLATE_COMPONENT'' then ''4407''',
'           else null',
'       end as copy_template_page,',
'       decode(template_type,',
'           ''REGION'',',
'            wwv_flow_utilities.prepare_url(''f?p=4000:538:''||:APP_SESSION||'':::538:P538_FROM_TEMPLATE_ID:''||template_id),',
'           ''PAGE'',',
'            wwv_flow_utilities.prepare_url(''f?p=4000:568:''||:APP_SESSION||'':::568:P568_FROM_TEMPLATE_ID:''||template_id),',
'           ''REPORT'',',
'            wwv_flow_utilities.prepare_url(''f?p=4000:569:''||:APP_SESSION||'':::569:P569_FROM_TEMPLATE_ID:''||template_id),',
'           ''BUTTON'',',
'            wwv_flow_utilities.prepare_url(''f?p=4000:571:''||:APP_SESSION||'':::571:P571_FROM_TEMPLATE_ID:''||template_id),',
'           ''LIST'',',
'            wwv_flow_utilities.prepare_url(''f?p=4000:573:''||:APP_SESSION||'':::573:P573_FROM_TEMPLATE_ID:''||template_id),',
'           ''LABEL'',',
'            wwv_flow_utilities.prepare_url(''f?p=4000:574:''||:APP_SESSION||'':::574:P574_FROM_TEMPLATE_ID:''||template_id),',
'           ''MENU'',',
'            wwv_flow_utilities.prepare_url(''f?p=4000:636:''||:APP_SESSION||'':::636:P636_FROM_TEMPLATE_ID:''||template_id),',
'           ''TEMPLATE_COMPONENT'',',
'           wwv_flow_utilities.prepare_url(''f?p=4000:4407:''||:APP_SESSION||'':::4407:P4407_FROM_PLUGIN_ID:''||template_id),',
'           null',
'        ) as action_link,',
'       template_id,',
'       template_type,',
'       case when template_type = ''TEMPLATE_COMPONENT''',
'            then ''P''',
'            else ''F4000_P'' ',
'       end || edit_page || ''_ID'' as edit_item,',
'       --',
'       theme_id,',
'       null action',
'from ( ',
'    ',
'select ''POPUP_LOV'' template_type,',
'        upper(''Popup LOV'') upper_name,',
'        ''251'' edit_page,',
'        ''Popup LOV'' template_name,',
'        ''POPUP_LOV'' internal_name,',
'        case',
'            when plt.theme_id in (  select theme_id',
'                                    from wwv_flows',
'                                    where id = :FB_FLOW_ID',
'                                   and security_group_id = :WORKSPACE_ID ) then 1',
'            else 0',
'        end reference_count,',
'        last_updated_on,',
'        last_updated_by,',
'        reference_id,',
'        case when reference_id is not null then',
'            coalesce ( ( select to_char( flow_id )',
'                           from wwv_flow_popup_lov_template',
'                          where id                = plt.reference_id',
'                         and security_group_id in ( :WORKSPACE_ID, 11, 12 )',
'                        ),',
'                        wwv_flow_lang.system_message( ''SUBSCRIBED_FROM.NONEXISTING_MASTER'' )',
'                     )',
'        end as subscribed_from,',
'        ( select case when count(*) > 0 then count(*) end',
'            from wwv_flow_popup_lov_template',
'           where reference_id      = plt.id',
'             and security_group_id = :WORKSPACE_ID',
'        ) as subscribers,',
'        case',
'            when plt.theme_id in ( select theme_id',
'                                     from wwv_flows',
'                                    where id = :FB_FLOW_ID',
'                                      and security_group_id = :WORKSPACE_ID ) then 1',
'            else 0',
'        end is_default,',
'        current_app_theme_id theme_id,',
'        id template_id,',
'        security_group_id',
'    from wwv_theme_popup_lov_templates plt',
'    union all',
'    select ''CALENDAR'' template_type,',
'        upper(name) upper_name,',
'        ''697'' edit_page,',
'        name template_name,',
'        internal_name,',
'        ( select count(*)',
'            from wwv_flow_cals',
'            where template_id = c.id',
'             and flow_id = :FB_FLOW_ID',
'             and security_group_id = :WORKSPACE_ID )',
'            + ( select count(*)',
'                from wwv_flow_themes',
'                where flow_id = :FB_FLOW_ID',
'                 and security_group_id = :WORKSPACE_ID',
'                 and theme_id = c.current_app_theme_id',
'                 and default_calendar_template = c.id ) reference_count,',
'        last_updated_on,',
'        last_updated_by,',
'        reference_id,',
'        case when reference_id is not null then',
'            coalesce ( ( select to_char( flow_id )',
'                           from wwv_flow_cal_templates',
'                          where id                = c.reference_id',
'                         and security_group_id in ( :WORKSPACE_ID, 11, 12 )',
'                        ),',
'                        wwv_flow_lang.system_message( ''SUBSCRIBED_FROM.NONEXISTING_MASTER'' )',
'                     )',
'        end as subscribed_from,',
'        ( select case when count(*) > 0 then count(*) end',
'            from wwv_flow_cal_templates',
'           where reference_id      = c.id',
'             and security_group_id = :WORKSPACE_ID',
'        ) as subscribers,',
'        ( select count(*)',
'            from wwv_flow_themes',
'           where flow_id = :FB_FLOW_ID',
'             and security_group_id = :WORKSPACE_ID',
'             and theme_id = c.current_app_theme_id',
'             and default_calendar_template = c.id ) is_default,',
'        current_app_theme_id theme_id,',
'        id template_id,',
'        security_group_id',
'    from wwv_theme_calendar_templates c',
'    union all',
'    select ''MENU'' template_type,',
'        upper(name) upper_name,',
'        ''289'' edit_page,',
'        name template_name,',
'        internal_name,',
'        ( select count(*)',
'            from wwv_flow_page_plugs r',
'            where r.flow_id = :FB_FLOW_ID',
'             and r.security_group_id = :WORKSPACE_ID',
'             and r.menu_template_id = m.id )',
'            + ( select count(*)',
'                from wwv_flow_themes',
'                where flow_id = :FB_FLOW_ID',
'                 and security_group_id = :WORKSPACE_ID',
'                 and theme_id = m.current_app_theme_id',
'                 and default_menu_template = m.id ) reference_count,',
'        last_updated_on,',
'        last_updated_by,',
'        reference_id,',
'        case when reference_id is not null then',
'            coalesce ( ( select to_char( flow_id )',
'                           from wwv_flow_menu_templates',
'                          where id                = m.reference_id',
'                         and security_group_id in ( :WORKSPACE_ID, 11, 12 )',
'                        ),',
'                        wwv_flow_lang.system_message( ''SUBSCRIBED_FROM.NONEXISTING_MASTER'' )',
'                     )',
'        end as subscribed_from,',
'        ( select case when count(*) > 0 then count(*) end',
'            from wwv_flow_menu_templates',
'           where reference_id      = m.id',
'             and security_group_id = :WORKSPACE_ID',
'        ) as subscribers,',
'        ( select count(*)',
'            from wwv_flow_themes',
'           where flow_id = :FB_FLOW_ID',
'             and security_group_id = :WORKSPACE_ID',
'             and theme_id = m.current_app_theme_id',
'             and default_menu_template = m.id ) is_default,',
'        current_app_theme_id theme_id,',
'        id template_id,',
'        security_group_id',
'    from wwv_theme_breadcrumb_templates m',
'    union all',
'    select ''BUTTON'' template_type,',
'        upper(template_name) upper_name,',
'        ''204'' edit_page,',
'        template_name,',
'        internal_name,',
'        ( select count(*)',
'            from wwv_flow_step_buttons sb',
'            where sb.flow_id = :FB_FLOW_ID',
'             and sb.security_group_id = :WORKSPACE_ID',
'             and sb.button_template_id = b.id )',
'            + ( select count(*)',
'                from wwv_flow_step_items si',
'                where flow_id = :FB_FLOW_ID',
'                 and si.security_group_id = :WORKSPACE_ID',
'                 and si.TAG_ATTRIBUTES = ''template:''||to_char(b.id) )',
'            + ( select count(*)',
'                from wwv_flow_themes',
'                where flow_id = :FB_FLOW_ID',
'                 and security_group_id = :WORKSPACE_ID',
'                 and theme_id = b.current_app_theme_id',
'                 and default_button_template = b.id ) reference_count,',
'        last_updated_on,',
'        last_updated_by,',
'        reference_id,',
'        case when reference_id is not null then',
'            coalesce ( ( select to_char( flow_id )',
'                           from wwv_flow_button_templates',
'                          where id                = b.reference_id',
'                         and security_group_id in ( :WORKSPACE_ID, 11, 12 )',
'                        ),',
'                        wwv_flow_lang.system_message( ''SUBSCRIBED_FROM.NONEXISTING_MASTER'' )',
'                     )',
'        end as subscribed_from,',
'        ( select case when count(*) > 0 then count(*) end',
'            from wwv_flow_button_templates',
'           where reference_id      = b.id',
'             and security_group_id = :WORKSPACE_ID',
'        ) as subscribers,',
'        ( select count(*)',
'            from wwv_flow_themes',
'           where flow_id = :FB_FLOW_ID',
'             and security_group_id = :WORKSPACE_ID',
'             and theme_id = b.current_app_theme_id',
'             and default_button_template = b.id ) is_default,',
'        current_app_theme_id theme_id,',
'        id template_id,',
'        security_group_id',
'    from wwv_theme_button_templates b',
'    union all',
'    select ''LABEL'' template_type,',
'        upper(template_name) upper_name,',
'        ''85'' edit_page,',
'        template_name,',
'        internal_name,',
'        ( select count(*)',
'            from wwv_flow_step_items i',
'           where i.flow_id = :FB_FLOW_ID',
'             and i.security_group_id = :WORKSPACE_ID',
'             and i.ITEM_FIELD_TEMPLATE = f.id )',
'            + ( select count(*)',
'                 from wwv_flow_themes',
'                 where flow_id = :FB_FLOW_ID',
'                 and security_group_id = :WORKSPACE_ID',
'                 and theme_id = f.current_app_theme_id',
'                 and default_label_template = f.id ) reference_count,',
'        last_updated_on,',
'        last_updated_by,',
'        reference_id,',
'        case when reference_id is not null then',
'            coalesce ( ( select to_char( flow_id )',
'                           from wwv_flow_field_templates',
'                          where id                = f.reference_id',
'                            and security_group_id in ( :WORKSPACE_ID, 11, 12 )',
'                        ),',
'                        wwv_flow_lang.system_message( ''SUBSCRIBED_FROM.NONEXISTING_MASTER'' )',
'                     )',
'        end as subscribed_from,',
'        ( select case when count(*) > 0 then count(*) end',
'            from wwv_flow_field_templates',
'           where reference_id      = f.id',
'             and security_group_id = :WORKSPACE_ID',
'        ) as subscribers,',
'        ( select count(*)',
'            from wwv_flow_themes',
'           where flow_id = :FB_FLOW_ID',
'             and security_group_id = :WORKSPACE_ID',
'             and theme_id = f.current_app_theme_id',
'             and default_label_template = f.id ) is_default,',
'        current_app_theme_id theme_id,',
'        id template_id,',
'        security_group_id',
'    from wwv_theme_item_templates f',
'    union all',
'    select ''LIST'' template_type,',
'        upper(list_template_name) upper_name,',
'        ''4655'' edit_page,',
'        l.list_template_name template_name,',
'        internal_name,',
'        ( select count(*)',
'            from wwv_flow_page_plugs p',
'            where p.flow_id = :FB_FLOW_ID',
'             and p.security_group_id = :WORKSPACE_ID',
'             and p.list_template_id = l.id)',
'            + ( select count(*)',
'                from wwv_flow_themes',
'                where flow_id = :FB_FLOW_ID',
'                 and security_group_id = :WORKSPACE_ID',
'                 and theme_id = l.current_app_theme_id',
'                 and default_list_template = l.id ) reference_count,',
'        last_updated_on,',
'        last_updated_by,',
'        reference_id,',
'        case when reference_id is not null then',
'            coalesce ( ( select to_char( flow_id )',
'                           from wwv_flow_list_templates',
'                          where id                = l.reference_id',
'                         and security_group_id in ( :WORKSPACE_ID, 11, 12 )',
'                        ),',
'                        wwv_flow_lang.system_message( ''SUBSCRIBED_FROM.NONEXISTING_MASTER'' )',
'                     )',
'        end as subscribed_from,',
'        ( select case when count(*) > 0 then count(*) end',
'            from wwv_flow_list_templates',
'           where reference_id      = l.id',
'             and security_group_id = :WORKSPACE_ID',
'        ) as subscribers,',
'        ( select count(*)',
'            from wwv_flow_themes',
'           where flow_id = :FB_FLOW_ID',
'             and security_group_id = :WORKSPACE_ID',
'             and theme_id = l.current_app_theme_id',
'             and default_list_template = l.id ) is_default,',
'        current_app_theme_id theme_id,',
'        id template_id,',
'        security_group_id',
'    from wwv_theme_list_templates l',
'    union all',
'    select ''REPORT'' template_type,',
'        upper(row_template_name) upper_name,',
'        case when row_template_type = ''GENERIC_COLUMNS'' then ''258''',
'            else ''4654''',
'        end as edit_page,',
'        row_template_name template_name,',
'        internal_name,',
'        ( select count(*)',
'            from wwv_flow_page_plugs p',
'            where flow_id = :FB_FLOW_ID',
'             and p.security_group_id = :WORKSPACE_ID',
'             and p.PLUG_QUERY_ROW_TEMPLATE = ro.id',
'             and plug_source_type in (''NATIVE_SQL_REPORT'', ''NATIVE_TABFORM'') )',
'            + ( select count(*)',
'                from wwv_flow_themes',
'                where flow_id = :FB_FLOW_ID',
'                 and security_group_id = :WORKSPACE_ID',
'                 and theme_id = ro.current_app_theme_id',
'                 and default_report_template = ro.id ) reference_count,',
'        last_updated_on,',
'        last_updated_by,',
'        reference_id,',
'        case when reference_id is not null then',
'            coalesce ( ( select to_char( flow_id )',
'                           from wwv_flow_row_templates',
'                          where id                = ro.reference_id',
'                         and security_group_id in ( :WORKSPACE_ID, 11, 12 )',
'                        ),',
'                        wwv_flow_lang.system_message( ''SUBSCRIBED_FROM.NONEXISTING_MASTER'' )',
'                     )',
'        end as subscribed_from,',
'        ( select case when count(*) > 0 then count(*) end',
'            from wwv_flow_row_templates',
'           where reference_id      = ro.id',
'             and security_group_id = :WORKSPACE_ID',
'        ) as subscribers,',
'        ( select count(*)',
'            from wwv_flow_themes',
'           where flow_id = :FB_FLOW_ID',
'             and security_group_id = :WORKSPACE_ID',
'             and theme_id = ro.current_app_theme_id',
'             and default_report_template = ro.id ) is_default,',
'        current_app_theme_id theme_id,',
'        id template_id,',
'        security_group_id',
'    from wwv_theme_report_templates ro',
'    union all',
'    select ''PAGE'' template_type,',
'        upper(name) upper_name,',
'        ''4307'' edit_page,',
'        name template_name,',
'        internal_name,',
'        ( select count(*)',
'            from wwv_flow_steps s',
'            where flow_id = :FB_FLOW_ID',
'             and s.security_group_id = :WORKSPACE_ID',
'             and s.step_template = p.id and s.id > 0 )',
'             + ( select count(*)',
'                   from wwv_flow_themes',
'                  where flow_id           = :FB_FLOW_ID',
'                    and security_group_id = :WORKSPACE_ID',
'                    and (    default_page_template     = p.id ',
'                          or error_template            = p.id ',
'                          or printer_friendly_template = p.id ) ) reference_count,',
'        last_updated_on,',
'        last_updated_by,',
'        reference_id,',
'        case when reference_id is not null then',
'            coalesce ( ( select to_char( flow_id )',
'                           from wwv_flow_templates',
'                          where id                = p.reference_id',
'                         and security_group_id in ( :WORKSPACE_ID, 11, 12 )',
'                        ),',
'                        wwv_flow_lang.system_message( ''SUBSCRIBED_FROM.NONEXISTING_MASTER'' )',
'                     )',
'        end as subscribed_from,',
'        ( select case when count(*) > 0 then count(*) end',
'            from wwv_flow_templates',
'           where reference_id      = p.id',
'             and security_group_id = :WORKSPACE_ID',
'        ) as subscribers,',
'        ( select count(*)',
'            from wwv_flow_themes',
'           where flow_id = :FB_FLOW_ID',
'             and security_group_id = :WORKSPACE_ID',
'             and DEFAULT_PAGE_TEMPLATE=p.id ) is_default,',
'        current_app_theme_id theme_id,',
'        id template_id,',
'        security_group_id',
'    from wwv_theme_page_templates p',
'    union all',
'    select ''REGION'' template_type,',
'        upper(page_plug_template_name) upper_name,',
'        ''4653'' edit_page,',
'        page_plug_template_name template_name,',
'        internal_name,',
'        ( select count(*)',
'            from wwv_flow_page_plugs p',
'            where p.flow_id = :FB_FLOW_ID',
'             and p.security_group_id = :WORKSPACE_ID',
'             and p.PLUG_TEMPLATE = r.id )',
'            + ( select count(*)',
'                from wwv_flow_themes',
'                where flow_id = :FB_FLOW_ID',
'                 and security_group_id = :WORKSPACE_ID',
'                 and default_region_template = r.id ) reference_count,',
'        last_updated_on,',
'        last_updated_by,',
'        reference_id,',
'        case when reference_id is not null then',
'            coalesce ( ( select to_char( flow_id )',
'                           from wwv_flow_page_plug_templates',
'                          where id                = r.reference_id',
'                         and security_group_id in ( :WORKSPACE_ID, 11, 12 )',
'                        ),',
'                        wwv_flow_lang.system_message( ''SUBSCRIBED_FROM.NONEXISTING_MASTER'' )',
'                     )',
'        end as subscribed_from,',
'        ( select case when count(*) > 0 then count(*) end',
'            from wwv_flow_page_plug_templates',
'           where reference_id      = r.id',
'             and security_group_id = :WORKSPACE_ID',
'        ) as subscribers,',
'        ( select count(*)',
'            from wwv_flow_themes',
'           where flow_id = :FB_FLOW_ID',
'             and security_group_id = :WORKSPACE_ID',
'             and default_region_template = r.id ) is_default,',
'        current_app_theme_id theme_id,',
'        id template_id,',
'        security_group_id',
'    from wwv_theme_region_templates r',
'    union all',
'    select ''TEMPLATE_COMPONENT'' template_type,',
'        upper(name) upper_name,',
'        ''4410'' edit_page,',
'        builder_name template_name,',
'        static_id internal_name,',
'        ( select count(*)',
'            from wwv_flow_page_plugs r',
'           where r.flow_id           = :FB_FLOW_ID',
'             and r.security_group_id = :WORKSPACE_ID',
'             and r.plug_source_type  = p.used_name ) +',
'        ( select count(*)',
'            from wwv_flow_worksheet_columns c',
'           where c.flow_id           = :FB_FLOW_ID',
'             and c.security_group_id = :WORKSPACE_ID',
'             and c.display_text_as   = p.used_name ) as reference_count,',
'        last_updated_on,',
'        last_updated_by,',
'        reference_id,',
'        case when reference_id is not null then',
'            coalesce ( ( select to_char( flow_id )',
'                           from wwv_flow_template_components',
'                          where id                = p.reference_id',
'                         and security_group_id in ( :WORKSPACE_ID, 11, 12 )',
'                        ),',
'                        wwv_flow_lang.system_message( ''SUBSCRIBED_FROM.NONEXISTING_MASTER'' )',
'                     )',
'        end as subscribed_from,',
'        ( select case when count(*) > 0 then count(*) end',
'            from wwv_flow_template_components',
'           where reference_id      = p.id',
'             and security_group_id = :WORKSPACE_ID',
'        ) as subscribers,',
'        0 is_default,',
'        current_app_theme_id theme_id,',
'        id template_id,',
'        security_group_id',
'    from wwv_theme_template_components p',
'   where p.current_app_theme_id is not null',
') x'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
