,p_item_plug_id=>wwv_flow_imp.id(178678919656730458)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Scheme Type'
,p_source=>'SCHEME_TYPE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'AUTHORIZATION TYPE'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select d,',
'       r',
'  from (',
'        select wwv_flow_lang.system_message(''AUTHORIZATION_NAME.''|| name_with_prefix) as d,',
'               name_with_prefix      as r',
'          from wwv_flow_native_plugins',
'         where plugin_type = ''AUTHORIZATION TYPE''',
'         union all',
'        select display_name || wwv_flow_lang.system_message(''PLUGIN.DISPLAY_NAME_POSTFIX'') as d,',
'               ''PLUGIN_'' || name     as r',
'          from wwv_flow_plugins',
'         where flow_id           = to_number(:FB_FLOW_ID)',
'           and security_group_id = to_number(:WORKSPACE_ID)',
'           and plugin_type       = ''AUTHORIZATION TYPE''',
'       )',
' order by 1'))
,p_lov_display_null=>'YES'
,p_lov_null_text=>'- Select a Scheme Type -'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(452656722938220607)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Select how this authorization scheme will be applied. The following built-in types are supported:</p>',
'<ul>',
'<li><strong>Exists SQL Query:</strong> A query that causes the authorization scheme to pass if it returns at least one row and causes the scheme to fail if it returns no rows</li>',
'<li><strong>NOT Exists SQL Query:</strong> A query that causes the authorization scheme to pass if it returns no rows and causes the scheme to fail if it returns one or more rows</li>',
'<li><strong>PL/SQL Function Returning Boolean:</strong> A PL/SQL function body that returns true or false. A false value causes the authorization scheme to fail. A true value causes it to pass.</li>',
'<li><strong>Item in Expression 1 is null:</strong> Value of item named in expression 1 is null.</li>',
'<li><strong>Item in Expression 1 is not null:</strong> Value of item named in expression 1 is not null.</li>',
'<li><strong>Value of Preference in Expression 1 Equals Expression 2:</strong> Value of preference named in expression 1 equals expression 2.</li>',
'<li><strong>Value of Preference in Expression 1 Does Not Equal Expression 2:</strong> Value of preference named in expression 1 does not equal expression 2.</li>',
'<li><strong>Value of Item in Expression 1 Equals Expression 2:</strong> Value of item named in expression 1 equals expression 2.</li>',
'<li><strong>Value of Item in Expression 1 Does NOT Equal Expression 2:</strong> Value of item named in expression 1 does not equal expression 2.</li>',
'<li><strong>Is In Role or Group:</strong> Checks the provided comma-separated roles/groups names against the user''s roles/groups for which the source is configured with the application security attribute <strong>Source for Role or Group Schemes</stro'
||'ng>.',
'<p>If the source is set to <em>Access Control User Role Assignments</em>, the authorization process will only consider the user''s granted ACL roles.</p>',
'<p>Otherwise, it will check if the groups are enabled as dynamic groups for the session (see APEX_AUTHORIZATION.ENABLE_DYNAMIC_GROUPS). If the application uses an Authentication scheme configured with Real Security Application (RAS) this check will i'
||'nclude RAS session roles. if Oracle APEX Accounts Authentication is used, this check also includes workspace groups that are granted to the user. If Database Authentication is used, this check also includes database roles that are granted to the user'
||'.</p>',
'<p>The authorization scheme succeed, If the user is granted any of the designated roles/groups.</p>',
'</li>',
'<li><strong>Is Not In Group:</strong> Group is not enabled or granted to the user. See <strong>Is In Group</strong> for details.</li>',
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
