,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select id,',
'       list_id,',
'       flow_id,',
'       list_item_display_sequence,',
'       list_item_link_text,',
'       list_item_link_target,',
'       wwv_flow_builder.get_formatted_target( list_item_link_target ) as formatted_target,',
'       list_item_current_type,',
'       list_item_current_for_pages,',
'       list_item_icon,',
'       list_text_01,',
'       list_text_02,',
'       list_text_03,',
'       list_text_04,',
'       list_text_05,',
'       list_text_06,',
'       list_text_07,',
'       list_text_08,',
'       list_text_09,',
'       list_text_10,',
'       list_text_11,',
'       list_text_12,',
'       parent_list_item_id,',
'       ( select l.list_item_link_text from wwv_flow_list_items l',
'          where l.list_id           = :F4000_P4050_LIST_ID',
'            and l.flow_id           = :FB_FLOW_ID',
'            and l.security_group_id = :WORKSPACE_ID',
'            and l.id                = p.parent_list_item_id ) as parent_list_item,',
'       item_displayed,',
'       security_scheme,',
'       required_patch,',
'       ( select nullif( count( c.id ), 0 )',
'           from wwv_flow_list_items c',
'          where list_id           = :F4000_P4050_LIST_ID',
'            and flow_id           = :FB_FLOW_ID',
'            and security_group_id = :WORKSPACE_ID',
'          start with c.parent_list_item_id = p.id',
'        connect by c.parent_list_item_id = prior c.id ) as child_item_count,',
'        --',
'       ( select case when count( c.id ) > 0 then ''U'' else ''UD'' end',
'           from wwv_flow_list_items c',
'          where list_id           = :F4000_P4050_LIST_ID',
'            and flow_id           = :FB_FLOW_ID',
'            and security_group_id = :WORKSPACE_ID',
'          start with c.parent_list_item_id = p.id',
'        connect by c.parent_list_item_id = prior c.id  ) as allowed_operations,',
'        --',
'       ( select hierarchy_level from (',
'             select id, level as hierarchy_level',
'               from (',
'                      select *',
'                        from wwv_flow_list_items',
'                       where list_id           = :F4000_P4050_LIST_ID',
'                         and flow_id           = :FB_FLOW_ID',
'                         and security_group_id = :WORKSPACE_ID',
'                    ) c',
