wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(622178476623944606)
,p_plug_name=>'History'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_region_attributes=>'style="width:100%"'
,p_plug_template=>wwv_flow_imp.id(29434107863295859)
,p_plug_display_sequence=>90
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'for c1 in (',
'    select last_updated_by,',
'           last_updated_on,',
'           created_by,',
'           created_on ',
'      from wwv_flow_lists',
'     where id                = :F4000_P4050_LIST_ID',
'       and security_group_id = :FLOW_SECURITY_GROUP_ID )',
'loop',
'    wwv_flow_4000_ui.show_history (',
'       p_last_updated_by => c1.last_updated_by,',
'       p_last_updated_on => c1.last_updated_on,',
'       p_created_by      => c1.created_by,',
'       p_created_on      => c1.created_on );',
