,p_plug_display_sequence=>30
,p_plug_new_grid_row=>false
,p_plug_new_grid_column=>false
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select id,',
'       list_id,',
'       flow_id,',
'       list_item_display_sequence,',
'       list_item_link_text,',
'       list_item_link_target,',
'       list_item_current_type,',
'       list_item_current_for_pages,',
'       list_item_icon,',
'       list_text_01,',
'       list_text_02,',
'       list_text_03,',
'       list_text_04,',
'       list_text_05,',
'       list_text_06,',
'       list_text_07,',
'       list_text_08,',
'       list_text_09,',
'       list_text_10,',
'       list_text_11,',
'       list_text_12,',
'       parent_list_item_id,',
'       list_item_icon_attributes,',
'       list_item_icon_alt_attribute,',
'       list_item_status,',
'       item_displayed,',
'       list_item_type,',
'       list_item_current_language,',
'       list_item_disp_cond_type,',
'       list_item_disp_condition,',
'       list_item_disp_condition2,',
'       security_scheme,',
'       required_patch,',
'       list_countclicks_y_n,',
'       list_countclicks_cat,',
'       translate_list_text_y_n,',
'       ( select nullif( count( c.id ), 0 )',
'           from wwv_flow_list_items c',
'          where list_id           = :P4051_LIST_ID',
'            and flow_id           = :FB_FLOW_ID',
'            and security_group_id = :WORKSPACE_ID',
'          start with c.parent_list_item_id = p.id',
'        connect by c.parent_list_item_id = prior c.id ) as child_item_count,',
'        --',
'       ( select case when count( c.id ) > 0 then ''U'' else ''UD'' end',
'           from wwv_flow_list_items c',
'          where list_id           = :P4051_LIST_ID',
'            and flow_id           = :FB_FLOW_ID',
'            and security_group_id = :WORKSPACE_ID',
'          start with c.parent_list_item_id = p.id',
'        connect by c.parent_list_item_id = prior c.id  ) as allowed_operations,',
'        --',
'       ( select hierarchy_level from (',
'             select id, level as hierarchy_level',
'               from (',
'                      select *',
'                        from wwv_flow_list_items',
'                       where list_id           = :P4051_LIST_ID',
'                         and flow_id           = :FB_FLOW_ID',
'                         and security_group_id = :WORKSPACE_ID',
'                    ) c',
'              start with c.parent_list_item_id is null',
'            connect by c.parent_list_item_id = prior c.id  ) where id = p.id ) as this_level,',
'       decode(list_item_disp_cond_type,null,null,''Y'') conditional,',
'       last_updated_on,',
'       last_updated_by',
'  from wwv_flow_list_items p',
' where list_id           = :P4051_LIST_ID',
'   and flow_id           = :FB_FLOW_ID',
'   and security_group_id = :WORKSPACE_ID'))
