,p_plug_display_column=>1
,p_plug_display_point=>'REGION_POSITION_03'
,p_plug_item_display_point=>'BELOW'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>You manage authorization for applications, pages, and most other components using Authorization Schemes.</p>',
'<p>You associate an Authorization Scheme with an application, page, or other component on the component''s attributes page.</p>',
'<p>Authorization Schemes are pass/fail checks.  Common Authorization Scheme types include Exists, Not Exists SQL Queries, and PL/SQL Function Returning Boolean.</p>',
'<p>To enhance performance, the success or failure of an Authorization Scheme is cached on a per session or per page view basis.</p>',
'<p><a target="_blank" href="&SYSTEM_HELP_URL.">Learn More ...</a></p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
