'    p_columns_clause         => :P4080_PQL_COLUMNS_CLAUSE,    ',
'    p_return_column          => :P4081_RETURN_COLUMN,',
'    p_display_column         => :P4081_DISPLAY_COLUMN',
');'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(8966537405715516)
,p_internal_uid=>21190462109691831
);
