wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3727517093871356)
,p_plug_name=>'Application Items'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(646287526247383209)
,p_plug_display_sequence=>30
,p_plug_new_grid_row=>false
,p_plug_new_grid_column=>false
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select i.id,',
'       i.name,',
'       i.scope,',
'       ''icon-sc-app-item'' icon,',
'       replace(i.name,''_'','' '') alt,',
'       wwv_flow_page_api.get_url(',
'           p_page        => 4303,',
'           p_clear_cache => 4303,',
'           p_items       => ''F4000_P4303_ID'',',
'           p_values      => i.id ) link,',
'       wwv_flow_computation.get_computation_points( :FB_FLOW_ID, i.name ) as comps,',
'       ( select count(*)',
'           from wwv_flow_computations',
'          where security_group_id = :FLOW_SECURITY_GROUP_ID',
'            and flow_id           = :FB_FLOW_ID',
'            and i.name            = computation_item ) application_computations,',
'       ( select count(*)',
'           from wwv_flow_step_computations',
'          where security_group_id = :FLOW_SECURITY_GROUP_ID',
'            and flow_id           = :FB_FLOW_ID',
'            and i.name            = computation_item ) page_computations,',
'       ( select count(*)',
'           from wwv_flow_processing',
'          where security_group_id = :FLOW_SECURITY_GROUP_ID',
'            and flow_id           = :FB_FLOW_ID',
'            and instr( upper( sys.dbms_lob.substr(',
'                    process_sql_clob, 4000, 1 ) ), '':'' || upper( i.name ) ) > 0 ) application_processes,',
'       ( select count(*)',
'           from wwv_flow_step_processing',
'          where security_group_id = :FLOW_SECURITY_GROUP_ID',
'            and flow_id           = :FB_FLOW_ID',
'            and instr( upper( sys.dbms_lob.substr(',
'                    process_sql_clob, 4000, 1 ) ), '':'' || upper( i.name ) ) > 0 ) page_processes,',
'       nvl( i.last_updated_by, i.created_by ) last_updated_by,',
'       nvl( i.last_updated_on, i.created_on ) last_updated,',
'       i.protection_level,',
'       i.escape_on_http_output,',
'       --',
'       case when i.reference_id is not null then',
'           coalesce ( to_char( master.flow_id ),',
'                       wwv_flow_lang_dev.builder_message( ''SUBSCRIBED_FROM.NONEXISTING_MASTER'' ) )',
'       end as subscribed_from,',
'       ( select case when count(*) > 0 then count(*) end',
'           from wwv_flow_items sub',
'          where sub.reference_id      = i.id',
'            and sub.security_group_id = :FLOW_SECURITY_GROUP_ID',
'       ) as subscribers,',
'       case when i.reference_id is not null then',
'           case',
'               when master.version_scn = i.version_scn then',
'                   wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_UP_TO_DATE'')',
'               when master.version_scn != i.version_scn then',
'                   wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_NEEDS_REFRESH'')',
'               else',
'                   wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_UNKNOWN'')',
'           end',
'       end subscription_status,',
'       --',
'       null as actions',
'  from wwv_flow_items i,',
'       wwv_flow_items master',
' where i.flow_id           = :FB_FLOW_ID',
'   and i.security_group_id = :FLOW_SECURITY_GROUP_ID',
'   and i.reference_id      = master.id (+)',
'   and i.security_group_id = master.security_group_id (+)'))
,p_plug_source_type=>'NATIVE_IR'
,p_plug_query_show_nulls_as=>' - '
,p_pagination_display_position=>'BOTTOM_RIGHT'
);
