wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(47836101365827708)
,p_plug_name=>'Application Computations'
,p_region_template_options=>'#DEFAULT#:a-IRR-region--responsiveIconView'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(646287526247383209)
,p_plug_display_sequence=>30
,p_plug_new_grid_row=>false
,p_plug_new_grid_column=>false
,p_plug_item_display_point=>'BELOW'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select c.computation_sequence,',
'       c.computation_point a,',
'       c.computation_item,',
'       c.computation_type b,',
'       ( select p.patch_name',
'           from wwv_flow_patches p',
'          where p.id = c.required_patch',
'            and p.security_group_id = c.security_group_id',
'         union all',
'         select ''{''||wwv_flow_lang.system_message(''NOT_W_ARGUMENT'',patch_name)|| ''} ''',
'                patch_name',
'           from wwv_flow_patches p',
'          where 0-p.id = c.required_patch',
'            and p.security_group_id = c.security_group_id ) as required_patch,',
'       c.compute_when,',
'       substr( c.computation, 1, 100 ) computation,',
'       c.id,',
'       ''icon-sc-app-computation'' icon,',
'       wwv_flow_page_api.get_url(',
'           p_page        => 4304,',
'           p_clear_cache => 4304,',
'           p_items       => ''F4000_P4304_ID'',',
'           p_values      => c.id ) link,',
'       nvl( c.last_updated_by, c.created_by ) last_updated_by,',
'       nvl( c.last_updated_on, c.created_on ) last_updated_on,',
'       --',
'       case when c.reference_id is not null then',
'           coalesce ( to_char( master.flow_id ),',
'                       wwv_flow_lang_dev.builder_message( ''SUBSCRIBED_FROM.NONEXISTING_MASTER'' ) )',
'       end as subscribed_from,',
'       ( select case when count(*) > 0 then count(*) end',
'           from wwv_flow_computations sub',
'          where sub.reference_id      = c.id',
'            and sub.security_group_id = :FLOW_SECURITY_GROUP_ID',
'       ) as subscribers,',
'       case when c.reference_id is not null then',
'           case',
'               when master.version_scn = c.version_scn then',
'                   wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_UP_TO_DATE'')',
'               when master.version_scn != c.version_scn then',
'                   wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_NEEDS_REFRESH'')',
'               else',
'                   wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_UNKNOWN'')',
'           end',
'       end subscription_status,',
'       --',
'       null as actions',
'  from wwv_flow_computations c,',
'       wwv_flow_computations master',
' where c.flow_id           = :FB_FLOW_ID',
'   and c.security_group_id = :FLOW_SECURITY_GROUP_ID',
'   and c.reference_id      = master.id (+)',
'   and c.security_group_id = master.security_group_id (+)'))
,p_plug_source_type=>'NATIVE_IR'
,p_plug_query_show_nulls_as=>' - '
,p_pagination_display_position=>'BOTTOM_RIGHT'
);
