wwv_flow_imp_page.create_page_computation(
 p_id=>wwv_flow_imp.id(23201774898325542)
,p_computation_sequence=>5
,p_computation_item=>'P4111_SOURCE_TYPE_HIDDEN'
,p_computation_type=>'FUNCTION_BODY'
,p_computation_language=>'PLSQL'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'if coalesce(:P4111_LOCATION,''LOCAL'') = ''LOCAL'' then',
'    if (:P4111_SOURCE_TYPE_HIDDEN in (''TABLE'',''SQL'',''FUNC_BODY_RETURNING_SQL'', ''GRAPH'')) then',
'        return :P4111_SOURCE_TYPE;',
'    else',
'        return :P4111_SOURCE_TYPE_HIDDEN;     -- for legacy P4111_SOURCE_TYPE is not displayed, ',
'                                              -- so just set back to itself.    ',
'    end if;',
'elsif :P4111_LOCATION = ''REMOTE'' then',
'    return :P4111_REMOTE_SOURCE_TYPE;',
'end if;'))
);
wwv_flow_imp_page.create_page_computation(
 p_id=>wwv_flow_imp.id(2009999197771027)
,p_computation_sequence=>10
,p_computation_item=>'P4111_DOCUMENT_SOURCE_HIDDEN'
,p_computation_type=>'EXPRESSION'
,p_computation_language=>'PLSQL'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'case coalesce(:P4111_LOCATION,''LOCAL'') ',
'    when ''DUALITY_VIEW''    then :P4111_DUALITY_VIEW_ID',
'    when ''JSON_COLLECTION'' then :P4111_JSON_SOURCE_ID',
'end'))
);
wwv_flow_imp_page.create_page_computation(
 p_id=>wwv_flow_imp.id(2320291263209548)
,p_computation_sequence=>15
,p_computation_item=>'P4111_FUNC_BODY_LANG_HIDDEN'
,p_computation_type=>'EXPRESSION'
,p_computation_language=>'PLSQL'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'case coalesce(:P4111_LOCATION,''LOCAL'')',
'    when ''LOCAL'' then',
'        case when :P4111_SOURCE_TYPE           = ''FUNC_BODY_RETURNING_SQL'' then :P4111_LOV_QUERY_FUNC_LANG end',
'    when ''WEB_SOURCE'' then ',
'        case when :P4111_SOURCE_POST_PROC_TYPE = ''FUNC_BODY_RETURNING_SQL'' then :P4111_SRC_POST_PROC_FUNC_LANG end    ',
'    when ''DUALITY_VIEW'' then',
'        case when :P4111_DVPOST_TYPE           = ''FUNC_BODY_RETURNING_SQL'' then :P4111_DVPOST_FUNC_LANG end    ',
'    when ''JSON_COLLECTION'' then',
'        case when :P4111_JSPOST_TYPE           = ''FUNC_BODY_RETURNING_SQL'' then :P4111_JSPOST_FUNC_LANG end',
'end',
''))
);
wwv_flow_imp_page.create_page_computation(
 p_id=>wwv_flow_imp.id(9496916949275717)
,p_computation_sequence=>25
,p_computation_item=>'P4111_LOV_QUERY_HIDDEN'
,p_computation_type=>'EXPRESSION'
,p_computation_language=>'PLSQL'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'case coalesce(:P4111_LOCATION,''LOCAL'')',
'    when ''LOCAL'' then',
'        case when :P4111_SOURCE_TYPE_HIDDEN in (''SQL'',''LEGACY_SQL'') ',
'             then :P4111_LOV_QUERY_SQL',
'             when :P4111_SOURCE_TYPE_HIDDEN = ''FUNC_BODY_RETURNING_SQL''',
'             then :P4111_LOV_QUERY_FUNC_BODY',
'        end',
'',
'    when ''REMOTE'' then',
'        :P4111_REMOTE_SQL',
'    when ''WEB_SOURCE'' then',
'        case :P4111_SOURCE_POST_PROC_TYPE',
'            when ''FUNC_BODY_RETURNING_SQL'' then :P4111_SRC_POST_PROC_FUNC_BODY',
'            when ''SQL''                     then :P4111_SOURCE_POST_PROC_SQL',
'        end',
'    when ''DUALITY_VIEW'' then',
'        case :P4111_DVPOST_TYPE',
'            when ''FUNC_BODY_RETURNING_SQL'' then :P4111_DVPOST_FUNC_BODY',
'            when ''SQL''                     then :P4111_DVPOST_SQL',
'        end',
'    when ''JSON_COLLECTION'' then',
'        case :P4111_JSPOST_TYPE',
'            when ''FUNC_BODY_RETURNING_SQL'' then :P4111_JSPOST_FUNC_BODY',
'            when ''SQL''                     then :P4111_JSPOST_SQL',
'        end',
'end',
''))
);
