,p_process_sequence=>130
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Sync REST Data Source Parameters'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    if :P4111_USE_LOCAL_TABLE = ''Y'' and coalesce( :P4111_OLD_USE_LOCAL_TABLE, ''N'' ) = ''N'' then',
'        --',
'        -- use local sync table was enabled and it was disabled before. So we have to delete all ',
'        -- component parameters; as data comes directly from the sync table.',
'        --',
'        delete wwv_flow_web_src_comp_params',
'         where security_group_id = :FLOW_SECURITY_GROUP_ID',
'           and flow_id           = :FB_FLOW_ID',
'           and shared_lov_id     = :F4000_P4111_ID;',
'',
'    elsif coalesce( :P4111_USE_LOCAL_TABLE, ''N'' ) = ''N'' and :P4111_OLD_USE_LOCAL_TABLE = ''Y'' then',
'        --',
'        -- use local sync table was disabled and it was enabled before. An LOV invocation',
'        -- must perform a REST call, so we need to initialize REST source component parameters.',
'        --',
'        wwv_flow_web_src_dev.add_web_source_params(',
'            p_flow_id              => :FB_FLOW_ID,',
'            p_web_source_module_id => :P4111_WEB_SRC_MODULE_ID,',
'            p_array_column_id      => :P4111_WEB_SRC_ARRAY_COL_ID,',
'            p_database_operation   => wwv_flow_plugin_api.c_db_operation_fetch_rows,',
'            p_shared_lov_id        => :F4000_P4111_ID );',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(292985826)
,p_process_when=>'P4111_WEB_SRC_MODULE_ID'
,p_process_when_type=>'ITEM_IS_NOT_NULL'
,p_internal_uid=>1663630736963720
);
