wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(17314311266994460)
,p_name=>'P4303_PROTECTION_LEVEL'
,p_source_data_type=>'VARCHAR2'
,p_item_sequence=>50
,p_item_plug_id=>wwv_flow_imp.id(17312310527965891)
,p_item_source_plug_id=>wwv_flow_imp.id(454431825)
,p_item_default=>'I'
,p_prompt=>'Session State Protection'
,p_source=>'PROTECTION_LEVEL'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'ITEM PROTECTION LEVEL D'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'for c1 in (select nvl(PAGE_PROTECTION_ENABLED_Y_N,''N'') p from wwv_flows where id = :FB_FLOW_ID) loop',
'    if c1.p = ''Y'' then',
'       return  ''select wwv_flow_lang.system_message(''''UNRESTRICTED'''') d, ''''N'''' r',
'                  from sys.dual union all',
'                select wwv_flow_lang.system_message(''''CHECKSUM_REQUIRED_APPLICATION'''') d, ''''B'''' r',
'                  from sys.dual union all',
'                select wwv_flow_lang.system_message(''''CHECKSUM_REQUIRED_USER'''') d, ''''P'''' r',
'                  from sys.dual union all               ',
'                select wwv_flow_lang.system_message(''''CHECKSUM_REQUIRED_SESSION'''') d, ''''S'''' r',
'                  from sys.dual union all               ',
'                select wwv_flow_lang.system_message(''''RESTRICTED_NO_SET_FROM_BROWSER'''') d, ''''I'''' r',
'                  from sys.dual'';',
'    else',
'       return  ''select wwv_flow_lang.system_message(''''UNRESTRICTED'''') d, ''''N'''' r',
'                  from sys.dual union all ',
'                select wwv_flow_lang.system_message(''''RESTRICTED_NO_SET_FROM_BROWSER'''') d, ''''I'''' r',
'                  from sys.dual'';',
'    end if;',
'end loop;'))
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_lov_display_extra=>'NO'
,p_escape_on_http_input=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Select Session State Protection for this item:',
'<ul>',
'<li><strong>Unrestricted</strong> - The item may be set by passing the item name/value in a URL or in a form. No checksum is required in the URL.</li><br />       ',
'<li><strong>Restricted - May not be set from browser</strong> - The item may not be altered using the URL or POSTDATA. Use this option when you want to restrict the way that the item value can be set to internal processes, computations, and so on. Th'
||'is attribute is only applicable only to items that cannot be used as data entry items and is always observed even if Session State Protection is disabled. This attribute may be used for application items or for page items with any of these "Display A'
||'s" types:',
'<br />',
'<ul>',
'<li>Display Only (Save State=No)</li>',
'<li>Text Field (Disabled, does not save state)</li>                          ',
'<li>Stop and Start Grid Layout (Displays label only)</li>',
'</li></ul>',
'<li><strong>Checksum Required: Application Level</strong> - The item may be set by passing the item name/value in a URL if a checksum is also provided that is specific to the workspace and application. Use this option when you want to allow the item '
||'to be set only by URLs having checksums that were generated by any user running the same application in the current workspace but in a different session.</li>',
'<li><strong>Checksum Required: User Level</strong> - The item may be set by passing the item name/value in a URL if a checksum is also provided that is specific to the workspace, application, and user. Use this option when you want to allow the item '
||'to be set only by URLs having checksums that were generated by the same named user, running the same application in the current workspace but in a different session.</li>      ',
'<li><strong>Checksum Required: Session Level</strong> - The item may be set by passing the item name/value in a URL if a checksum is also provided that is specific to the current session. Use this option when you want to allow this item to be set onl'
||'y by URLs having checksums that were generated in the current session.</li>',
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
