,p_item_template_options=>'#DEFAULT#:a-Form-fieldContainer--stretch'
,p_escape_on_http_input=>'Y'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Enter Cascading Style Sheet file URLs to be loaded for this page template. Each URL has to be written into a new line. If you provide a minified version of your file you can use the substitution string <code>#MIN#</code> to include <code>.min</cod'
||'e> or <code>#MIN_DIRECTORY#</code> to include <code>minified/</code> in your file URL for a regular page view and an empty string if the page is viewed in debug mode. You also have access to the substitution string <code>#APP_VERSION#</code> if you w'
||'ant to include the application''s version in the file URL.</p>',
'',
'<p>File URLs you enter here will replace the <code>#TEMPLATE_CSS#</code> substitution string in the template.</p>',
'',
'<p>Note: You do not need to include opening or closing <code>link</code> tags. Just include the file URL.</p>',
'',
'<p>',
'Examples:',
'<ul>',
'  <li>Standard file reference',
'      <pre>/mycss/main.css</pre>',
'  </li>',
'  <li>Standard file reference which loads the minified file main.min.css from /mycss/minified/ for regular page views and main.css from /mycss/ in debug mode.',
'      <pre>/mycss/#MIN_DIRECTORY#main#MIN#.css</pre>',
'  </li>',
'  <li>Conditional media query',
'      <pre>[media="only screen and (max-device-width: 480px)"]/mycss/smartphone.css</pre>',
'  </li>',
'  <li>File reference using a query string in the URL referencing the application version, such that when the application is upgraded (and the version is incremented), the browser will be instructed to always load the new file and ignore any previousl'
||'y cached files.',
'      <pre>/mycss/main.css?version=#APP_VERSION#</pre>',
'  </li>',
'</ul>',
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'auto_height', 'Y',
  'character_counter', 'N',
  'resizable', 'Y',
  'trim_spaces', 'NONE')).to_clob
);
