,p_name=>'P4307_GRID_TEMPLATE'
,p_item_sequence=>400
,p_item_plug_id=>wwv_flow_imp.id(131914703603)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Container Template'
,p_source=>'GRID_TEMPLATE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'PLUGIN_COM.ORACLE.APEX.CODE_EDITOR'
,p_cSize=>90
,p_cMaxlength=>4000
,p_cHeight=>15
,p_tag_attributes=>'onchange="htmldb_item_change(this)"'
,p_field_template=>wwv_flow_imp.id(561549716994252345)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Specifies the markup to start a new layout. You must include at least #ROWS# in this template. The following substitution strings are allowed in the container template:</p>',
'<ul>',
'<li><strong>#USED_COLUMNS_NUMBER#</strong> - Number of used columns. For example: 1, 2, 3, ...</li>',
'<li><strong>#USED_COLUMNS_ALPHA#</strong> - Alphabet character representing the number of used columns. For example: a, b, c, ...</li>',
'<li><strong>#USED_COLUMNS_ALPHA_MINUS#</strong> - Alphabet character representing the number of used columns which are reduced by one column. For example: Two columns will return "a".</li>',
'<li><strong>#USED_COLUMNS_WORD#</strong> - Word representing the number of used columns. For example: one, two, three, ...</li>',
'<li><strong>#USED_COLUMNS_PLURAL#</strong> - Gets substituted by "s" if the number of columns is bigger than one. Use it if the layout requires a class name "column" for a single column and "columns" if multiple columns are specified. For example: cl'
||'ass="#USED_COLUMNS_WORD# column#USED_COLUMNS_PLURAL#"</li>',
'<li><strong>#ROWS#</strong> - Substituted by the "Row Template".</li>',
'</ul>',
'<p>',
'Example:',
'<pre>',
'&lt;div class="ui-grid-#USED_COLUMNS_ALPHA_MINUS#"&gt;#ROWS#&lt;/div&gt;',
'</pre>',
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'HTMLMIXED',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
);
