wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(203353124660580498)
,p_name=>'P4307_GRID_COLUMN_TEMPLATE'
,p_item_sequence=>420
,p_item_plug_id=>wwv_flow_imp.id(131914703603)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Column Template'
,p_source=>'GRID_COLUMN_TEMPLATE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'PLUGIN_COM.ORACLE.APEX.CODE_EDITOR'
,p_cSize=>90
,p_cMaxlength=>4000
,p_cHeight=>15
,p_tag_attributes=>'onchange="htmldb_item_change(this)"'
,p_field_template=>wwv_flow_imp.id(561549716994252345)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Specifies the markup to start a new layout column. You must include at least #CONTENT# in this template. The following substitution strings are allowed in the column template:</p>',
'<ul>',
'<li><strong>#COLUMN_NUMBER#</strong> - Number of the column. For example: 1, 2, 3, ...</li>',
'<li><strong>#COLUMN_ALPHA#</strong> - Alphabet character representing the column. For example: a, b, c, ...</li>',
'<li><strong>#COLUMN_WORD#</strong> - Word representing the column. For example: one, two, three, ...</li>',
'<li><strong>#COLUMN_PLURAL#</strong> - Gets substituted by "s" if the column is bigger than one. Use it if the layout requires a class name "column" for the first column and "columns" for the following columns. For example: class="#COLUMN_WORD# colum'
||'n#COLUMN_PLURAL#"</li>',
'<li><strong>#COLUMN_SPAN_NUMBER#</strong> - Number of the column span. For example: 1, 2, 3, ...</li>',
'<li><strong>#COLUMN_SPAN_ALPHA#</strong> - Alphabet character representing the column span. For example: a, b, c, ...</li>',
'<li><strong>#COLUMN_SPAN_WORD#</strong> - Word representing the column span. For example: one, two, three, ...</li>',
'<li><strong>#COLUMN_SPAN_PLURAL#</strong> - Gets substituted by "s" if the column span is bigger than one. Use it if the layout requires a class name "column" for a single column span and "columns" if multiple columns are specified. For example: clas'
||'s="#COLUMN_SPAN_WORD# column#COLUMN_SPAN_PLURAL#"</li>',
'<li><strong>#CSS_CLASSES#</strong> - Substituted by the value specified as "Column CSS Classes". This allows to further customize a column with CSS classes.</li>',
'<li><strong>#ATTRIBUTES#</strong> - Substituted by the value specified as "Column Attributes". This allows to further customize a column.</li>',
'<li><strong>#FIRST_LAST_COLUMN_ATTRIBUTES#</strong> - Substituted by the value specified in "First Column Attributes" and "Last Column Attributes" depending if it''s the first or last column.</li>',
'<li><strong>#CONTENT#</strong> - Substituted by the regions, page items or buttons displayed in the column.</li>',
'</ul>',
'<p>',
'Example:',
'<pre>',
'&lt;div class="#COLUMN_SPAN_WORD# column#COLUMN_SPAN_PLURAL# #CSS_CLASSES#"&gt;#CONTENT#&lt;/div&gt;',
'</pre>',
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'HTMLMIXED',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
);
