wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(864568260573731002)
,p_name=>'P4307_DIALOG_BROWSER_FRAME'
,p_item_sequence=>1350
,p_item_plug_id=>wwv_flow_imp.id(53603513531407414)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Allow Embed In Frame'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare ',
'   l_value wwv_flow_global.vc_arr2;',
'begin ',
'   select dialog_browser_frame ',
'   bulk collect into l_value ',
'   from wwv_flow_templates ',
'   where id = :F4000_P4307_ID',
'   and security_group_id in ( :WORKSPACE_ID, 11, 12 );',
'',
'   return wwv_flow_utilities.table_to_string2(l_value,'':''); ',
'end;'))
,p_source_type=>'FUNCTION_BODY'
,p_source_language=>'PLSQL'
,p_display_as=>'NATIVE_CHECKBOX'
,p_named_lov=>'DIALOG_PAGE_MODE_OPTIONS'
,p_lov=>'.'||wwv_flow_imp.id(887851591470130537)||'.'
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'Your page template level browser frame options are listed below, along with the current setting for each.',
'Check the box next to a page mode to use this attribute to control if the browser is allowed to display your application''s pages within a frame.',
'The current setting will be the default for each modal and non-modal dialog using this page template.',
'<p/>',
'<p>',
'Displaying pages within frames can be misused with "clickjacking" attacks.',
'In a clickjacking attack the attacker uses multiple layers to trick a user into clicking a button or link on another page when they were intending to click on the top level page.',
'Thus, the attacker is hijacking clicks (or keystrokes) meant for their page and routing them to another page.',
'<p/>',
'<p>',
'&PRODUCT_NAME. embeds modal dialogs in iframes.',
'If you set the application security attribute <em>Browser Frame</em> to "Deny",',
'checking <em>Allow Embed In Frame</em> for "Modal Dialog" will instead use "Allow from same origin" for dialog pages that use this template. ',
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'number_of_columns', '1')).to_clob
,p_multi_value_type=>'SEPARATED'
,p_multi_value_separator=>':'
);
