wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(116593057307910565)
,p_validation_name=>'unique template name'
,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with central_theme as (',
'    select wwv_flow_theme_manager.get_central_application_id( :FB_FLOW_ID, :P4307_THEME ) as application_id,',
'           wwv_flow_theme_manager.get_central_theme_id( :FB_FLOW_ID, :P4307_THEME )       as theme_id,',
'           wwv_flow_theme_manager.get_central_workspace_id( :FB_FLOW_ID, :P4307_THEME )   as workspace_id',
'      from sys.dual',
')',
'',
'select 1',
'  from wwv_flow_templates t,',
'       central_theme ct',
' where ( t.flow_id, t.theme_id, t.security_group_id ) in',
'       (',
'        ( :FB_FLOW_ID, :P4307_THEME, :WORKSPACE_ID ),',
'        ( ct.application_id, ct.theme_id, ct.workspace_id )',
'       )',
'   and t.name = :F4000_P4307_NAME',
'   and t.id  != :F4000_P4307_ID'))
,p_validation_type=>'NOT_EXISTS'
,p_error_message=>'Template name must be unique'
,p_associated_item=>wwv_flow_imp.id(22011144003)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
