wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(64149671474)
,p_name=>'F4000_P4318_DISPLAY_CONDITION_TYPE'
,p_item_sequence=>16
,p_item_plug_id=>wwv_flow_imp.id(469888520)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Tab Display Condition'
,p_source=>'DISPLAY_CONDITION_TYPE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'PLUGIN_COM.ORACLE.APEX.CONDITION_LIST'
,p_named_lov=>'STANDARD_CONDITION_TYPES'
,p_lov=>'.'||wwv_flow_imp.id(13602414170805697)||'.'
,p_lov_display_null=>'YES'
,p_lov_null_text=>'- Tab Not Conditional -'
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'YES'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<P>Select one of the predefined conditions if you want this tab displayed only in certain situations:</P>',
'',
'<UL>',
'',
'<LI>CURRENT_PAGE_NOT_EQUALS_CONDITION: tab will be displayed only if the current page is not the page specified in the Display Condition field.</LI>',
'',
'<LI>CURRENT_PAGE_EQUALS_CONDITION: tab will be displayed only if the current page is the page specified in the Display Condition field.</LI>',
'',
'<LI>CURRENT_PAGE_NOT_IN_CONDITION: tab will be displayed only if the current page is not in the list of pages specified in the Display Condition field (comma-separated list of pages).</LI>',
'',
'<LI>CURRENT_PAGE_IN_CONDITION: tab will be displayed only if the current page is in the list of pages specified in the Display Condition field (comma-separated list of pages).</LI>',
'',
'<LI>USER_IS_NOT_PUBLIC_USER: tab will be displayed only&nbsp;if the current user is not the public user. No entry required in the Display Condition field.</LI>',
'',
'<LI>USER_IS_PUBLIC_USER: tab will be displayed only&nbsp;if the current user is the public user. No entry required in the Display Condition field.</LI>',
'',
'<LI>EXISTS: tab will be displayed only if the query in the Display Condition field returns at least one row.</LI>',
'',
'<LI>ITEM_IS_NOT_NULL: tab will be displayed only if item identified in the Display Condition field is not null.</LI>',
'',
'<LI>ITEM_IS_NULL:&nbsp; tab will be displayed only if item identified in the Display Condition field is null.</LI>',
'',
'<LI>NOT_EXISTS: tab will be displayed only if the query in the Display Condition field returns no rows.</LI>',
'',
'<LI>PLSQL_EXPRESSION: tab will be displayed only if the PL/SQL expression in the Display Condition field evaluates to true.</LI>',
'',
'<LI>SQL_EXPRESSION: tab will be displayed only if the SQL expression in the Display Condition field evaluates to true.</LI></UL>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'F4000_P4318_DISPLAY_CONDITION',
  'attribute_02', 'F4000_P4318_DISPLAY_CONDITION2',
  'attribute_04', 'F4000_P4318_DISPLAY_CONDITION_CHECK',
  'attribute_06', 'CONDITION',
  'attribute_07', 'F4000_P4318_DISPLAY_CONDITION_LANG')).to_clob
);
