'    select ( select wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_UP_TO_DATE'') from sys.dual ) up_to_date,',
'           ( select wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_NEEDS_REFRESH'') from sys.dual ) needs_refresh,',
'           ( select wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_UNKNOWN'') from sys.dual ) unknown_status,',
'           ( select wwv_flow_lang_dev.builder_message(''SUBSCRIBED_FROM.NONEXISTING_MASTER'') from sys.dual ) no_master',
'      from sys.dual )',
'select p.id, ',
'       p.name,',
'       p.display_name,',
'       p.plugin_type,',
'       ( select count(*)',
'           from wwv_flow_step_items',
'          where flow_id       = p.flow_id',
'            and display_as    = ''PLUGIN_''||p.name',
'            and p.plugin_type = ''ITEM TYPE''',
'       ) +',
'       ( select count(*)',
'           from wwv_flow_region_columns',
'          where flow_id       = p.flow_id',
'            and item_type     = ''PLUGIN_''||p.name',
'            and p.plugin_type = ''ITEM TYPE''',
'       ) +',
'       ( select count(*)',
'           from wwv_flow_page_plugs',
'          where flow_id          = p.flow_id',
'            and plug_source_type = ''PLUGIN_''||p.name',
'            and p.plugin_type    = ''REGION TYPE''',
'       ) +',
'       ( select count(*)',
'           from wwv_flow_page_plugs',
'          where flow_id          = p.flow_id',
'            and plug_source_type = ''TMPL_''||p.name',
'            and p.plugin_type    = ''TEMPLATE COMPONENT''',
'       ) +',
'       ( select count(*)',
'           from wwv_flow_region_report_column',
'          where flow_id       = p.flow_id',
'            and display_as    = ''PLUGIN_''||p.name',
'            and p.plugin_type = ''REPORT COLUMN TYPE''',
'       ) +',
'       ( select count(*)',
'           from wwv_flow_processing',
'          where flow_id       = p.flow_id',
'            and process_type  = ''PLUGIN_''||p.name',
'            and p.plugin_type = ''PROCESS TYPE''',
'       ) +',
'       ( select count(*)',
'           from wwv_flow_step_processing',
'          where flow_id       = p.flow_id',
'            and process_type  = ''PLUGIN_''||p.name',
'            and p.plugin_type = ''PROCESS TYPE''',
'       ) +',
'       ( select count(*)',
'           from wwv_flow_page_da_events  e,',
'                wwv_flow_page_da_actions a',
'          where e.flow_id     = p.flow_id',
'            and a.event_id    = e.id',
'            and a.action      = ''PLUGIN_''||p.name',
'            and p.plugin_type = ''DYNAMIC ACTION''',
'       ) +',
'       ( select count(*)',
'           from wwv_flow_security_schemes',
'          where flow_id       = p.flow_id',
'            and scheme_type   = ''PLUGIN_''||p.name',
'            and p.plugin_type = ''AUTHORIZATION TYPE''',
'       ) +',
'       ( select count(*)',
'           from wwv_flow_web_src_modules',
'          where flow_id         = p.flow_id',
'            and web_source_type = ''PLUGIN_''||p.name',
'            and p.plugin_type   = ''WEB SOURCE TYPE''',
'       ) +       ',
'       ( select count(*)',
'           from wwv_flow_authentications',
'          where flow_id       = p.flow_id',
'            and scheme_type   = ''PLUGIN_''||p.name',
'            and p.plugin_type = ''AUTHENTICATION TYPE''',
'       ) +',
'       ( select count(*)',
'           from wwv_flow_worksheet_columns',
'          where flow_id         = p.flow_id',
'            and display_text_as = ''TMPL_''||p.name',
'            and p.plugin_type   = ''TEMPLATE COMPONENT''',
'       ) as ref,',
'       --',
'       case when p.reference_id is not null then',
'           coalesce ( to_char( master.flow_id ),',
'                       messages.no_master )',
'       end as subscribed_from,',
'       ( select case when count(*) > 0 then count(*) end',
'           from wwv_flow_plugins sub',
'          where sub.reference_id      = p.id',
'            and sub.security_group_id = :WORKSPACE_ID ) as subscribers,',
'       case when p.reference_id is not null then',
'           case',
'               when master.version_scn = p.version_scn then',
'                   messages.up_to_date',
'               when master.version_scn != p.version_scn then',
'                   messages.needs_refresh',
'               else',
'                   messages.unknown_status',
'           end',
'       end subscription_status,',
'       --',
'       p.version_identifier,',
'       p.about_url,',
'       p.plugin_comment,',
'       p.help_text,',
'       --',
'       coalesce( p.last_updated_on, p.created_on ) last_updated,',
'       coalesce( p.last_updated_by, p.created_by ) last_updated_by,',
'       --',
'       ''icon-sc-plugin'' as icon_class,',
'       p.display_name                             as icon_title,',
'       ''f?p=4000:4410:''||:app_session||''::NO:4410:P4410_ID:''||p.id as edit_link',
'  from wwv_flow_plugins p,',
'       wwv_flow_plugins master,',
'       messages',
' where p.flow_id           = :FB_FLOW_ID',
'   and p.security_group_id = :WORKSPACE_ID',
'   and p.reference_id           = master.id (+)',
'   and p.security_group_id      = master.security_group_id (+)',
'   and p.theme_id is null'))
,p_plug_source_type=>'NATIVE_IR'
,p_plug_query_show_nulls_as=>' - '
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_prn_output_show_link=>'Y'
