wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(5830766728948627)
,p_validation_name=>'Name is unique'
,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with central_theme as (',
'    select wwv_flow_theme_manager.get_central_application_id( :FB_FLOW_ID ) as application_id,',
'           wwv_flow_theme_manager.get_central_workspace_id( :FB_FLOW_ID )   as workspace_id',
'      from sys.dual',
')',
'',
'select 1',
'  from wwv_flow_plugins p,',
'       central_theme ct',
' where ( p.flow_id, p.security_group_id ) in',
'       (',
'         ( :FB_FLOW_ID, :WORKSPACE_ID ),',
'         ( ct.application_id, ct.workspace_id )',
'       )',
