wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3053446993523770)
,p_plug_name=>'Help - Slots'
,p_region_template_options=>'#DEFAULT#:js-dialog-size720x480'
,p_plug_template=>wwv_flow_imp.id(557449278618308550)
,p_plug_display_sequence=>220
,p_plug_display_point=>'REGION_POSITION_05'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ul>',
'    <li>If the template component is used in a region, displayed as a partial, then &PRODUCT_NAME. will only render slots inside the partial template. Side effects are that it cannot be refreshed dynamically and cannot be lazy loaded.</li>',
'    <li>If the template component is used in a region, displayed as a report, then &PRODUCT_NAME. will only render slots inside the report container template. The report container template is surrounding the report body template.</li>',
'    <li>It is not possible to render slots in the report rows or interactive report columns, as slot content is not designed to be repeatable on page rendering.</li>',
'    <li>It''s possible to check for the existence of slot content, such that we can render additional markup only if the slot is used. Example:',
'        <pre><code>',
'            &lt;div class="outer-div"&gt;',
'            {if SLOT_A/}',
'            &lt;div class="inner-div"&gt;#SLOT_A#&lt;/div&gt;',
'            {endif/}',
'            &lt;/div&gt;',
'        </code></pre>',
'    </li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
