wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(2832908358618431)
,p_name=>'P4410_TMPL_COMPONENT_TYPES'
,p_item_sequence=>150
,p_item_plug_id=>wwv_flow_imp.id(4004640729629327)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Available as'
,p_source=>'P4410_SUPPORTED_COMP_TYPES'
,p_source_type=>'ITEM'
,p_display_as=>'NATIVE_CHECKBOX'
,p_named_lov=>'PLUGIN_TEMPLATE_COMPONENT_COMPONENT_TYPES'
,p_lov=>'.'||wwv_flow_imp.id(8409910097232187)||'.'
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'YES'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Specifies how the plug-in can be displayed and where it can be used.</p>',
'<p>',
'<dl>',
'<dt>Single (Partial)</dt>',
'<dd>When checked, the Template Component can be used for an Interactive Report Column or for a region to show a single row.</dd>',
'<dt>Multiple (Report)</dt>',
'<dd>When checked, the Template Component can be used for a region to show multiple rows with pagination options.</dd>',
'<dt>Region Only</dt>',
'<dd>When checked, the Template Component can be used as a region showing static values. The provided HTML template is displayed without any wrapping HTML elements around it. The region has a limited number of attributes in Page Designer (excludes Reg'
||'ion Template, Header text, Footer text). It is recommended to include the <code>APEX$DOM_ID</code> substitution as an ID attribute of an element in within the template, to ensure that existing APEX functionality works with this component.</dd>',
'</dl>',
'<p>Template Components can always be used in server-side Template Directives using <code>{with/}</code> and <code>{apply/}</code> syntax without checking any of the checkboxes.<p>',
'<p>Example:',
'<pre>',
'{with/}',
'PLACEHOLDER1:=Some value',
'PLACEHOLDER2:=Some value',
'{apply INTERNAL_NAME/}',
'</pre>',
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'number_of_columns', '1')).to_clob
,p_multi_value_type=>'SEPARATED'
,p_multi_value_separator=>':'
);
