wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(9811750713144402)
,p_name=>'P4410_PARTIAL_TEMPLATE'
,p_item_sequence=>160
,p_item_plug_id=>wwv_flow_imp.id(4004640729629327)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Partial'
,p_source=>'PARTIAL_TEMPLATE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'PLUGIN_COM.ORACLE.APEX.CODE_EDITOR'
,p_cSize=>80
,p_cMaxlength=>32767
,p_cHeight=>25
,p_field_template=>wwv_flow_imp.id(561549716994252345)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Enter the markup for the template. The Static IDs of the Custom Attributes of scope "Component" can be referenced with <code>#STATIC_ID#</code> syntax.',
'You can quickly synchronize all placeholders as Custom Attributes using the <strong>Synchronize from Templates</strong> button from the Custom Attributes region.',
'</p>',
'<p>',
'The following predefined template placeholders are supported:',
'<dl>',
'<dt>APEX$DOM_ID</dt>',
'<dd>Unique DOM ID generated when the template is invoked, useful for referencing other DOM elements in the provided HTML markup.</dd>',
'<dt>APEX$IS_LAZY_LOADING</dt>',
'<dd>Set to <code>T</code> if the region uses lazy loading to load its data and skeleton markup should be rendered instead.</dd>',
'<dt>APEX$HAS_ACTION_BUTTONS</dt>',
'<dd>Set to <code>T</code> if at least one button or button menu action gets rendered.</dd>',
'<dt>APEX$TITLE</dt>',
'<dd>Title of the region.</dd>',
'<dt>APEX$COMPONENT_CSS_CLASSES</dt>',
'<dd>CSS classes specified for the region.</dd>',
'<dt>APEX$SELECTOR</dt>',
'<dd>For row selection support. Renders as a radio or checkbox control depending on single or multiple selection. This placeholder will only be populated in the context of a template component report.</dd>',
'<dt>APEX$VALUE_IDENTIFIES_ROW</dt>',
'<dd>Contains row values of report columns which enabled the accessibilty related column setting "Value Identifies Row". Enabling this setting on multiple report columns outputs the values separated by a blank. This placeholder will only be populated '
||'in the context of a template component report.</dd>',
'</dl>',
'</p>',
'<p>The Static IDs of Action Positions can be referenced with <code>#STATIC_ID#</code> syntax.',
'If the Action Position is of type Link, <code>#STATIC_ID_ATTR#</code> can be used to reference the value of the Link Attribute.</p>',
'<p>You can also use slot placeholders to allow this partial to render page components (regions, items, buttons). Slots can be referenced with <code>#SLOT_STATIC_ID#</code> syntax. To render a slot conditionally to its usage use the <code>{if SLOT_STA'
||'TIC_ID/}&lt;div class="inner-div"&gt;#SLOT_STATIC_ID#&lt;/div&gt;{endif/}</code> syntax to render additional markup only if the slot is being used. Slots in the partial template will only render if the associated region uses <strong>Display As: Singl'
||'e (Partial)</strong></p>',
'',
'<p>Supports Template Directives.</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'HTMLMIXED',
  'attribute_02', 'VARCHAR2',
  'attribute_03', 'Y',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
);
