wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(20527901230873212)
,p_name=>'P4410_SUBSTITUTE_ATTRIBUTES'
,p_item_sequence=>340
,p_item_plug_id=>wwv_flow_imp.id(48467930491898431)
,p_use_cache_before_default=>'NO'
,p_item_default=>'N'
,p_prompt=>'Substitute Attribute Values'
,p_source=>'SUBSTITUTE_ATTRIBUTES'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_YES_NO'
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Custom Attribute Values specified by the developer might contain items referenced with substitution syntax, for example <code>&amp;P1_DNAME.</code>',
'</p>',
'<p>If Substitute Attribute Values is set to <strong>On</strong> &PRODUCT_NAME. will automatically replace those references with their actual value before calling the plug-in.',
'</p>',
'<p>If Substitute Attribute Values is set to <strong>Off</strong> the values are written unchanged into the <code>attribute_01 - attribute_25</code> record type attributes of <code>p_plugin, p_item, p_region, ...</code> and the plug-in developer is re'
||'sponsible to replace those substitution syntax references with a call to <code>apex_plugin_util.replace_substitutions</code> or do similar replacements.',
'</p>',
'<p>A use case for <strong>Off</strong> would be if the custom plug-in attribute is used as a template and the substitution syntax is used to reference page items and columns of the SQL statement executed by the plug-in. Because the column values of t'
||'he SQL statement are not available at the time when the plug-in is called, the replacement has to be done by the plug-in itself.',
'</p>',
'<p>Example to manually substitute column values for each row:</p>',
'<pre>',
'/* Read data */',
'l_column_value_list := apex_plugin_util.get_data2 (',
'                           p_sql_statement => p_region.source,',
'                           p_region        => p_region );',
'/* Emit rows */',
'for l_row_num in 1 .. l_column_value_list( 1 ).value_list.count loop',
'    begin',
'        -- Assign the column values of the current row',
'        -- into session state',
'        apex_plugin_util.set_component_values (',
'            p_column_value_list => l_column_value_list,',
'            p_row_num           => l_row_num );',
'',
'        ...',
'',
'        -- Link Attribute: Replace substitution variables',
'        -- (including column values of the current row)',
'        l_link := apex_plugin_util.replace_substitutions(',
'                      p_value => p_region.attribute_01 );',
'        ...',
'',
'        apex_plugin_util.clear_component_values;',
'    exception when others then',
'        apex_plugin_util.clear_component_values;',
'        raise;',
'    end;',
'end loop;',
'</pre>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'use_defaults', 'Y')).to_clob
);
