wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(27936921271036180)
,p_name=>'P4410_RENDER_FUNCTION'
,p_item_sequence=>40
,p_item_plug_id=>wwv_flow_imp.id(27935931959010930)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Render Procedure/Function Name'
,p_source=>'RENDER_FUNCTION'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>64
,p_cMaxlength=>255
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Enter the name of the PL/SQL procedure/function to be called to render the plug-in. It can reference a procedure or function of the anonymous PL/SQL code block, a package procedure or function, or stand alone procedure or function in the database.'
||' For example:',
'<pre>',
'render_slider',
'</pre></p>',
'',
'<p>When referencing a database PL/SQL package or stand alone procedure/function, you can use the <code>#OWNER#</code> substitution string to reference the parsing schema of the current application. For example:',
'<pre>',
'#OWNER#.render_slider',
'</pre></p>',
'',
'<p>Item Type Plug-in Render Procedures must implement the following interface:',
'',
'<pre>',
'procedure &lt;name of procedure&gt; (',
'    p_item   in            apex_plugin.t_item,',
'    p_plugin in            apex_plugin.t_plugin,',
'    p_param  in            apex_plugin.t_item_render_param,',
'    p_result in out nocopy apex_plugin.t_item_render_result )',
'</pre>',
'</p>',
'',
'<p>Region Type Plug-in Render Procedures must implement the following interface:',
'',
'<pre>',
'procedure &lt;name of procedure&gt; (',
'    p_plugin in            apex_plugin.t_plugin,',
'    p_region in            apex_plugin.t_region,',
'    p_param  in            apex_plugin.t_region_render_param,',
'    p_result in out nocopy apex_plugin.t_region_render_result )',
'</pre>',
'</p>',
'',
'<p>Dynamic Action Plug-in Render Functions must implement the following interface:',
'',
'<pre>',
'function &lt;name of function&gt; (',
'    p_dynamic_action in apex_plugin.t_dynamic_action,',
'    p_plugin         in apex_plugin.t_plugin )',
'    return apex_plugin.t_dynamic_action_render_result',
'</pre>',
'</p>',
''))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'TEXT',
  'trim_spaces', 'NONE')).to_clob
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(27937216900044386)
,p_name=>'P4410_AJAX_FUNCTION'
,p_item_sequence=>100
,p_item_plug_id=>wwv_flow_imp.id(27935931959010930)
,p_use_cache_before_default=>'NO'
,p_prompt=>'AJAX Procedure/Function Name'
,p_source=>'AJAX_FUNCTION'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>64
,p_cMaxlength=>255
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Enter the name of the PL/SQL procedure/function used by the plug-in to load additional data with an Ajax call. It can reference a procedure or function of the anonymous PL/SQL code block, a package procedure or function, or stand alone procedure o'
||'r function in the database. For example:',
'<pre>',
'ajax_slider',
'</pre></p>',
'',
'<p>When referencing a database PL/SQL package or stand alone procedure or function, you can use the <code>#OWNER#</code> substitution string to reference the parsing schema of the current application. For example:',
'<pre>',
'#OWNER#.ajax_slider',
'</pre></p>',
'',
'<p>The Ajax Procedure callback behaves the same way as an Ajax callback process and can access the generic <code>apex_application.g_x01 - g_x10</code> global variables to transfer data from the browser to the back end. It can also read and set sessio'
||'n state as an Ajax callback process does.</p>',
'',
'<p>To call the Ajax callback function from Javascript, use the same technique as used for Ajax callback processes. Instead of <code>APPLICATION_PROCESS=[process name]</code> use <code>PLUGIN=[p_ajax_identifier]</code>, where p_ajax_identifier is the '
||'value generated with the apex_plugin.get_ajax_identifier function in the render function.</p>',
'',
'<p>Item Type Plug-in Ajax Procedures must implement the following interface:',
'',
'<pre>',
'procedure &lt;name of procedure&gt; (',
'    p_item   in            apex_plugin.t_item,',
'    p_plugin in            apex_plugin.t_plugin,',
'    p_param  in            apex_plugin.t_item_ajax_param,',
'    p_result in out nocopy apex_plugin.t_item_ajax_result )',
'</pre>',
'</p>',
'',
'<p>Region Type Plug-in Ajax Procedures must implement the following interface:',
'',
'<pre>',
'procedure &lt;name of procedure&gt; (',
'    p_plugin in            apex_plugin.t_plugin,',
'    p_region in            apex_plugin.t_region,',
'    p_param  in            apex_plugin.t_region_ajax_param,',
'    p_result in out nocopy apex_plugin.t_region_ajax_result )',
'</pre>',
'</p>',
'',
'<p>Dynamic Action Plug-in Ajax Functions must implement the following interface:',
'',
'<pre>',
'function &lt;name of function&gt; (',
'    p_dynamic_action in apex_plugin.t_dynamic_action,',
'    p_plugin         in apex_plugin.t_plugin )',
'    return apex_plugin.t_dynamic_action_ajax_result',
'</pre>',
'</p>',
'',
'',
'<p>Authentication Scheme Plug-in Ajax Functions must implement the following interface:',
'',
'<pre>',
'function &lt;name of function&gt; (',
'    p_authentication in apex_plugin.t_authentication,',
'    p_plugin         in apex_plugin.t_plugin )',
'    return apex_plugin.t_authentication_ajax_result',
'</pre>',
'</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'TEXT',
  'trim_spaces', 'NONE')).to_clob
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(27937500062049023)
,p_name=>'P4410_VALIDATION_FUNCTION'
