wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(32723128238376948)
,p_name=>'P4410_REFERENCE_ID'
,p_item_sequence=>100
,p_item_plug_id=>wwv_flow_imp.id(33340707031647637)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Subscribe From'
,p_source=>'REFERENCE_ID'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_named_lov=>'FLOW_SUBSCRIBE_FROM_PLUGINS'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select case when p.security_group_id in ( 11, 12 ) ',
'       then wwv_flow_lang.system_message( ''SUBSCRIBED_FROM.THEME_REPOSITORY'' )',
'       else to_char( p.flow_id )',
'       end ||'' : ''||p.display_name || ',
'       case when p.theme_id is not null',
'       then '' '' || wwv_flow_lang.system_message( ''THEME.THEME_ID_POSTFIX'', p0 => p.theme_id )',
'       end as d,',
'       p.id as r',
'  from wwv_flow_plugins p,',
'       wwv_main_apps_dev f',
' where ( (    p.flow_id != to_number(:FB_FLOW_ID)',
'          and p.theme_id is null',
'          and :P4410_THEME_ID is null )',
'        or ( p.theme_id is not null',
'          and :P4410_THEME_ID is not null',
'          and p.id != :P4410_ID ) )',
'   and p.security_group_id in ( to_number(:WORKSPACE_ID), 11, 12 )',
'   and f.id                = p.flow_id',
'   and f.build_status     not in (''RUN_ONLY'',''RUN_AND_HIDDEN'')',
' order by 1'))
,p_lov_display_null=>'YES'
,p_lov_null_text=>'- no plug-in -'
,p_lov_cascade_parent_items=>'P4410_THEME_ID'
,p_ajax_optimize_refresh=>'N'
,p_cSize=>50
,p_cMaxlength=>2000
,p_read_only_when_type=>'NEVER'
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'YES'
,p_help_text=>'<p>Use this field to base this plug-in on an existing plug-in in this application or another application in your workspace.</p>'
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'case_sensitive', 'N',
  'display_as', 'DIALOG',
  'fetch_on_search', 'N',
  'initial_fetch', 'FIRST_ROWSET',
  'manual_entry', 'N',
  'match_type', 'CONTAINS',
  'min_chars', '0')).to_clob
);
