,p_item_plug_id=>wwv_flow_imp.id(538625467201238345)
,p_use_cache_before_default=>'NO'
,p_prompt=>'JavaScript'
,p_source=>'JAVASCRIPT_FILE_URLS'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXTAREA'
,p_cSize=>96
,p_cMaxlength=>4000
,p_cHeight=>3
,p_tag_css_classes=>'a-Form-textarea--code'
,p_field_template=>wwv_flow_imp.id(561549638722251517)
,p_item_template_options=>'#DEFAULT#:a-Form-fieldContainer--stretch'
,p_escape_on_http_input=>'Y'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Enter JavaScript file URLs for code to be loaded with this plug-in. Each URL has to be written on a new line. If you provide a minified version of your file you can use the substitution string <code>#MIN#</code> to include <code>.min</code>, or <c'
||'ode>#MIN_DIRECTORY#</code> to include <code>minified/</code> in your file URL for a regular page view, and an empty string if the page is viewed in debug mode. You also have access to the substitution string <code>#PLUGIN_FILES#</code> to substitute '
||'the value of the plug-in''s file prefix.</p>',
'',
'<p>JavaScript file URLs you enter here will be emitted within the <code>#GENERATED_JAVASCRIPT#</code> substitution string in the page template.</p>',
'',
'<p>Note: You do not need to include opening or closing <code>script</code> tags, just the file URL.',
'',
'<p>',
'Examples:',
'<ul>',
'  <li>Standard file reference',
'      <pre>#PLUGIN_FILES#main.js</pre>',
'  </li>',
'  <li>Standard file reference which loads the minified file main.min.js from #PLUGIN_FILES#minified/ for regular page views and main.js from #PLUGIN_FILES# in debug mode.',
'      <pre>#PLUGIN_FILES##MIN_DIRECTORY#main#MIN#.js</pre>',
'  </li>',
'  <li>Use this syntax if the library is also used from a RequireJS require call. The define name must match what is used in the requirejs.config paths and the value must be the global symbol exposed by the library. Only applies when using RequireJS. '
||'This avoids RequireJS  loading that library a second time.',
'      <pre>[define hammerjs=Hammer]/myjs/hammer.js</pre>',
'  </li>',
'  <li>Use this syntax if the file has a dependency on Oracle JET. This will automatically load RequireJS, the Oracle JET RequireJS configuration and the JET common module bundle before this file.',
'      <pre>[require jet]/myjs/main.js</pre>',
'  </li>',
'  <li>Use this syntax if the file has a dependency on RequireJS. This will automatically load RequireJS before this file.',
'      <pre>[require requirejs]/myjs/main.js</pre>',
'  </li>',
'</ul>',
'</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'auto_height', 'Y',
  'character_counter', 'N',
  'resizable', 'Y',
  'trim_spaces', 'NONE')).to_clob
);
