wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(439437431648840248)
,p_event_id=>wwv_flow_imp.id(439437108210840247)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'Y'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'let',
'    selectedItems = apex.item( "P4410_REGION_ATTRIBUTES" ).getValue(),',
'    items$ = $( "#P4410_REGION_ATTRIBUTES" ),',
'    checkboxAjaxItems$ = items$.find( "input[value=AJAX_ITEMS_TO_SUBMIT]" ),',
'    checkboxOrberBy$ = items$.find( "input[value=ORDER_BY]" ),',
'    checkboxSupportsFiltering$ = items$.find( "input[value=SUPPORTS_EXTERNAL_FILTERING]" ),',
'    checkboxHasColumns$ = items$.find( "input[value=COLUMNS]" ),',
'    checkboxesOfColumns$ = items$.find( "input[value=COLUMN_HEADING],input[value=HEADING_ALIGNMENT],input[value^=VALUE_]" ),',
'    checkboxesOfAi$ = items$.find( "input[value=AI_SYSTEM_PROMPT],input[value=AI_WELCOME_MESSAGE]" );',
'',
'// RULE 1: Enable/Disable Region Source Type Checkboxes',
'const SOURCE_TYPES = ["SOURCE_LOCATION", "SOURCE_PLAIN", "SOURCE_HTML", "SOURCE_SQL", "SOURCE_PLSQL", "SOURCE_PLSQL_FUNCTION"];',
'',
'const sourceTypeIdx = (function () {',
'    //',
'    // return the index position of the selected source type',
'    //',
'    for (var i = 0; i < selectedItems.length; i++) {',
'        var lIdx = SOURCE_TYPES.indexOf(selectedItems[i]);',
'        if (lIdx >= 0) {',
'            return lIdx;',
'        }',
'    }',
'    return -1;',
'})();',
'',
'if (sourceTypeIdx >= 0) {',
'    //',
'    // disable every type but the selected source type',
'    // ',
'    for (var lIdx = 0; lIdx < SOURCE_TYPES.length; lIdx++) {',
'        if (lIdx !== sourceTypeIdx) {',
'            $("#P4410_REGION_ATTRIBUTES input[value=" + SOURCE_TYPES[lIdx] + "]").prop({ "disabled": true, "checked": false });',
'        }',
'    }',
'} else {',
'    //',
'    // no type selected -> enable all types',
'    //',
'    for (var lIdx = 0; lIdx < SOURCE_TYPES.length; lIdx++) {',
'        $("#P4410_REGION_ATTRIBUTES input[value=" + SOURCE_TYPES[lIdx] + "]").prop({ "disabled": false, "checked": false });',
'    }',
'}',
'',
'// RULE 2: Enable/Disable "Has Region Columns" and "Supports Faceted Search"',
'checkboxOrberBy$.add( checkboxSupportsFiltering$ ).prop( selectedItems.includes( "SOURCE_LOCATION" )',
'    ? { "disabled": false }',
'    : { "disabled": true, "checked": false }',
');',
'',
'// RULE 3: Enable/Disable "Has Region Columns"',
'checkboxHasColumns$ .prop( selectedItems.includes( "SOURCE_LOCATION" ) || selectedItems.includes( "SOURCE_SQL" )',
'    ? { "disabled": false }',
'    : { "disabled": true, "checked": false }',
');',
'',
'// RULE 4: Enable/Disable Column Attributes',
'selectedItems = apex.item( "P4410_REGION_ATTRIBUTES" ).getValue(); // refresh items',
'',
'checkboxesOfColumns$.prop( selectedItems.includes( "COLUMNS" )',
'    ? { "disabled": false }',
'    : { "disabled": true, "checked": false }',
');',
'',
'// RULE 5: Enable/Disable AI related Attributes',
'checkboxesOfAi$.prop( ( selectedItems.includes( "AI_ENABLED_ALWAYS" ) || selectedItems.includes( "AI_ENABLED" ) )',
'    ? { "disabled": false }',
'    : { "disabled": true, "checked": false }',
');'))
);
