,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'Y'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'// in a few specific cases, "Substitute Attribute Values" should be hidden',
'if( apex.items.P4410_PLUGIN_TYPE.value === "TEMPLATE COMPONENT" ||',
'    ( apex.items.P4410_PLUGIN_TYPE.value === "REGION TYPE" && ',
'       /* P4410_API_VERSION_REGION is of type Radio Group and using apex.items API ',
'       will throw a JS error in the console when the plug-in is copied and subscribed, see bug 37090926 */',
'      apex.item("P4410_API_VERSION_REGION").getValue() === "3" ) ||',
'    ( apex.items.P4410_PLUGIN_TYPE.value === "ITEM TYPE" && ',
'      apex.items.P4410_API_VERSION_ITEM.value === "3" ) ',
'    ',
') {',
'    apex.item("P4410_SUBSTITUTE_ATTRIBUTES").hide();',
'} else {',
'    apex.item("P4410_SUBSTITUTE_ATTRIBUTES").show();',
'}'))
);
