,p_use_cache_before_default=>'NO'
,p_item_default=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_next_sequence number;',
'begin',
'    select coalesce(max(attribute_sequence), 0)+1',
'      into l_next_sequence',
'      from wwv_flow_plugin_attributes',
'     where plugin_id             = to_number(:P4415_PLUGIN_ID)',
'       and security_group_id     in ( :WORKSPACE_ID, 11, 12 )',
'       and (  attribute_scope    = :P4415_ATTRIBUTE_SCOPE',
'           or :P4415_PLUGIN_TYPE = ''TEMPLATE COMPONENT''',
'           );',
'',
'    return l_next_sequence;',
'end;'))
