wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(2804735544667419)
,p_validation_name=>'P4415_STATIC_ID unique for plugins with multiple scopes'
,p_validation_sequence=>330
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select 1',
'  from wwv_flow_plugin_attributes',
' where plugin_id          = :P4415_PLUGIN_ID',
'   and security_group_id  = :WORKSPACE_ID',
'   and static_id          = :P4415_STATIC_ID',
'   and attribute_scope    = :P4415_ATTRIBUTE_SCOPE',
'   and (  :P4415_ID is null',
'       or id <> :P4415_ID',
'       )',
'union all',
'select 1',
'  from wwv_flow_plugin_slots',
' where flow_id           = :FB_FLOW_ID',
'   and plugin_id         = :P4415_PLUGIN_ID',
'   and security_group_id = :WORKSPACE_ID',
'   and placeholder       = :P4415_STATIC_ID'))
,p_validation_type=>'NOT_EXISTS'
,p_error_message=>'Static Identifier already in use as a custom attribute, or region plugin slot.'
,p_validation_condition=>':P4415_PLUGIN_TYPE in (''REGION TYPE'', ''ITEM TYPE'')'
,p_validation_condition2=>'PLSQL'
,p_validation_condition_type=>'EXPRESSION'
,p_associated_item=>wwv_flow_imp.id(9813324748144418)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
