'        select p.display_name                                as display_name,',
'               wwv_flow_lang.system_message(''DICTIONARY_VIEW.APEX_APPL_TASKDEF_ACTIONS'') as object_type,',
'               ''f?p=4000:9506:''||:APP_SESSION||''::NO:RP,9506:''||''P9506_ID,FB_FLOW_ID:''||a.id||'',''||a.flow_id as object_url,',
'               a.name                                        as object_name,',
'               null                                          as component_type,',
'               null                                          as component_id,',
'               a.flow_id                                     as app_id,',
