 p_id=>wwv_flow_imp.id(14886004355621915)
,p_plug_name=>'Component Settings'
,p_region_template_options=>'#DEFAULT#:a-IRR-region--noOuterBorders'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(646287526247383209)
,p_plug_display_sequence=>30
,p_plug_new_grid_row=>false
,p_plug_new_grid_column=>false
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select s.id,',
'       s.display_name,',
'       s.plugin_type,',
'       s.last_updated_on,',
'       s.last_updated_by,',
'       --',
'       ''icon-sc-component-settings''                as icon_class,',
'       s.display_name                              as icon_title,',
'       wwv_flow_page_api.get_url(',
'           p_page        => 4446,',
'           p_clear_cache => 4446,',
'           p_items       => ''P4446_ID'',',
'           p_values      => s.id ) edit_link,       ',
'       --',
'       case when s.reference_id is not null then',
'           coalesce ( to_char( master.flow_id ),',
'                       wwv_flow_lang_dev.builder_message( ''SUBSCRIBED_FROM.NONEXISTING_MASTER'' ) )',
'       end as subscribed_from,',
'       ( select case when count(*) > 0 then count(*) end',
'           from wwv_flow_plugin_settings sub',
'          where sub.reference_id      = s.id',
'            and sub.security_group_id = :WORKSPACE_ID ) as subscribers,',
'       case when s.reference_id is not null then',
'           case',
'               when master.version_scn = s.version_scn then',
'                   wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_UP_TO_DATE'')',
'               when master.version_scn != s.version_scn then',
'                   wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_NEEDS_REFRESH'')',
'               else',
'                   wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_UNKNOWN'')',
'           end',
'       end subscription_status',
'       --',
'  from wwv_flow_plugin_settings_dev s,',
'       wwv_flow_plugin_settings master',
' where s.flow_id           = :FB_FLOW_ID',
'   and s.security_group_id = :WORKSPACE_ID',
'   and s.reference_id      = master.id (+)',
'   and s.security_group_id = master.security_group_id (+)'))
