,p_process_clob_language=>'PLSQL'
,p_process_when=>':P4446_PLUGIN_TYPE in (''REGION TYPE'', ''ITEM TYPE'')'
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_internal_uid=>2965697009895409
);
