wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(346057922272119929)
,p_name=>'P4495_POST_AUTH_PROCESS'
,p_item_sequence=>260
,p_item_plug_id=>wwv_flow_imp.id(345924009281078364)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Post-Authentication Procedure Name'
,p_source=>'POST_AUTH_PROCESS'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>64
,p_cMaxlength=>255
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Specify the name of a procedure to be executed by the &PRODUCT_NAME. login procedure (login API) after',
'the authentication step (login credentials verification). The login procedure will execute this code after',
'it verified the user''s credentials, but before registering the user in the session and redirecting to the',
'desired application page. The procedure can be defined in the PL/SQL Code attribute or',
'within the database.</p>',
'',
'<p>For example, to transform the <code>JOHNDOE@EXAMPLE.COM</code> authenticated username to',
'<code>JOHNDOE</code>, define <code>my_post_auth</code> procedure in the PL/SQL Code attribute:</p>',
'<pre>',
'procedure my_post_auth',
'is',
'begin',
'  apex_custom_auth.set_user (',
'    p_user => regexp_replace(:APP_USER, ''@.*'', null) );',
'end my_post_auth;',
'</pre>',
'',
'<p>Then, reference this procedure in the Post-Authentication Procedure Name attribute:</p>',
'<pre>',
'my_post_auth',
'</pre>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'TEXT',
  'trim_spaces', 'NONE')).to_clob
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(346898909384210784)
,p_name=>'P4495_SCHEME_TYPE'
,p_is_required=>true
,p_item_sequence=>40
,p_item_plug_id=>wwv_flow_imp.id(345889721617072434)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Scheme Type'
,p_source=>'SCHEME_TYPE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'AUTHENTICATION_SCHEME_TYPE'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select d,',
'       r',
'  from (',
'        select wwv_flow_lang.system_message(''AUTHENTICATION_NAME.''|| name_with_prefix) as d,',
'               name_with_prefix      as r',
'          from wwv_flow_native_plugins',
'         where plugin_type = ''AUTHENTICATION TYPE''',
'         union all',
'        select display_name || wwv_flow_lang.system_message(''PLUGIN.DISPLAY_NAME_POSTFIX'') as d,',
'               ''PLUGIN_'' || name     as r',
'          from wwv_flow_plugins',
'         where flow_id           = to_number(:FB_FLOW_ID)',
'           and security_group_id = to_number(:WORKSPACE_ID)',
'           and plugin_type       = ''AUTHENTICATION TYPE''',
'       )',
' order by 1'))
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(452656722938220607)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'YES'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Select how this authentication scheme will be applied.  The following built-in types are supported (they can be extended using plug-ins):</p>',
'<ul>',
'    <li><strong>Builder Extension Sign-In</strong> - Enables you to integrate this application with the APEX development environment.</li>',
'    <li><strong>Custom</strong> - Enables you to create a custom authentication scheme from scratch, giving you complete control over your authentication interface.</li>',
'    <li><strong>Database Accounts</strong> - This authentication scheme requires that a database user (schema) exists in the local database. When using this method, the user name and password of the database account is used to authenticate the user.<'
||'/li>',
'    <li><strong>HTTP Header Variable</strong> - Authenticate externally, where the username is stored in an HTTP header variable set by the web server.</li>',
'    <li><strong>Internal Application Extension</strong> - Use this scheme for extensions to internal applications.</li>',
'    <li><strong>LDAP Directory</strong> - Authentication of user/password with an authentication request to an LDAP server.</li>',
'    <li><strong>No Authentication</strong> - Adopts the current database user.</li>',
'    <li><strong>Open Door Credentials</strong> - Enables anyone to access your application using a login page that captures a user name.</li>',
'    <li><strong>Oracle APEX Accounts</strong> - &PRODUCT_NAME. Account Credentials are internal user accounts that are created within and managed in the &PRODUCT_NAME. user repository. When you use this method, your application is authenticated again'
||'st these accounts.</li>',
'    <li><strong>SAML Sign-In</strong> - Supports authentication with SAML2 identity providers.</li>',
'    <li><strong>Social Sign-In</strong> - Supports authentication with Google, Facebook, generic OpenID Connect, and generic OAuth2 identity providers.</li>',
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
