,p_cSize=>64
,p_cMaxlength=>255
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Enter the name of a function that is called after the session sentry returned successfully. The',
'function can either be defined in the PL/SQL Code attribute or directly in the database. The boolean',
'return value of this function determines whether or not the session is still valid.</p>',
'',
'<p>For example, to restrict the use of your application to specific business hours, define',
'<code>check_business_hours</code> function in the PL/SQL Code attribute:</p>',
'<pre>',
'function check_business_hours return boolean',
'is',
'begin',
'  return to_number(to_char(sysdate, ''hh24'')) between 8 and 17;',
'end check_business_hours;',
'</pre>',
'<p>Then, reference this function in the Verify Function Name attribute:</p>',
'<pre>',
'check_business_hours',
'</pre>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
