  'trim_spaces', 'NONE')).to_clob
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(414185518003152116)
,p_name=>'P4495_SWITCH_IN_SESSION_YN'
,p_is_required=>true
,p_item_sequence=>270
,p_item_plug_id=>wwv_flow_imp.id(345924009281078364)
,p_use_cache_before_default=>'NO'
,p_item_default=>'N'
,p_prompt=>'Switch in Session'
,p_source=>'SWITCH_IN_SESSION_YN'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'ENABLED_DISABLED_RETURNS_Y_OR_N'
,p_lov=>'.'||wwv_flow_imp.id(91439803955181562)||'.'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'Select <strong>Enabled</strong> to enable switching from the default authentication scheme to this scheme in the current &PRODUCT_NAME. session. Select <strong>Disabled</strong> if the authentication scheme should not be enabled at runtime.',
'</p><p>',
'If enabled, the current session''s authentication scheme can be changed by passing <strong>APEX_AUTHENTICATION=scheme name</strong> in a URL''s request parameter.',
'</p>',
'<h3>Example</h3>',
'<p>',
'The developer adds a button labelled "Sign In with OAuth2" to the application''s login page, which redirects to',
'<pre>',
'f?p=&amp;APP_ID.:1:&amp;APP_SESSION.:APEX_AUTHENTICATION=OAuth2-Scheme',
'</pre>',
'where "OAuth2-Scheme" is the authentication scheme name. When processing the request (and assuming "Switch in Session" is enabled), &PRODUCT_NAME. registers the scheme in the session and will use it for all future requests.',
'</p>',
'<p>',
'<strong>NOTE:</strong>',
'If the application has an <em>Authentication Configuration Procedure</em>,',
'changing the authentication via the URL is not supported.',
'However, this attribute still has to be set.',
'</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
