wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(6902842551389926)
,p_name=>'P4653_DEFAULT_LANDMARK_TYPE'
,p_item_sequence=>10
,p_item_plug_id=>wwv_flow_imp.id(6902767343389925)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Default Landmark Type'
,p_source=>'DEFAULT_LANDMARK_TYPE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov=>'STATIC:Banner;banner,Complementary;complementary,Content Info;contentinfo,Form;form,Main;main,Navigation;navigation,Region;region,Search;search'
,p_lov_display_null=>'YES'
,p_lov_null_text=>'- No Default Landmark -'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Define the default landmark type to be used for this region template. When this region template is used by a region, this will be the landmark type exposed to screen reader users, unless this has been overridden at region level.</p>',
'<p>Note: In order for this functionality to work, the Template attribute must include the <code>#REGION_LANDMARK_ATTRIBUTES#</code> substitution string. This should be defined on the main container element of the template.</p>',
'<p>Landmarks provide a powerful way to identify the organization and structure of a web page. The structural information conveyed visually to users should be represented programmatically in the markup using landmark roles. The use of landmarks roles '
||'support keyboard navigation to the structure of a web page for screen reader users, and can be used as targets for browser extensions for enhanced keyboard navigation.</p>',
'<p>The <a rel="noopener noreferrer" target="_blank" href="https://www.w3.org/WAI/ARIA/apg/example-index/landmarks/index.html">W3C ARIA Landmarks site</a> provides useful information, including a good reference implementation (click on the ''Show Landm'
||'arks'' button to visualize well defined landmarks).</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
