,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Defines the row template. You can use these substitution strings here:',
'<ul>',
'<li>#COLUMN_VALUE# - Will be replaced with the value of a column</li>',
'<li>#ALIGNMENT# - Specified by the user, determines the alignment of a column</li>',
'<li>#COLNUM# - Current Column Number</li>',
'<li>#COLUMN_HEADER# - Column Header</li>',
'<li>#COLCOUNT# - Number of Columns</li>',
'<li>#ROWNUM# - Current Row Number</li>',
'</ul>',
'<p>You can also use column number syntax to reference columns by select list position in the query, such as #1#, #2#.</p>',
'<p>A typical example would be:</p>',
'<pre>&lt;td #ALIGNMENT#&gt;#COLUMN_VALUE#&lt;/td&gt;</pre>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'HTMLMIXED',
  'attribute_02', 'VARCHAR2',
  'attribute_03', 'Y',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
);
