,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(646287526247383209)
,p_plug_display_sequence=>40
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ',
'    case component_status',
'    when ''MISSING'' then null',
'    else',
'        wwv_flow_working_copy_dev.add_encoded_checkbox (',
'            p_component_type           => component_type,',
'            p_component_id             => component_id,',
'            p_component_type_label     => component_type_label,',
'            p_component_display_name   => component_display_name,',
'            p_status                   => component_status,',
'            p_rownum                   => rownum ) ',
'    end as sel,',
'    v.*',
'from ( ',
'    select r.component_id,',
'           l.seq_id  as export_left_id,',
'           r.seq_id  as export_right_id,',
'           r.file_name,',
'           r.component_type,',
'           r.component_type_label,',
'           r.component_display_name,',
'           null as link,',
'           r.component_export_id,',
'           ''CHANGED'' as component_status,',
'           wwv_flow_lang_dev.builder_message( p_name => ''APEXDEV.DIFF.CHANGED'' ) as component_status_display,',
'           l.offset_component_id as left_offset_comp_id,',
'           r.offset_component_id as right_offset_comp_id,',
'           ''info'' as badge_state',
'      from wwv_flow_diff_export_left_dev l,',
'           wwv_flow_diff_export_right_dev r',
'     where l.offset_component_id = r.offset_component_id',
'       and l.component_type      = r.component_type',
'       and l.diff_checksum      != r.diff_checksum',
'    union all',
'    /* new components that exist in the right app but not in the left */',
'    select r.component_id,',
'           null      as export_left_id,',
'           r.seq_id as export_right_id,',
'           r.file_name,',
'           r.component_type,',
'           r.component_type_label,',
'           r.component_display_name,',
'           null as link,',
'           r.component_export_id,',
'           ''ADDED'' as component_status,',
'           wwv_flow_lang_dev.builder_message( p_name => ''APEXDEV.DIFF.ADDED'' ) as component_status_display,',
'           null as left_offset_comp_id,',
'           r.offset_component_id as right_offset_comp_id,',
'           ''success'' as badge_state',
'      from wwv_flow_diff_export_right_dev r,',
'           wwv_flow_diff_export_left_dev l',
'     where l.component_type      (+) = r.component_type',
'       and l.offset_component_id (+) = r.offset_component_id',
'       and l.component_type is null',
'       and l.offset_component_id is null',
'       and not exists (',
'           /* ignore list items when the list is being created/new */',
'           select null',
'             from wwv_flow_list_items',
'            where list_id in (select ir.component_id ',
'                                from wwv_flow_diff_export_right_dev ir',
'                               where ir.component_type = ''LIST''',
'                                and not exists',
'                                       ( select null ',
'                                           from wwv_flow_diff_export_left_dev il',
'                                          where il.component_type      = ir.component_type',
'                                            and il.offset_component_id = ir.offset_component_id',
'                                       )                         ',
'                            )',
'              and id                = r.component_id',
'              and security_group_id = :WORKSPACE_ID',
'       )',
'    union all',
'    /* components that exist in the left app but not in the right (might have been deleted or merged in from another app) */',
'    select l.component_id,',
'           l.seq_id  as export_left_id,',
'           null      as export_right_id,',
'           l.file_name,',
'           l.component_type,',
'           l.component_type_label,',
'           l.component_display_name,',
'           null as link,',
'           l.component_export_id,',
'           ''MISSING'' as component_status,',
'           wwv_flow_lang_dev.builder_message( p_name => ''APEXDEV.DIFF.MISSING'' ) as component_status_display,',
'           l.offset_component_id as left_offset_comp_id,',
'           null as right_offset_comp_id,',
'           ''danger'' as badge_state',
'      from wwv_flow_diff_export_left_dev l,',
'           wwv_flow_diff_export_right_dev r',
'     where l.component_type         = r.component_type (+)',
'       and l.offset_component_id    = r.offset_component_id (+)',
'       and nvl(:P5300_REVERSE, ''N'') = ''N''',
'       and r.component_type is null',
'       and r.offset_component_id is null',
') v',
'order by component_type_label, component_display_name'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P5300_REVERSE'
,p_prn_content_disposition=>'ATTACHMENT'
