wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(3184674367144506)
,p_event_id=>wwv_flow_imp.id(3600632309086116)
,p_event_result=>'TRUE'
,p_action_sequence=>40
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select sum(status_count)',
'into :P5300_DIFF_COUNT',
'from (',
'    select count(*) as status_count,',
'           ''CHANGED'' as status',
'      from wwv_flow_diff_export_left_dev l,',
'           wwv_flow_diff_export_right_dev r',
'     where l.offset_component_id = r.offset_component_id',
'       and l.component_type = r.component_type',
'       and l.diff_checksum != r.diff_checksum',
'       and r.component_type not in (select column_value from table(wwv_flow_working_copy_dev.get_unsupported_export_types))',
'    union all',
'    select count(*) as status_count,',
'           ''ADDED'' as status',
'      from wwv_flow_diff_export_right_dev r',
'      left join wwv_flow_diff_export_left_dev l on',
'              l.component_type = r.component_type',
'          and l.offset_component_id = r.offset_component_id',
'     where l.component_type is null',
'       and l.offset_component_id is null',
'       and r.component_type not in (select column_value from table(wwv_flow_working_copy_dev.get_unsupported_export_types))',
'       and not exists (',
'           /* ignore list items when the list is being created/new */',
'           select null',
'             from wwv_flow_list_items',
'            where list_id in (select ir.component_id ',
'                                from wwv_flow_diff_export_right_dev ir',
'                               where ir.component_type = ''LIST''',
'                                 and not exists',
'                                       ( select null ',
'                                           from wwv_flow_diff_export_left_dev il',
'                                          where il.component_type = ir.component_type',
'                                            and il.offset_component_id = ir.offset_component_id',
'                                       )                         ',
'                            )',
'              and id = r.component_id',
'              and security_group_id = :WORKSPACE_ID',
'       )',
'    union all',
'    select count(*) as status_count,',
'           ''MISSING'' as status',
'      from wwv_flow_diff_export_left_dev l',
'      left join wwv_flow_diff_export_right_dev r on',
'              l.component_type = r.component_type',
'          and l.offset_component_id = r.offset_component_id',
'     where r.component_type is null',
'       and r.offset_component_id is null',
'       and l.component_type not in (select column_value from table(wwv_flow_working_copy_dev.get_unsupported_export_types))',
'       and nvl(:P5300_REVERSE, ''N'') = ''N''',
');'))
,p_attribute_03=>'P5300_DIFF_COUNT'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
