begin
wwv_flow_imp_page.create_page(
 p_id=>5303
,p_name=>'About Working Copies'
,p_alias=>'ABOUT-WORKING-COPIES'
,p_page_mode=>'MODAL'
,p_step_title=>'About Working Copies'
,p_autocomplete_on_off=>'OFF'
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'.a-Region .a-Region-body {',
'  font-size: 14px;',
'  line-height: 20px;',
'}',
'',
'.a-Region .a-Region-body h3 {',
'    margin-top: 8px;',
'    margin-bottom: 4px;',
'}',
