'.a-Region .a-Region-body ul {',
'  margin-bottom: 16px;',
'}'))
,p_step_template=>wwv_flow_imp.id(120871216744825711)
,p_page_template_options=>'#DEFAULT#'
,p_dialog_height=>'560'
,p_protection_level=>'C'
,p_page_component_map=>'11'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3185079872144510)
,p_plug_name=>'About Working Copies'
,p_region_css_classes=>'padding-left-md padding-right-md'
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody:a-Region--noBorder:a-Region--hideHeader'
,p_plug_template=>wwv_flow_imp.id(174794400314076650)
,p_plug_display_sequence=>10
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<h3>Tips</h3>',
'<ul>',
'    <li>Developers can use distinct working copies. To avoid overwrites or errors on merge:',
'        <ul>',
'            <li>Lock a page in your main app before modifying it in a working copy</li>',
'            <li>Reserve page ranges for new pages each developer will create</li>',
'            <li>Agree on shared component names each developer will add</li>',
'        </ul>',
'    </li>',
'    <li>Export a working copy as needed using <em>Original IDs</em> to maintain its link with main</li>',
'    <li><em>Unlink</em> a working copy from main by using the <em>Copy Application</em> task</li>',
'    <li>Delete any working copies <em>before</em> deleting an application</li>',
'</ul>',
'<h3>Unsupported Component Types</h3>',
'<p>These component types are not yet supported for <em>automatic</em> merging:',
'   Translations, Themes, Theme Templates, Supporting Objects, Application Properties, Tabs (Legacy), and',
'   Workspace-level components like App Groups, Credentials, or Remote Servers. You can merge the working copy,',
'   then manually apply the additions or changes to these component types.',
'</p>',
'<h3>Limitations</h3>',
'<p>Working copies have the following limitations:</p>',
'<ul>',
'    <li>You cannot create a working copy of a working copy</li>',
'    <li>Deleted working copy pages or shared components must be <em>manually</em> deleted in main</li>',
'    <li>Components listed as <em>Missing</em> may have been removed in the working copy or may only exist in main</li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
end;
