wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3079055206425104)
,p_plug_name=>'Navigate'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(208928010704475743)
,p_plug_display_sequence=>10
,p_list_id=>wwv_flow_imp.id(1385199811261560)
,p_plug_source_type=>'NATIVE_LIST'
,p_list_template_id=>wwv_flow_imp.id(168712225287236339)
,p_translate_title=>'N'
,p_landmark_type=>'navigation'
,p_landmark_label=>'Map Backgrounds'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3084457844524926)
,p_plug_name=>'Map Backgrounds'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(646287526247383209)
,p_plug_display_sequence=>20
,p_include_in_reg_disp_sel_yn=>'Y'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with messages as (',
'    select ( select wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_UP_TO_DATE'') from sys.dual ) up_to_date,',
'           ( select wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_NEEDS_REFRESH'') from sys.dual ) needs_refresh,',
'           ( select wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_UNKNOWN'') from sys.dual ) unknown_status,',
'           ( select wwv_flow_lang_dev.builder_message(''SUBSCRIBED_FROM.NONEXISTING_MASTER'') from sys.dual ) no_master',
'      from sys.dual )',
'select mbg.id,',
'       mbg.name,',
'       (select wwv_flow_lang.system_message( ''MAP_BACKGROUND.TYPES.'' || mbg.type )',
'          from sys.dual )',
'       as type,',
'       mbg.url,',
'       mbg.api_key,',
'       mbg.attribution,',
'       mbg.map_comment,',
'       ''icon-sc-app-search'' icon_class,',
'       wwv_flow_page_api.get_url(',
'           p_application => :APP_ID,',
'           p_page        => 6120,',
'           p_clear_cache => 6120,',
'           p_items       => ''P6120_ID'',',
'           p_values      => mbg.id ) edit_link,',
'       coalesce( mbg.last_updated_on, mbg.created_on ) last_updated,',
'       coalesce( mbg.last_updated_by, mbg.created_by ) last_updated_by,',
'       --',
'       case when mbg.reference_id is not null then',
'           coalesce ( to_char( master.flow_id ),',
'                       messages.no_master )',
'       end as subscribed_from,',
'       ( select case when count(*) > 0 then count(*) end',
'           from wwv_flow_map_backgrounds sub',
'          where sub.reference_id      = mbg.id',
'            and sub.security_group_id = :WORKSPACE_ID ) as subscribers,',
'       case when mbg.reference_id is not null then',
'           case',
'               when master.version_scn = mbg.version_scn then',
'                   messages.up_to_date',
'               when master.version_scn != mbg.version_scn then',
'                   messages.needs_refresh',
'               else',
'                   messages.unknown_status',
'           end',
'       end subscription_status,',
'       --',
'       null action',
'  from wwv_flow_map_backgrounds mbg,',
'       wwv_flow_map_backgrounds master,',
'       messages',
