,p_cSize=>60
,p_cHeight=>3
,p_field_template=>wwv_flow_imp.id(452656722938220607)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'URL used to fetch a map tile layer from the Web Map Service - Open Geospatial Consortium. Pass in the URL with all the required WMS parameters, except the following ones, which are added automatically by the Map Region:',
'<ul>',
'    <li>BBOX</li>',
'    <li>WIDTH</li>',
'    <li>HEIGHT</li>',
'    <li>REQUEST</li>',
'    <li>FORMAT</li>',
'    <li>SRS / CRS</li>',
'</ul>',
'</p><p>',
