,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function buildInterval() {',
'    var lIntervalString = ''FREQ='' + $v("P7021_INT_FREQUENCY") +',
'                          '';INTERVAL='' + $v("P7021_INT_INTERVAL");',
'    ',
'    if ( $v("P7021_BYDAY") !== "" && $v("P7021_INT_FREQUENCY") !== "DAILY" && $v("P7021_BYDAY") !== "MON:TUE:WED:THU:FRI:SAT:SUN" ) {',
'       lIntervalString =  lIntervalString + ";BYDAY=" + $v("P7021_BYDAY").replace(/:/g,",");',
'    }',
'    if ( $v("P7021_BYHOUR") !== "" && $v("P7021_INT_FREQUENCY") !== "HOURLY") {',
'       lIntervalString =  lIntervalString + ";BYHOUR=" + $v("P7021_BYHOUR");',
'    }',
'    if ( $v("P7021_BYMINUTE") !== "" && $v("P7021_INT_FREQUENCY") !== "MINUTELY" ) {',
'       lIntervalString =  lIntervalString + ";BYMINUTE=" + $v("P7021_BYMINUTE");',
'    }',
'        ',
'    return lIntervalString;',
'}',
'',
'function refreshPrimaryKeyColumns() { ',
'    apex.server.process( ',
'        "getColumnInfo",',
'        { ',
'            pageItems: "#P7021_LOCATION,#P7021_LOCAL_DATA_SOURCE_TYPE,#P7021_REMOTE_DATA_SOURCE_TYPE,#P7021_TABLE_OWNER,#P7021_REMOTE_TABLE_OWNER,#P7021_TABLE_NAME,#P7021_REMOTE_TABLE_NAME,#P7021_SQL,#P7021_REMOTE_SQL,#P7021_SOURCE_POST_PROCESSING,#P'
||'7021_POST_PROCESS_QUERY,#P7021_FUNCTION_BODY,#P7021_REMOTE_FUNC_BODY,#P7021_POST_PROC_FUNC_BODY,#P7021_FUNCTION_BODY_LANGUAGE,#P7021_REMOTE_FUNC_BODY_LANG,#P7021_POST_PROC_FUNC_BODY_LANG,#P7021_WEB_SRC_MODULE_ID,#P7021_WEB_SRC_ARRAY_COL_ID,#P7021_REM'
||'OTE_SERVER_ID,#P7021_INCLUDE_ROWID_COLUMN,#P7021_REMOTE_INCLUDE_ROWID,#P7021_GRAPH_NAME,#P7021_PQL_MATCH_CLAUSE,#P7021_PQL_COLUMNS_CLAUSE,#P7021_PQL_WHERE_CLAUSE,#P7021_JSON_SOURCE_ID,#P7021_JSONSRC_ARRAYCOL_ID,#P7021_JSPOST,#P7021_JSPOST_WHERE,#P702'
||'1_JSPOST_ORDERBY,#P7021_JSPOST_QUERY,#P7021_JSPOST_FUNC_BODY_LANG,#P7021_JSPOST_FUNC_BODY,#P7021_DUALITY_VIEW_ID,#P7021_DVSRC_ARRAYCOL_ID,#P7021_DVPOST,#P7021_DVPOST_WHERE,#P7021_DVPOST_ORDERBY,#P7021_DVPOST_QUERY,#P7021_DVPOST_FUNC_BODY_LANG,#P7021_'
||'DVPOST_FUNC_BODY" },',
'        {',
'            success: function( pData ) {',
'                var lItems = apex.jQuery( ".is-column");',
'',
'                //-----------------------------------------------------------------------------------------',
'                function refreshItem( pItem$, pSetValue ) {',
'                    var lValue           = apex.item( pItem$.attr( "name" ) ).getValue(),',
'                        lValueStillValid = false,',
'                        lNullOption$     = pItem$.find( ''option[value=""]''),',
'                        lOption$;',
'',
'                    pItem$.empty();',
'                    if ( lNullOption$.length > 0 ) {',
'                        pItem$.append( lNullOption$ );',
'                    }',
'                    ',
'                    for ( let o = 0; o < pData.length; o++ ) {',
'                        if (    pData[ o ].t === "NUMBER" ',
'                                || pData[ o ].t === "VARCHAR2" ',
'                                || pData[ o ].t === "DATE" ',
'                                || pData[ o ].t === "TIMESTAMP"  )',
'                        {',
'                            lOption$ = apex.jQuery("<option></option>").attr("value", pData[ o ].r ).text( pData[ o ].d );',
'                            if ( pData[ o ].r === lValue ) {',
'                                lValueStillValid = true;',
'                            }',
'                            pItem$.append( lOption$ );',
'                        }',
'                    }',
'',
'                    if ( pSetValue ) {',
'                        if ( lValueStillValid ) {',
'                            apex.item( pItem$.attr( "name" ) ).setValue( lValue );',
'                        } else {',
'                            apex.item( pItem$.attr( "name" ) ).setValue( "" );',
'                        }',
'                    }',
'                }',
'',
'                if ( pData.length > 0 ) {',
'                    for (let i=0; i<lItems.length;i++) {',
'                        refreshItem( apex.jQuery (lItems[ i ] ), true );',
'                    }',
'                }',
'            }',
'        }',
'    );',
'}',
'',
''))
