 p_id=>wwv_flow_imp.id(6353168577393099)
,p_plug_name=>'REST Source Parameters'
,p_parent_plug_id=>wwv_flow_imp.id(2063557467407603)
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(208928010704475743)
,p_plug_display_sequence=>110
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select cp.id, ',
'       pa.name,',
'       pa.data_type,',
'       cp.value_type,',
'       cp.value_language,',
'       cp.value,',
'       cp.format_mask',
'  from wwv_flow_web_src_comp_params cp, wwv_flow_web_src_params pa',
' where pa.id                = cp.web_src_param_id',
'    -- ',
'   and cp.automation_id     = :P7021_ID',
'   and cp.security_group_id = :WORKSPACE_ID',
'   and cp.flow_id           = :FB_FLOW_ID',
'   and cp.security_group_id = pa.security_group_id'))
