,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Distribute items'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    if :P7021_SOURCE_TYPE = ''QUERY'' then',
'',
'        if :P7021_LOCATION = wwv_flow_exec_api.c_location_remote_db then',
'',
'            :P7021_REMOTE_TABLE_OWNER      := :P7021_TABLE_OWNER;',
'            :P7021_REMOTE_TABLE_NAME       := :P7021_TABLE_NAME;',
'            :P7021_REMOTE_DATA_SOURCE_TYPE := :P7021_LOCAL_DATA_SOURCE_TYPE;',
'            :P7021_REMOTE_WHERE            := :P7021_QUERY_WHERE;',
'            :P7021_REMOTE_ORDER_BY         := :P7021_QUERY_ORDER_BY;',
'',
'            case :P7021_REMOTE_DATA_SOURCE_TYPE',
'                when ''SQL''                     then :P7021_REMOTE_SQL := :P7021_SQL;',
'                when ''FUNC_BODY_RETURNING_SQL'' then',
'                    :P7021_REMOTE_FUNC_BODY      := :P7021_SQL;',
'                    :P7021_REMOTE_FUNC_BODY_LANG := :P7021_FUNCTION_BODY_LANGUAGE;',
'                else null;',
'            end case;',
'            :P7021_REMOTE_INCLUDE_ROWID   := :P7021_INCLUDE_ROWID_COLUMN;',
'',
'        elsif :P7021_LOCATION = wwv_flow_exec_api.c_location_local_db then',
'            case :P7021_LOCAL_DATA_SOURCE_TYPE',
'                when ''FUNC_BODY_RETURNING_SQL'' then :P7021_FUNCTION_BODY    := :P7021_SQL;',
'                when ''GRAPH''                   then :P7021_GRAPH_NAME       := :P7021_TABLE_NAME;',
'                                                    :P7021_PQL_WHERE_CLAUSE := :P7021_QUERY_WHERE;',
'                else null;',
'            end case;',
'',
'        elsif :P7021_LOCATION = wwv_flow_exec_api.c_location_json_source then',
'',
'            :P7021_OLD_JSONSRC_ID      := :P7021_DOCUMENT_SOURCE_ID;',
'            :P7021_JSON_SOURCE_ID      := :P7021_DOCUMENT_SOURCE_ID;',
'            :P7021_JSONSRC_ARRAYCOL_ID := :P7021_WEB_SRC_ARRAY_COL_ID;',
'',
'            :P7021_JSPOST              := coalesce( :P7021_SOURCE_POST_PROCESSING, ''NONE'' );',
'',
'            if :P7021_JSPOST = ''WHERE_ORDER_BY_CLAUSE'' then',
'                :P7021_JSPOST_WHERE            := :P7021_QUERY_WHERE;',
'                :P7021_JSPOST_ORDERBY          := :P7021_QUERY_ORDER_BY;',
'            elsif :P7021_JSPOST = ''SQL'' then',
'                :P7021_JSPOST_QUERY            := :P7021_SQL;',
'            elsif :P7021_JSPOST = ''FUNC_BODY_RETURNING_SQL'' then',
'                :P7021_JSPOST_FUNC_BODY_LANG   := :P7021_FUNCTION_BODY_LANGUAGE;',
'                :P7021_JSPOST_FUNC_BODY        := :P7021_SQL;',
'            end if;',
'',
'        elsif :P7021_LOCATION = wwv_flow_exec_api.c_location_duality_view then',
'',
'            :P7021_OLD_DVSRC_ID        := :P7021_DOCUMENT_SOURCE_ID;',
'            :P7021_DUALITY_VIEW_ID     := :P7021_DOCUMENT_SOURCE_ID;',
'            :P7021_DVSRC_ARRAYCOL_ID   := :P7021_WEB_SRC_ARRAY_COL_ID;',
'',
'            :P7021_DVPOST              := coalesce( :P7021_SOURCE_POST_PROCESSING, ''NONE'' );',
'',
'            if :P7021_DVPOST = ''WHERE_ORDER_BY_CLAUSE'' then',
'                :P7021_DVPOST_WHERE            := :P7021_QUERY_WHERE;',
'                :P7021_DVPOST_ORDERBY          := :P7021_QUERY_ORDER_BY;',
'            elsif :P7021_DVPOST = ''SQL'' then',
'                :P7021_DVPOST_QUERY            := :P7021_SQL;',
'            elsif :P7021_DVPOST = ''FUNC_BODY_RETURNING_SQL'' then',
'                :P7021_DVPOST_FUNC_BODY_LANG   := :P7021_FUNCTION_BODY_LANGUAGE;',
'                :P7021_DVPOST_FUNC_BODY        := :P7021_SQL;',
'            end if;',
'',
'        elsif :P7021_LOCATION = wwv_flow_exec_api.c_location_web_source then',
'',
'            if :P7021_SOURCE_POST_PROCESSING = ''WHERE_ORDER_BY_CLAUSE'' then',
'                :P7021_POST_PROCESS_WHERE            := :P7021_QUERY_WHERE;',
'                :P7021_POST_PROCESS_ORDERBY         := :P7021_QUERY_ORDER_BY;',
'            elsif :P7021_SOURCE_POST_PROCESSING = ''SQL'' then',
'                :P7021_POST_PROCESS_QUERY            := :P7021_SQL;',
'            elsif :P7021_SOURCE_POST_PROCESSING = ''FUNC_BODY_RETURNING_SQL'' then',
'                :P7021_POST_PROC_FUNC_BODY_LANG      := :P7021_FUNCTION_BODY_LANGUAGE;',
'                :P7021_POST_PROC_FUNC_BODY           := :P7021_SQL;',
'            end if;',
'',
'            :P7021_SOURCE_POST_PROCESSING := coalesce( :P7021_SOURCE_POST_PROCESSING, ''NONE'' );',
'        end if;',
'',
'        if :P7021_LOCATION in ( wwv_flow_exec_api.c_location_web_source,',
'                                wwv_flow_exec_api.c_location_duality_view,',
'                                wwv_flow_exec_api.c_location_remote_db,',
'                                wwv_flow_exec_api.c_location_json_source )',
'        then',
'            :P7021_SQL                    := null;',
'            :P7021_TABLE_NAME             := null;',
'            :P7021_TABLE_OWNER            := null;',
'            :P7021_QUERY_WHERE            := null;',
'            :P7021_QUERY_ORDER_BY         := null;',
'        end if;',
'',
'    elsif :P7021_SOURCE_TYPE = ''FUNC_BODY_RETURNING_BOOLEAN'' then',
'        :P7021_FUNC_BODY_BOOL_LOCATION := :P7021_LOCATION;',
'',
'        if :P7021_FUNC_BODY_BOOL_LOCATION = wwv_flow_exec_api.c_location_local_db then',
'            :P7021_LOCAL_FUNC_BODY_BOOLEAN      := :P7021_SQL;',
'            :P7021_LOCAL_FUNCBODYBOOL_LANG      := :P7021_FUNCTION_BODY_LANGUAGE;',
'            :P7021_REMOTE_PLSQL_BOOLEAN         := null;',
'            :P7021_PLSQL_REMOTE_SERVER_ID       := null;',
'        else',
'            :P7021_REMOTE_PLSQL_BOOLEAN         := :P7021_SQL;',
'            :P7021_PLSQL_REMOTE_SERVER_ID       := :P7021_REMOTE_SERVER_ID;',
'            :P7021_LOCAL_FUNC_BODY_BOOLEAN      := null;',
'            :P7021_LOCAL_FUNCBODYBOOL_LANG      := null;',
'        end if;',
'        :P7021_SQL := null;',
'    elsif :P7021_SOURCE_TYPE = ''ALWAYS'' then',
'        :P7021_LOCATION                := null;',
'        :P7021_SQL                     := null;',
'        :P7021_LOCAL_FUNC_BODY_BOOLEAN := null;',
'    end if;',
'',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>2515564925671732
);
