wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(29895161562987844)
,p_plug_name=>' Examples'
,p_parent_plug_id=>wwv_flow_imp.id(1409470037910721)
,p_region_template_options=>'#DEFAULT#:is-collapsed:a-Region--noBorder'
,p_plug_template=>wwv_flow_imp.id(689970285456172024)
,p_plug_display_sequence=>30
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'    Example 1: Send en email. This assumes that an email template named <strong>ORDER</strong> exists, with the placeholders used in the ',
'    <strong>p_placeholders</strong> parameter.',
'</p>',
'<pre>',
'begin',
'    apex_mail.send (',
'        p_template_static_id => ''ORDER'',',
'        p_placeholders       => ''{ "ORDER_NUMBER": '' || :ORDER_NUMBER ||',
'                                  ''"ORDER_DATE":"''   || to_char( :ORDER_DATE, ''YYYY-MM-DD'' ) || ''", ''',
'                                  ''"ORDER_TOTAL":''   || :ORDER_TOTAL || ',
'                                ''}'',',
'        p_to                 => ''some_user@somewhere.com'' );',
'end;',
'</pre>',
'<p>',
'    Example 2: Insert a row into another table. If the :SAL value is NULL, write a warning message to the automation log.',
'</p>',
'<pre>',
'begin',
'    insert into other_table( empno, ename, sal )',
'                     values( :EMPNO, :ENAME, :SAL );',
'    if :SAL is null then',
'        apex_automation.log_warn( ''EMPNO '' || :EMPNO ||'' has a NULL Salary'');',
'    end if;',
'end;',
'</pre>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
