wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1409356763910720)
,p_name=>'P7022_ACTION_TYPE'
,p_source_data_type=>'VARCHAR2'
,p_is_required=>true
,p_item_sequence=>50
,p_item_plug_id=>wwv_flow_imp.id(1410170163910728)
,p_item_source_plug_id=>wwv_flow_imp.id(1410170163910728)
,p_item_default=>'NATIVE_PLSQL'
,p_prompt=>'Type'
,p_source=>'ACTION_TYPE'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select d,',
'       r',
'  from (',
'         select wwv_flow_lang.system_message(''PROCESS.''|| name_with_prefix) as d,',
'               name_with_prefix as r',
'          from wwv_flow_native_plugins',
'         where plugin_type               = ''PROCESS TYPE''',
'           and supported_component_types like ''%APEX_APPL_AUTOMATION_ACTIONS%''',
'           and ( ( select wwv_flow_f4000_util.is_cloud',
'                     from sys.dual ) = ''Y''',
'                  or name != ''GEOCODING'' )',
'         union all',
'        select display_name || wwv_flow_lang.system_message(''PLUGIN.DISPLAY_NAME_POSTFIX'') as d,',
'               ''PLUGIN_'' || name     as r',
'          from wwv_flow_plugins',
'         where flow_id                   = to_number(:FB_FLOW_ID)',
'           and security_group_id         = to_number(:WORKSPACE_ID)',
'           and plugin_type               = ''PROCESS TYPE''',
'           and supported_component_types like ''%APEX_APPL_AUTOMATION_ACTIONS%''',
'       )',
' order by 1'))
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(452656722938220607)
,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_lov_display_extra=>'NO'
,p_help_text=>'Select the type of action.'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1409543908910722)
,p_name=>'P7022_REMOTE_PLSQL_CODE'
,p_item_sequence=>20
,p_item_plug_id=>wwv_flow_imp.id(90116067165448609)
,p_prompt=>'PL/SQL Code (executes at the REST Enabled SQL Service)'
,p_display_as=>'PLUGIN_COM.ORACLE.APEX.CODE_EDITOR'
,p_cSize=>80
,p_cMaxlength=>32767
,p_cHeight=>10
,p_field_template=>wwv_flow_imp.id(561549638722251517)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'    Provide the PL/SQL code to be executed. Column values from the automation query are available as bind variables, by column name, for example <strong>:EMPNO</strong>, <strong>:ENAME</strong> and so on. Additionally, APEX provides the following, ge'
||'neric bind variables:',
'</p>',
'<ul>',
'    <li><strong>APEX$AUTOMATION_ROW_PK</strong>: If a primary key column has been defined, this bind variable contains the primary key value.</li>',
'    <li><strong>APEX$AUTOMATION_ROW_NUM</strong>: For automations based on a query, this bind variable contains the current row number.</li>',
'    <li><strong>APEX$AUTOMATION_ERROR_ROWS</strong>: For automations based on a query, this bind variable contains the number of rows where the actions raised errors.</li>',
'    <li><strong>APEX$AUTOMATION_LASTRUN_ISO</strong>: Contains the timestamp of the <em>previous</em> automation run, in the <strong>YYYY-MM-DD"T"HH24:MI:SS.FF3TZH:TZM</strong> format.</li>        ',
'</ul>',
'<p style="padding-top: 10px">',
'    Note that the <strong>APEX_AUTOMATION</strong> package might not be available on the REST Enabled SQL service. For adding messages to the execution log (<strong>LOG_WARN</strong>, <strong>LOG_INFO</strong>, <strong>LOG_ERROR</strong>), create <em'
||'>another</em> Action being executed on the <em>Local Database.</em>',
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'PLSQL',
  'attribute_02', 'VARCHAR2',
  'attribute_03', 'Y',
  'attribute_04', 'Y',
  'attribute_05', 'P7022_REMOTE_SERVER_ID',
  'attribute_07', 'N')).to_clob
);
