,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'    Provide the PL/SQL code to be executed. Column values from the automation query are available as bind variables, by column name, for example <strong>:EMPNO</strong>, <strong>:ENAME</strong> and so on. Additionally, &PRODUCT_NAME. provides the fol'
||'lowing generic bind variables:',
'</p>',
'<ul>',
'    <li><strong>APEX$AUTOMATION_ROW_PK</strong>: If a primary key column has been defined, this bind variable contains the primary key value.</li>',
'    <li><strong>APEX$AUTOMATION_ROW_NUM</strong>: For automations based on a query, this bind variable contains the current row number.</li>',
'    <li><strong>APEX$AUTOMATION_ERROR_ROWS</strong>: For automations based on a query, this bind variable contains the number of rows, where at least the one of the actions raised errors.</li>',
'    <li><strong>APEX$AUTOMATION_LASTRUN_ISO</strong>: Contains the timestamp of the <em>previous</em> automation run, in the <strong>YYYY-MM-DD"T"HH24:MI:SS.FF3TZH:TZM</strong> format.</li>        ',
'</ul>',
'<p>',
'    ',
'</p>',
'<p>',
'    To write messages to the execution log, use the <strong>LOG_INFO</strong>, <strong>LOG_WARN</strong>, or <strong>LOG_ERROR</strong> procedures in the <strong>APEX_AUTOMATION</strong> package.',
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'PLSQL',
  'attribute_02', 'VARCHAR2',
  'attribute_03', 'Y',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
);
