wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(1380687782119094)
,p_validation_name=>'Is Valid Automation Query'
,p_validation_sequence=>40
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'--',
'-- validate_query also validates that required items actually contain',
'-- a value (e.g. Table Name for Query Type = TABLE)',
'return wwv_flow_exec_dev.validate_query(',
'           p_location                 => :P7031_LOCATION,',
'           p_remote_server_id         => case :P7031_LOCATION ',
'                                             when ''REMOTE'' then :P7031_REMOTE_SERVER_ID end,',
'           p_web_src_module_id        => case :P7031_LOCATION',
'                                             when ''WEB_SOURCE''      then :P7031_WEB_SRC_MODULE_ID end,',
'           p_array_column_id          => case :P7031_LOCATION',
'                                             when ''WEB_SOURCE''      then :P7031_WEB_SRC_ARRAY_COL_ID',
'                                             when ''DUALITY_VIEW''    then :P7031_DV_ARRAY_COL_ID',
'                                             when ''JSON_COLLECTION'' then :P7031_JSON_SOURCE_ARRAY_COL_ID end,',
'           p_document_source_id       => case :P7031_LOCATION',
'                                             when ''DUALITY_VIEW''    then :P7031_DUALITY_VIEW_ID',
'                                             when ''JSON_COLLECTION'' then :P7031_JSON_SOURCE_ID end,                                         ',
'           --  ',
'           p_table_owner              => case :P7031_LOCATION',
'                                             when ''LOCAL''  then :P7031_TABLE_OWNER ',
'                                             when ''REMOTE'' then :P7031_REMOTE_TABLE_OWNER end,',
'           p_table_name               => case :P7031_LOCATION',
'                                             when ''LOCAL''  then case ',
'                                                                    when :P7031_SOURCE_TYPE = ''GRAPH'' ',
'                                                                         then :P7031_GRAPH_NAME ',
'                                                                         else :P7031_TABLE_NAME ',
'                                                                end ',
'                                             when ''REMOTE'' then :P7031_REMOTE_TABLE_NAME end,',
'           p_where_clause             => null,',
'           p_order_by_clause          => null,',
'           p_match_clause             => case when :P7031_SOURCE_TYPE = ''GRAPH'' then :P7031_PQL_MATCH_CLAUSE end,',
'           p_columns_clause           => case when :P7031_SOURCE_TYPE = ''GRAPH'' then :P7031_PQL_COLUMNS_CLAUSE end,',
'           p_sql_query                => case :P7031_LOCATION',
'                                             when ''LOCAL''  then :P7031_SQL ',
'                                             when ''REMOTE'' then :P7031_REMOTE_SQL end,',
'           p_function_body_language   => ''PLSQL'',',
'           p_optimizer_hint           => null,',
'           --  ',
'           p_post_processing_type     => null,',
'           p_query_type               => case :P7031_LOCATION',
'                                             when ''REMOTE'' then ',
'                                                 case :P7031_REMOTE_SOURCE_TYPE',
'                                                     when ''QUERY'' then ''SQL''',
'                                                     else :P7031_REMOTE_SOURCE_TYPE end',
'                                             else',
'                                                 case :P7031_SOURCE_TYPE',
'                                                     when ''QUERY'' then ''SQL''',
'                                                     else :P7031_SOURCE_TYPE end',
'                                          end );'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_when_button_pressed=>wwv_flow_imp.id(1340421143119017)
,p_associated_item=>wwv_flow_imp.id(1347963424119036)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
