);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(2235495233684111)
,p_plug_name=>'Duality Views or JSON Sources'
,p_title=>'&P7100_SOURCE_TYPE_TITLE.'
,p_region_template_options=>'#DEFAULT#:a-IRR-region--noOuterBorders'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(646287526247383209)
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with messages as (',
'    select ( select wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_UP_TO_DATE'') from sys.dual ) up_to_date,',
'           ( select wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_NEEDS_REFRESH'') from sys.dual ) needs_refresh,',
'           ( select wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_UNKNOWN'') from sys.dual ) unknown_status,',
'           ( select wwv_flow_lang_dev.builder_message(''SUBSCRIBED_FROM.NONEXISTING_MASTER'') from sys.dual ) no_master',
'      from sys.dual )',
'select o.id,',
'       o.flow_id,',
'       o.name,',
'       o.document_source_type,',
'       case when o.remote_server_id is not null then',
'       (select r.name',
'          from wwv_remote_servers r',
'         where r.security_group_id = o.security_group_id ',
'           and r.id                = o.remote_server_id ) ',
'       end as remote_server_name,',
'          case when o.object_owner is not null then o.object_owner || ''.''  end',
'       || o.object_name as object_name,',
'       (select count( dpc.id ) ',
'          from wwv_flow_data_profiles     dp,',
'               wwv_flow_data_profile_cols dpc',
'         where dpc.security_group_id = dp.security_group_id',
'           and dp.security_group_id  = o.security_group_id',
'           and dpc.flow_id           = dp.flow_id',
'           and dp.flow_id            = o.flow_id',
'            --',
'           and dpc.data_profile_id   = dp.id',
'           and dp.id                 = o.data_profile_id ) as columns_cnt,',
'       case when o.reference_id is not null then',
'           coalesce ( to_char( master.flow_id ),',
'                       messages.no_master )',
'       end as subscribed_from,',
'       ( select case when count(*) > 0 then count(*) end',
'           from wwv_flow_document_sources sub',
'          where sub.reference_id      = o.id',
'            and sub.security_group_id = :WORKSPACE_ID ) as subscribers,',
'       case when o.reference_id is not null then',
'           case',
'               when master.version_scn = o.version_scn then',
'                   messages.up_to_date',
'               when master.version_scn != o.version_scn then',
'                   messages.needs_refresh',
'               else',
'                   messages.unknown_status',
'           end',
'       end subscription_status,           ',
'       o.last_updated_on',
'  from wwv_flow_document_sources    o,',
'       wwv_flow_document_sources    master,',
'       messages',
' where o.security_group_id     = master.security_group_id (+)',
'   and o.reference_id          = master.id                (+) ',
'    --',
'   and o.security_group_id     = :FLOW_SECURITY_GROUP_ID',
'   and o.flow_id               = :FB_FLOW_ID',
'   and o.document_source_type   in ( :P7100_SOURCE_TYPE, case when :P7100_SOURCE_TYPE = ''JSON_TABLE'' then ''JSON_COLLECTION'' end )'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
