,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select document_source_id,',
'       source_name,',
'       wwv_flow_lang.system_message(component_type_msg)  component_type_msg,',
'       component_id,',
'       page_id,',
'       case ',
'           when page_id is not null then',
'               wwv_flow_page_api.get_url (',
'                   p_page        => 4500,',
'                   p_items       => ''FB_FLOW_PAGE_ID'',',
'                   p_values      => page_id ) ',
'           when component_type_msg = ''AUTOMATIONS'' then',
'                wwv_flow_page_api.get_url (',
'                    p_page        => 7021,',
'                    p_clear_cache => 7021,',
'                    p_items       => ''P7021_ID'',',
'                    p_values      => component_id )            ',
'           when component_type_msg = ''SEARCH_CONFIG'' then',
'                wwv_flow_page_api.get_url (',
'                    p_page        => 3120,',
'                    p_clear_cache => 3120,',
'                    p_items       => ''P3120_ID'',',
'                    p_values      => component_id ) ',
'           when component_type_msg = ''SHARED DYNAMIC LOV'' then',
'                wwv_flow_page_api.get_url (',
'                    p_page        => 4111,',
'                    p_clear_cache => 4111,',
'                    p_items       => ''F4000_P4111_ID'',',
'                    p_values      => component_id )                              ',
'       end url,',
'       nvl( region_name, shared_component_name ) as component_name,',
'       series_name',
'  from wwv_flow_doc_src_usage_dev',
' where security_group_id = :FLOW_SECURITY_GROUP_ID',
'   and flow_id           = :FB_FLOW_ID',
'   and document_source_type   in ( :P7100_SOURCE_TYPE, case when :P7100_SOURCE_TYPE = ''JSON_TABLE'' then ''JSON_COLLECTION'' end )'))
,p_plug_source_type=>'NATIVE_IR'
