wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(2787302350432735)
,p_plug_name=>'About: JSON Sources'
,p_title=>'About'
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody:a-Region--sideRegion:a-Region--noBorder'
,p_plug_template=>wwv_flow_imp.id(174794400314076650)
,p_plug_display_sequence=>30
,p_plug_display_point=>'REGION_POSITION_03'
,p_plug_item_display_point=>'BELOW'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'    <strong>JSON Sources</strong> in &PRODUCT_NAME. consist of information about the owner and name ',
'    of a database table, which can be a <em>JSON Collection Table</em> or a plain table with columns containing',
'    JSON data. <em>JSON Collection Tables</em> are available in Oracle Database 23ai or higher. In addition,',
'    a <strong>Data Profile</strong> is maintained, which maps',
'    JSON attributes to <em>columns</em>, to be consumed by &PRODUCT_NAME. components.',
'</p>',
'<p> ',
'    You can define a JSON Source using the Local Database as well as using a REST Enabled SQL',
'    service. After picking the table and column to use, &PRODUCT_NAME. either determines the data',
'    profile from the actual data, or from an uploaded <em>JSON Schema</em> file.',
'</p>',
'<p>',
'    After creation, the JSON Source will be available to page components like <em>reports</em>, <em>charts</em>, ',
'    <em>forms</em> or others, as well as to shared components like <em>Lists Of Values</em>, <em>Automations</em>',
'    or others. The APEX_EXEC PL/SQL package allows programmatic access.',
'</p>',
'<p><a target="_blank" href="&SYSTEM_HELP_URL.">Learn More ...</a></p>'))
,p_plug_display_condition_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
,p_plug_display_when_condition=>'P7100_SOURCE_TYPE'
,p_plug_display_when_cond2=>'JSON_TABLE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
