,p_name=>'P8101_ACCESSIBILITY_CHECKS'
,p_item_sequence=>230
,p_item_plug_id=>wwv_flow_imp.id(1289320081911864300)
,p_item_default=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_result varchar2(2000);',
'begin',
'    for l_check in (',
'        select code',
'          from wwv_flow_advisor_checks',
'         where is_default = ''Y'' )',
'    loop',
'        l_result := case when l_result is not null then l_result||'':'' end||',
'                    l_check.code;',
'    end loop;',
'    --',
'    return l_result;',
'end;'))
,p_item_default_type=>'FUNCTION_BODY'
,p_item_default_language=>'PLSQL'
,p_prompt=>'Accessibility:'
,p_source=>'ADVISOR_CHECKS'
,p_source_type=>'PREFERENCE'
,p_display_as=>'NATIVE_CHECKBOX'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select wwv_flow_escape.html(description) as d,',
'       code as r',
'  from ( select nvl(chk.description, wwv_flow_lang.system_message(''ADVISOR.CHECK.DESC_''||chk.code)) as description,',
'                chk.code,',
'                chk.order_seq',
'           from wwv_flow_advisor_categories cat,',
'                wwv_flow_advisor_checks chk',
'          where cat.code        = ''ACCESSIBILITY''',
'            and chk.category_id = cat.id',
'            and chk.code       <> ''VERIFY_CLOB_PROPERTY''',
'            and chk.is_custom   = ''N''',
'            and (  chk.flow_id is null',
'                or chk.flow_id = :FB_FLOW_ID )',
'       )',
' order by order_seq'))
,p_label_alignment=>'ABOVE'
,p_field_template=>wwv_flow_imp.id(561549638722251517)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_escape_on_http_output=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<dl>',
'    <dt>Theme Style tested for accessibility</dt>',
'    <dd>Is your app using a Theme Style that has been tested for accessibility? Theme Styles that have not been accessibility tested may contain more issues, such as insufficient color contrast.</dd>',
'    <dt>Page has page title</dt>',
'    <dd>Does the page have a title? Meaningful page titles are important for accessibility, to help users understand the content and purpose of the current page. Note: Global pages, and pages with no regions are excluded from this check.</dd>',
'    <dt>Region has Row Header</dt>',
'    <dd>Regions that support row headers should have a column with the "Use as Row Header" attribute set to Yes.</dd>',
'    <dt>Chart type supports accessibility</dt>',
'    <dd>Are you using any older Chart Types that have limited accessibility support? These should instead be switched to using our new charts based on Oracle JET.</dd>',
'    <dt>Page item has label</dt>',
'    <dd>Does the item have a label defined? For example just defining the ''Value Placeholder'' text is not sufficient in labelling an item for accessibility.</dd>',
'    <dt>Page item does not cause an unexpected context change</dt>',
'    <dd>Some page item settings can cause an unexpected change of context for the user, such as select lists that submit the page after a value is selected. Unless the user has prior warning that this will happen, this represents an accessibility iss'
||'ue.</dd>',
'    <dt>Display Image item has image ALT text defined</dt>',
'    <dd>Display Image page items must provide text, or a column (depending on the Based On setting), that will be used as the image''s alternative text. This is important for accessibility, as without it some user''s may have no way of perceiving the c'
||'ontent of the image.</dd>',
'</dl>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'number_of_columns', '1')).to_clob
,p_multi_value_type=>'SEPARATED'
,p_multi_value_separator=>':'
);
