 p_id=>wwv_flow_imp.id(93814170672276749)
,p_plug_name=>'Dependency Entries'
,p_region_name=>'dbEntries'
,p_parent_plug_id=>wwv_flow_imp.id(75508925201601004)
,p_region_css_classes=>'a-DependencyBrowser-treeWrap a-DependencyEntries'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(208928010704475743)
,p_plug_display_sequence=>30
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with db_tree as (',
'    select search_text,',
'           sys_connect_by_path(node_id, '':'') || '':'' as db_entry_path',
'      from wwv_flow_obj_dep_entries',
'     start with parent_id is null',
'   connect by prior node_id = parent_id',
')',
'select node_id,',
'       parent_id,',
'       referenced_type,',
'       referenced_name,',
'       referenced_sub_name,',
'       node_label,',
'       icon_css, ',
'       sort_col,',
'       ''#action$do-activate?id=''||node_id||''&parent=''||parent_id||''&refType=''||referenced_type||',
'       ''&title=''||',
'       case ',
'       when referenced_name is not null and referenced_sub_name is not null then ',
'           referenced_name || ''.'' || node_label ',
'       else',
'           node_label',
'       end as link',
'  from wwv_flow_obj_dep_entries db_data',
' where :P8115_SEARCH is null',
'    or exists ( select null',
'                  from db_tree',
'                 where db_tree.search_text like ''%'' || upper(:P8115_SEARCH) || ''%'' ',
'                   and instr(db_tree.db_entry_path, '':'' || db_data.node_id || '':'') > 0 )'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_JSTREE'
,p_ajax_items_to_submit=>'P8115_SEARCH'
,p_plugin_init_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function(options) {',
'    options.makeNodeAdapter = function(data, types, hasIdentity) {',
'        var treeAdapter,',
'            // get the ids from session storage',
'            ids = apex.storage.getScopedSessionStorage( { prefix: "ORA_WWV_apex.builder.dependencyTree", useAppId: false} ).getItem("treeExpansionState");',
'        if ( ids ) {',
'            ids = ids.split(":");',
'        }',
'        treeAdapter = $.apex.treeView.makeDefaultNodeAdapter( data, types, hasIdentity, ids );',
'        return treeAdapter;',
'    }',
'    return options;',
'}'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'activate_node_link_with', 'S',
  'icon_css_class_column', 'ICON_CSS',
  'icon_type_css_class', 'a-Icon ',
  'link_column', 'LINK',
  'node_id_column', 'NODE_ID',
  'node_label_column', 'NODE_LABEL',
  'node_value_column', 'NODE_ID',
  'order_siblings_by', 'SORT_COL',
  'parent_key_column', 'PARENT_ID',
  'selected_node_page_item', 'P8115_ID',
  'start_tree_with', 'NULL',
  'tree_hierarchy', 'SQL',
  'tree_tooltip', 'N')).to_clob
);
