'       wwv_flow_escape.html(d.component_display_name) || '' &rarr; ''||',
'       d.property_group_name || '' &rarr; ''||',
'       d.property_name  as component_path',
'  from wwv_used_db_object_comp_props d',
' where d.flow_id = :FB_FLOW_ID',
'   and d.security_group_id = :WORKSPACE_ID',
'   and d.error_message is not null'))
