wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(93056611702204630)
,p_plug_name=>'Dependencies'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_region_attributes=>'style="display:none"'
,p_plug_template=>wwv_flow_imp.id(646287526247383209)
,p_plug_display_sequence=>30
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with db_details as ( ',
'    select to_char(d.used_db_object_id) as id,',
'           case when     d.used_db_object_parent_id is null',
'                     and d.is_system_owner          = ''Y'' then ',
'               ''SYSTEM_DEPENDENCIES/'' || d.referenced_type',
'           else',
'               nvl(to_char(d.used_db_object_parent_id), d.referenced_type)',
'           end as parent_id,',
'           case when     d.used_db_object_parent_id is null',
'                     and d.is_system_owner          = ''Y'' then',
'               ''Y''',
'           end as is_system_dependency,',
'           d.referenced_type, ',
'           nvl2( d.referenced_sub_name,',
'                 d.referenced_name || ''.'' || d.referenced_sub_name,',
'                 d.referenced_name ) as referenced_name, ',
'           d.referenced_owner,',
'           d.created as object_created,',
'           d.oracle_maintained,',
'           d.last_ddl_time,',
'           d.status as object_status,',
'           d.temporary as object_is_temporary,',
'           d.generated as object_is_generated,',
'           d.data_type,',
'           d.data_length,',
'           d.data_precision,',
'           d.data_scale,',
'           d.nullable,',
'           d.column_id,',
'           d.data_default,',
'           d.char_length,',
'           d.char_used,',
'           d.virtual_column,',
'           d.user_generated,',
'           d.default_on_null,',
'           d.identity_column,',
'           d.page_id,',
'           d.component_type_name,',
'           d.component_display_name,',
'           d.property_group_name,',
'           d.property_name,',
'           d.component_type_id, ',
'           d.component_id,',
'           d.parent_component_id,',
'           d.code_fragment, ',
'           d.edit_url, ',
'           d.is_shared_designer',
'      from wwv_used_db_obj_dependencies d',
'     where d.flow_id = :FB_FLOW_ID',
'       and d.security_group_id = :WORKSPACE_ID )',
'select d.id, ',
'       d.parent_id, ',
'       d.referenced_type, ',
'       d.referenced_name, ',
'       d.referenced_owner,',
'       d.object_created,',
'       d.oracle_maintained,',
'       d.last_ddl_time,',
'       d.object_status,',
'       d.object_is_temporary,',
'       d.object_is_generated,',
'       d.data_type,',
'       d.data_length,',
'       d.data_precision,',
'       d.data_scale,',
'       d.nullable,',
'       d.column_id,',
'       d.data_default,',
'       d.char_length,',
'       d.char_used,',
'       d.virtual_column,',
'       d.user_generated,',
'       d.default_on_null,',
'       d.identity_column,',
'       d.page_id, ',
'       d.component_type_name, ',
'       d.component_display_name,',
'       d.property_group_name, ',
'       d.property_name, ',
'       substr(d.code_fragment, 1, 16000) ||',
'       case when length(d.code_fragment) > 16000 then chr(10)||''...'' end',
'       as code_fragment, ',
'       nvl2(d.page_id, wwv_flow_lang.system_message(''DEP.PAGE'', d.page_id)||'' &rarr; '', null) || ',
'       d.component_type_name || '' &rarr; ''||',
'       wwv_flow_escape.html(d.component_display_name) || '' &rarr; ''||',
'       d.property_group_name || '' &rarr; ''||',
'       d.property_name as component_path,',
'       case ',
'       when d.page_id is not null then -- page designer',
'           wwv_flow_utilities.prepare_url(',
'               p_url           => ''f?p=4000:4500:'' || :APP_SESSION || ''::NO::'' ||',
'                                  ''FB_FLOW_ID,F4000_P1_FLOW,FB_FLOW_PAGE_ID:'' ||',
'                                  :FB_FLOW_ID || '','' || :FB_FLOW_ID || '','' || d.page_id || ',
'                                  ''#'' || d.component_type_id ||'':'' || d.component_id,',
'               p_checksum_type => ''SESSION'')',
'       when d.is_shared_designer = ''Y'' then -- workflow',
'           wwv_flow_utilities.prepare_url(',
'               p_url           => ''f?p=4000:9600:'' || :APP_SESSION || ''::NO::'' ||',
'                                  ''FB_FLOW_ID,F4000_P1_FLOW:'' ||',
'                                  :FB_FLOW_ID || '','' || :FB_FLOW_ID || ',
'                                  ''#'' || d.component_type_id || '':'' || d.component_id,',
'               p_checksum_type => ''SESSION'')      ',
'       else',
'           wwv_flow_utilities.fast_replace_manyf (',
'               p_srcstr => nvl(d.edit_url, ''f?p=4000:1:%session%:''),',
'               oldsub   => wwv_flow_t_varchar2(''%application_id%'',',
'                                               ''%page_id%'',',
'                                               ''%pk_value%'',',
'                                               ''%parent_pk_value%'',',
'                                               ''%session%''),',
'               newsub   => wwv_flow_t_varchar2(:FB_FLOW_ID,',
'                                               d.page_id,',
'                                               d.component_id,',
'                                               d.parent_component_id, ',
'                                               :APP_SESSION))              ',
'       end as link',
'from db_details d',
'      -- System Dependencies node',
'where (     :P8115_ID              = ''SYSTEM_DEPENDENCIES''',
'        and d.is_system_dependency = ''Y'' )',
'      -- Type node (e.g. "Tables")',
'   or (     nullif(:P8115_PARENT_ID, ''SYSTEM_DEPENDENCIES'') is null',
'        and d.parent_id                                     = :P8115_ID )',
'      -- Object node',
'   or (     :P8115_PARENT_ID is not null',
'        and d.id             = :P8115_ID )',
''))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P8115_ID,P8115_PARENT_ID,FB_FLOW_ID'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
,p_prn_page_footer_font_family=>'Helvetica'
,p_prn_page_footer_font_weight=>'normal'
,p_prn_page_footer_font_size=>'12'
,p_prn_header_bg_color=>'#EEEEEE'
,p_prn_header_font_color=>'#000000'
,p_prn_header_font_family=>'Helvetica'
,p_prn_header_font_weight=>'bold'
,p_prn_header_font_size=>'10'
,p_prn_body_bg_color=>'#FFFFFF'
,p_prn_body_font_color=>'#000000'
,p_prn_body_font_family=>'Helvetica'
,p_prn_body_font_weight=>'normal'
,p_prn_body_font_size=>'10'
,p_prn_border_width=>.5
,p_prn_page_header_alignment=>'CENTER'
,p_prn_page_footer_alignment=>'CENTER'
,p_prn_border_color=>'#666666'
);
