wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(103031559702250840)
,p_process_sequence=>30
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'init page items'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select id, last_dependency_analyzed_at, apex_util.get_since(last_dependency_analyzed_at), apex_util.get_since(nvl(last_updated_on, created_on))',
'  into :P8115_LAST_FLOW_ID, :P8115_LAST_SCAN, :P8115_SCANNED_ON, :P8115_MODIFIED_ON',
'  from wwv_flows ',
' where id = :FB_FLOW_ID',
'   and security_group_id = :WORKSPACE_ID;',
'',
'-- if a partial scan was run then the last_dependency_analyzed_at column could be null ',
'-- but there could be scan records',
'if :P8115_LAST_SCAN is null then',
'    begin',
'        select sysdate',
'          into :P8115_LAST_SCAN',
'          from wwv_flow_used_db_objects',
'         where flow_id = :FB_FLOW_ID',
'           and security_group_id = :WORKSPACE_ID',
'           and rownum = 1;',
'    exception ',
'        when no_data_found then ',
'            null;',
'    end;',
'end if;',
'',
'select count(*)',
'  into :P8115_ERROR_COUNT',
'  from wwv_used_db_object_comp_props',
' where flow_id = :FB_FLOW_ID',
'   and security_group_id = :WORKSPACE_ID',
'   and error_message is not null;',
'',
'-- determine the selected node. Do this after other items were cleared instead of using a computation',
'declare',
'    l_errors number;',
'begin',
'    if :P8115_ID is not null then ',
'        return;',
'    end if;',
'    ',
'    -- if there are errors then choose the errors node first',
'    begin',
'        select 0, ''ERROR''',
'          into :P8115_ID, :P8115_REFERENCED_TYPE',
'          from wwv_used_db_object_comp_props t',
'         where t.flow_id = :FB_FLOW_ID',
'           and t.security_group_id = :WORKSPACE_ID',
'           and t.error_message is not null',
'           and rownum = 1;',
'',
'        :P8115_TITLE := wwv_flow_lang_dev.builder_message(''DEP.ERROR_COUNT'', :P8115_ERROR_COUNT);',
'        return;',
'    exception ',
'        when no_data_found then ',
'            null; ',
'    end;',
'',
'    -- determine what are the top-level nodes and return the first one',
'    for c in (',
'    select distinct',
'           case when t.is_system_owner = ''Y'' then ''SYSTEM_DEPENDENCIES/'' end ||',
'           t.referenced_type as node_id,',
'           instr(''TABLE,VIEW,SEQUENCE,TYPE,PACKAGE,PROCEDURE,FUNCTION,NESTED TABLE,MVIEW,SYNONYM,SCHEMA'',',
'                 t.referenced_type) as sort_col, ',
'           t.referenced_type, t.is_system_owner',
'      from wwv_used_db_objects t',
'     where t.parent_id is null',
'       and t.flow_id = :FB_FLOW_ID',
'       and t.security_group_id = :WORKSPACE_ID',
'       and t.usage_count > 0',
'     order by t.is_system_owner, sort_col',
'    ) loop',
'        :P8115_ID              := c.node_id;',
'        :P8115_REFERENCED_TYPE := c.referenced_type;',
'        :P8115_TITLE           := wwv_flow_lang_dev.builder_message(''DEP.''||replace(c.referenced_type, '' '', ''_'')||''_PLURAL'');',
'        return;',
'    end loop;',
'',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>103031559702250840
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(11643238903681062)
,p_process_sequence=>40
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'getCurrentStatus'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_percent_comp    number;',
'    l_execution wwv_flow_process_bg_api.t_execution;',
'begin',
'    l_execution := wwv_flow_process_bg.get_execution(',
'        p_security_group_id => wwv_flow_security.g_curr_flow_security_group_id,',
'        p_application_id    => wwv_flow_security.g_flow_id,',
'        p_execution_id      => :P8115_EXEC_ID ); ',
'',
'    l_percent_comp := nvl(l_execution.sofar, 1) / nvl(l_execution.totalwork, greatest(100000, l_execution.sofar)) * 100;',
'',
'    wwv_flow_json.open_object;',
'    wwv_flow_json.open_array(''items'');',
'    wwv_flow_json.open_object;',
'    wwv_flow_json.write(''id'', ''P8115_STATE'');',
'    wwv_flow_json.write(''value'', l_execution.state);',
'    wwv_flow_json.close_object;',
'    wwv_flow_json.open_object;',
'    wwv_flow_json.write(''id'', ''P8115_MESSAGE'');',
'    wwv_flow_json.write(''value'', l_execution.last_status_message);',
'    wwv_flow_json.close_object;',
'    wwv_flow_json.open_object;',
'    wwv_flow_json.write(''id'', ''P8115_PERCENT'');',
'    wwv_flow_json.write(''value'', trunc(l_percent_comp));',
'    wwv_flow_json.close_object;',
'    wwv_flow_json.close_array;',
'    wwv_flow_json.close_object;',
'end;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>11643238903681062
);
end;
