,p_item_plug_id=>wwv_flow_imp.id(110814830114933628)
,p_item_default=>'N'
,p_prompt=>'Session State Protection:'
,p_source=>'select PAGE_PROTECTION_ENABLED_Y_N from wwv_flows where id = :fb_flow_id'
,p_source_type=>'QUERY'
,p_display_as=>'NATIVE_DISPLAY_ONLY'
,p_named_lov=>'ENABLED_DISABLED_RETURNS_Y_OR_N'
,p_lov=>'.'||wwv_flow_imp.id(91439803955181562)||'.'
,p_cSize=>30
,p_cMaxlength=>2000
,p_cHeight=>1
,p_cAttributes=>'nowrap="nowrap"'
,p_tag_css_classes=>'fielddatabold'
,p_label_alignment=>'RIGHT'
,p_field_template=>wwv_flow_imp.id(561547836135222071)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_escape_on_http_input=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Indicates whether Session State Protection is enabled or disabled. When enabled, this feature, uses the <i>Page Access Protection</i> page attributes and the <i>Session State Protection</i> item attributes in conjunction with checksums positioned in '
||'"f?p=" URLs. The feature prevents URL tampering and unauthorized access to and alteration of session state. ',
'<p />',
'When this feature is disabled, the page and item attributes related to session state protection are ignored and checksums are not included checksums in generated "f?p=" URLs.'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'based_on', 'LOV',
  'format', 'PLAIN',
  'send_on_page_submit', 'N',
  'show_line_breaks', 'N')).to_clob
);
