wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3201962690436619)
,p_plug_name=>'Task Definitions'
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody'
,p_plug_template=>wwv_flow_imp.id(174794400314076650)
,p_plug_display_sequence=>10
,p_plug_display_point=>'REGION_POSITION_03'
,p_plug_item_display_point=>'BELOW'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'    <strong>Task Definitions</strong> define the properties of a human task.',
'    They are used to create task instances and then perform the appropriate',
'    action (examples are approving or rejecting the task instances. Tasks can',
'    also be claimed, released, delegated, canceled.',
'</p>',
'<p>',
'    <strong>Task Definition Participants</strong> define the participants of',
'    a human task who can act on the task. Participants can be either of type',
'    <strong> Potential Owner </strong> or <strong> Business Administrator',
'    </strong>.',
'</p>',
'<p>',
'    <strong>Task Definition Parameters</strong> define the parameters of a',
'    human task. These are typically attributes of a system of records for',
'    which the task has been defined. They constitute the payload of the task.',
'</p>',
'<p>',
'    <strong>Task Definition Actions</strong> fire once for an event performed',
'    on the task. Events can be:',
'</p>',
'<ul>',
'    <li><strong>Claim</strong></li>',
'    <li><strong>Complete</strong></li>',
'    <li><strong>Delegate</strong></li>',
'    <li><strong>Update Comment</strong></li>',
'    <li><strong>Update Priority</strong></li>',
'    <li><strong>Update Parameter</strong></li>',
'    <li><strong>Release</strong></li>',
'    <li><strong>Cancel</strong></li>',
'    <li><strong>Create</strong></li>',
'    <li><strong>Request Information</strong></li>',
'    <li><strong>Submit Information</strong></li>',
'    <li><strong>Before Expire</strong></li>',
'    <li><strong>Expire</strong></li>',
'</ul>',
'<p>',
'    <a target="_blank" href="&SYSTEM_HELP_URL.">Learn More ...</a>',
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
