wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(1705428619273907)
,p_validation_name=>'Due On Interval must be valid ISO or SQL interval format'
,p_validation_sequence=>30
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_due_on timestamp := null;',
'begin',
'    if :P9502_DUE_ON_TYPE is not null and :P9502_DUE_ON_TYPE != ''INTERVAL'' then',
'        return true;',
'    else   ',
'        -- Due On Interval should not be null or negative',
'        if :P9502_DUE_ON_TYPE is not null ',
'            and (:P9502_DUE_ON_INTERVAL is null',
'            or :P9502_DUE_ON_INTERVAL like ''-%'') then ',
'            return false;',
'        end if;',
'        select systimestamp + to_dsinterval(:P9502_DUE_ON_INTERVAL) ',
'          into l_due_on ',
'          from sys.dual;',
'    end if;      ',
'    return true;',
'exception',
'    when others then',
'    return false;',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>'Invalid Interval format.'
,p_validation_condition=>'CREATE:SAVE'
,p_validation_condition_type=>'REQUEST_IN_CONDITION'
,p_associated_item=>wwv_flow_imp.id(2109125538618234)
,p_error_display_location=>'INLINE_WITH_FIELD'
);
