,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    wwv_flow_approval_dev.create_task_details_forms (',
'        p_flow_id              => :FB_FLOW_ID,',
'        p_details_page_id      => :P9502_DETAILS_LINK_PAGE_ID,',
'        p_task_definition_name => :P9502_NAME,',
'        p_task_type            => :P9502_TASK_TYPE',
'    );',
'',
'    :P9502_DETAILS_LINK_TARGET :=',
'        -- the funny text concatenation is needed to prevent placeholder',
'        -- replacements by the APEX engine',
'        ''f?p=&'' || ''APP_ID.:'' || :P9502_DETAILS_LINK_PAGE_ID ||',
'        '':&'' || ''SESSION.::&'' || ''DEBUG.:RP,''  || :P9502_DETAILS_LINK_PAGE_ID || ',
'        '':P'' || :P9502_DETAILS_LINK_PAGE_ID || ''_TASK_ID:&'' || ''TASK_ID.'';',
'',
'    update wwv_flow_task_defs ',
'       set details_link_target = :P9502_DETAILS_LINK_TARGET',
'     where id                  = :P9502_ID',
'       and flow_id             = :FB_FLOW_ID',
'       and security_group_id   = wwv_flow_security.g_security_group_id;',
'',
'    :P9502_DETAILS_LINK_PAGE_ID := null;',
'end;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>':P9502_DETAILS_LINK_PAGE_ID > 0'
