,p_item_plug_id=>wwv_flow_imp.id(3379750715607841)
,p_item_source_plug_id=>wwv_flow_imp.id(3379750715607841)
,p_prompt=>'On Event'
,p_source=>'ON_EVENT'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'TASK_ACTION_ON_EVENTS'
,p_lov=>'.'||wwv_flow_imp.id(2058881135907033)||'.'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(452656722938220607)
,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'The event for which the action will be executed. Actions can be executed for the following events on the task',
'<dl>',
'    <dt>Claim</dt>',
'    <dd>When the task is claimed by a potential owner. Claiming a task transitions the task from Unassigned to Assigned State.</dd>',
'    <dt>Complete</dt>',
'    <dd>When the task is being completed. In addition, for an Approval Task you can choose if the action occurs only on an outcome of Approved or Rejected.</dd>',
'    <dt>Delegate</dt>',
'    <dd>When the task is being delegated to another potential owner of the task.</dd>',
'    <dt>Update Comment</dt>',
'    <dd>When a comment is added to the task.</dd>',
'    <dt>Update Priority</dt>',
'    <dd>When the priority of the task is being updated.</dd>',
'    <dt>Update Parameter</dt>',
'    <dd>When parameters of the task are being updated.</dd>',
'    <dt>Release</dt>',
'    <dd>When the task is being released. This transitions the task from state Assigned to Unassigned.</dd>',
'    <dt>Cancel</dt>',
'    <dd>When the task is being canceled, thus showing no more interest in the task.</dd>',
'    <dt>Create</dt>',
'    <dd>When the task is being created.</dd>',
'    <dt>Request Information</dt>',
'    <dd>When information by the initiator of the task is being requested.</dd>',
'    <dt>Submit Information</dt>',
'    <dd>When information by the initiator is submitted to the requester.</dd>',
'    <dt>Before Expire</dt>',
'    <dd>Before the task due date is reached and the task is about to expire. An ISO/SQL interval must be specified.</dd>',
'    <dt>Expire</dt>',
'    <dd>When the task due date is reached and the task expires.</dd>',
' </dl>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
