wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1974380900697179)
,p_name=>'P9506_LOCAL_CODE'
,p_item_sequence=>20
,p_item_plug_id=>wwv_flow_imp.id(92085503084145721)
,p_prompt=>'Code'
,p_display_as=>'PLUGIN_COM.ORACLE.APEX.CODE_EDITOR'
,p_cSize=>80
,p_cMaxlength=>32767
,p_cHeight=>10
,p_field_template=>wwv_flow_imp.id(561549638722251517)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'    Provide the PL/SQL code to be executed. Column values from the task definition action query are available as bind variables, by column name, for example <strong>:EMPNO</strong>, <strong>:ENAME</strong> and so on. Additionally, APEX provides the f'
||'ollowing, generic bind variables:',
'</p>',
'<ul>',
'    <li><strong>APEX$TASK_PK</strong>: If a primary key column has been defined, this bind variable contains the primary key value.</li>',
'    <li><strong>APEX$TASK_ID</strong>: This bind variable contains the id of the task for which this action is defined.</li>',
'    <li><strong>APEX$TASK_SUBJECT</strong>: This bind variable contains the subject of the task for which this action is defined.</li>',
'    <li><strong>APEX$TASK_STATE</strong>: This bind variable contains the current state of the task for which this action is defined.</li>',
'    <li><strong>APEX$TASK_OUTCOME</strong>: This bind variable contains the outcome of the task for which this action is defined.This variable is populated only for tasks in <strong>Completed</strong> state.</li>',
'    <li><strong>APEX$TASK_CREATED_ON</strong>: Contains the timestamp of the task creation, in the <strong>YYYY-MM-DD"T"HH24:MI:SS.FF3TZH:TZM</strong> format.</li>        ',
'    <li><strong>APEX$TASK_INITIATOR</strong>: Contains the user who has initiated the task. This value defaults to the logged-in user if not explicitly specified as part of the <strong>Human Task - Create</strong> Page Process type.</li>        ',
'    <li><strong>APEX$TASK_DUE_ON</strong>: Contains the timestamp of when this task is due , in the <strong>YYYY-MM-DD"T"HH24:MI:SS.FF3TZH:TZM</strong> format.</li>        ',
'    <li><strong>APEX$TASK_OWNER</strong>: Contains the user to whom the task is currently assigned.</li>',
'    <li> The parameters for the task definition are also available as bind variables.</li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'PLSQL',
  'attribute_02', 'VARCHAR2',
  'attribute_03', 'Y',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
);
