wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(1411441402331404)
,p_validation_name=>'Cannot delete used Generative AI Service'
,p_validation_sequence=>40
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select s.id',
'  from wwv_remote_servers s ',
' where s.security_group_id  = :FLOW_SECURITY_GROUP_ID',
'   and s.id                 = :P9801_ID',
'   and s.server_type        = ''GENERATIVE_AI''',
'   and (    exists ( select 1',
'                       from wwv_flows f',
'                      where f.ai_remote_server_id   = s.id',
'                        and f.security_group_id     = s.security_group_id )',
'         or exists ( select 1',
'                       from wwv_flow_page_plugs f',
'                      where f.ai_remote_server_id = s.id',
'                        and f.security_group_id      = s.security_group_id ) ',
'         or exists ( select 1',
'                       from wwv_flow_step_items f',
'                      where f.ai_remote_server_id = s.id',
'                        and f.security_group_id      = s.security_group_id )',
'         or exists ( select 1',
'                       from wwv_flow_page_da_actions f',
'                      where f.ai_remote_server_id = s.id',
'                        and f.security_group_id      = s.security_group_id ) )'))
,p_validation_type=>'NOT_EXISTS'
,p_error_message=>'Generative AI Service is in use and cannot be deleted.'
,p_when_button_pressed=>wwv_flow_imp.id(3249256613301102)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(1411631855331406)
,p_validation_name=>'Only one default for App Builder on CREATE'
,p_validation_sequence=>50
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_count number;',
'begin',
'    select count(id)',
'      into l_count',
'      from wwv_remote_servers',
'     where ai_is_builder_service        = ''Y''',
'       and server_type                  = ''GENERATIVE_AI''',
'       and id                          != :P9801_ID',
'       and security_group_id            = :FLOW_SECURITY_GROUP_ID;',
'    ',
'    return (    ((l_count  = 0) and (:P9801_AI_IS_BUILDER_SERVICE = ''Y''))',
'             or ((l_count <= 1) and (:P9801_AI_IS_BUILDER_SERVICE = ''N'')));',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>'Only one Generative AI Service can be configured to be used by App Builder.'
,p_validation_condition=>':REQUEST in ( ''CREATE'', ''SAVE'' ) and :P9801_AI_IS_BUILDER_SERVICE = ''Y'''
,p_validation_condition2=>'PLSQL'
,p_validation_condition_type=>'EXPRESSION'
,p_associated_item=>wwv_flow_imp.id(2001134026749011)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
