,p_process_name=>'Distribute Page Items'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_oci_attributes   sys.json_object_t;',
'    l_oci_serving_mode sys.json_object_t;',
'begin',
'    if :P9801_AI_PROVIDER_TYPE = ''OCI_GENAI'' then',
'        :P9801_OCI_CREDENTIAL_ID := :P9801_CREDENTIAL_ID;',
'        begin',
'            l_oci_attributes := sys.json_object_t.parse(:P9801_AI_ATTRIBUTES);',
'            if l_oci_attributes is not null then',
'             :P9801_OCI_COMPARTMENT_ID := l_oci_attributes.get_string(''compartmentId'');',
'                l_oci_serving_mode        := l_oci_attributes.get_object(''servingMode'');',
'                if l_oci_serving_mode is not null then',
'                    :P9801_OCI_MODEL_ID   := l_oci_serving_mode.get_string(''modelId'');',
'                end if;',
'            end if; ',
'        exception',
'            when others then',
'                -- Set model to default model and leave compartment empty',
'                :P9801_OCI_MODEL_ID := wwv_flow_ai_dev.get_default_model(',
'                    p_provider_type => :P9801_AI_PROVIDER_TYPE);',
'        end;',
'    else',
'         :P9801_APIKEY_CREDENTIAL_ID := :P9801_CREDENTIAL_ID;',
'    end if;',
'end;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>2384839101262621
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(8722628638008625)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'TestGenAIConn'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_response   wwv_flow_ai.t_response;',
'    l_credential number;',
'    l_model      varchar2(255);',
'begin',
'    case ',
'        when apex_application.g_x05 = wwv_flow_ai.c_provider_ocigenai ',
'        then l_credential := apex_application.g_x14;',
'             l_model      := apex_application.g_x15;',
'        else l_credential := apex_application.g_x04; ',
'             l_model      := apex_application.g_x06;',
'    end case;',
'    l_response := wwv_flow_ai.get_connection_status (',
'        p_name                  => apex_application.g_x01,',
'        p_static_id             => apex_application.g_x02,',
'        p_base_url              => apex_application.g_x03,',
'        p_credential_id         => l_credential,',
'        p_ai_provider_type      => apex_application.g_x05,',
'        p_ai_model_name         => l_model,',
'        p_ai_http_headers       => apex_application.g_x07,',
'        p_ai_attributes         => apex_application.g_x08,',
'        --',
'        p_new_api_key           => apex_application.g_x09,',
'        p_new_oci_userid        => apex_application.g_x10,',
'        p_new_oci_tenancyid     => apex_application.g_x11,',
'        p_new_oci_privatekey    => apex_application.g_x12,',
'        p_new_oci_fingerprint   => apex_application.g_x13 );',
'    -- Open a new JSON object',
'    apex_json.open_object();',
'    -- Write a key-value pair to the JSON object',
'    apex_json.write( ''status'', l_response.http_status_code );',
'    apex_json.write( ''message'', l_response.text );',
'    -- Close the JSON object',
'    apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>8722628638008625
);
