,p_plug_item_display_point=>'BELOW'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Vector providers are configured to convert <strong>text</strong> into an <strong>embedding</strong>.',
'The functionality can be covered by an <strong>AI service</strong>, but also locally by an <strong>ONNX model</strong> in the database or a user-defined <strong>PL/SQL function</strong>.',
'</p>',
'<p>The <code>APEX_AI</code> public API contains a function for using a Vector Provider to get the embedding for a text.</p>',
'<p>Vector Providers are stored at the workspace level and therefore are visible in all applications. When you export an application, used Vector Providers are added to the export file. When you import the application into another workspace, &PRODUCT_'
||'NAME. checks whether the target workspace already contains Vector Providers with the same <strong>static ID</strong>. If a Vector Provider already exists, the application uses it. Otherwise the Vector Provider from the import file are created in the '
||'target workspace.</p>',
'<p><a href="&SYSTEM_HELP_URL." rel="noopener noreferrer" target="_blank">Learn More ...</a></p>'))
,p_plug_display_condition_type=>'EXPRESSION'
,p_plug_display_when_condition=>'nvl(#OWNER#.wwv_flow_preferences.get_preference(''FP_PREF_SHOW_INFORMATION''),''YES'') = ''YES'''
,p_plug_display_when_cond2=>'PLSQL'
,p_ai_enabled=>false
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
