wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(1882178299116059)
,p_event_id=>wwv_flow_imp.id(1881633637116057)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_name=>'Set Base URL and Attributes'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    :P9811_BASE_URL := wwv_flow_ai_dev.get_base_url(',
'        p_provider_type      => :P9811_AI_PROVIDER_TYPE,',
'        p_oci_region         => :P9811_OCI_REGION);',
'    ',
'    :P9811_AI_ATTRIBUTES := wwv_flow_ai_dev.get_mandatory_attributes(',
'        p_provider_type      => :P9811_AI_PROVIDER_TYPE,',
'        p_oci_compartment_id => :P9811_OCI_COMPARTMENT_ID,',
'        p_oci_model_id       => :P9811_OCI_MODEL_ID);',
'',
'    if :P9811_AI_PROVIDER_TYPE != wwv_flow_ai.c_provider_ocigenai then',
'        :P9811_AI_MODEL_NAME := wwv_flow_ai_dev.get_default_model(',
'            p_provider_type => :P9811_AI_PROVIDER_TYPE);',
