'            if l_oci_attributes is not null then',
'             :P9811_OCI_COMPARTMENT_ID := l_oci_attributes.get_string(''compartmentId'');',
'                l_oci_serving_mode        := l_oci_attributes.get_object(''servingMode'');',
'                if l_oci_serving_mode is not null then',
'                    :P9811_OCI_MODEL_ID   := l_oci_serving_mode.get_string(''modelId'');',
'                end if;',
'            end if; ',
'        exception',
'            when others then',
'                -- Set model to default model and leave compartment empty',
'                :P9811_OCI_MODEL_ID := wwv_flow_ai_dev.get_default_model(',
'                    p_provider_type => :P9811_AI_PROVIDER_TYPE);',
'        end;',
'    else',
'         :P9811_APIKEY_CREDENTIAL_ID := :P9811_CREDENTIAL_ID;',
'    end if;',
'end;',
''))
